export const rasberProductPages = {
  "sliding-inclinometer": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Sliding Inclinometer</span>\n    </div>\n    <h1>Sliding Inclinometer</h1>\n    <p class=\"sub\">\n      A smart, Bluetooth-enabled portable deep-displacement monitoring system. One operator surveys a 30&nbsp;m borehole in 5 minutes — international-grade accuracy in a 7.5&nbsp;kg package.\n      \n    </p>\n    <div class=\"model\">SCIS SERIES · CLASS A / CLASS B</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/sliding-inclinometer/sliding-inclinometer-system.jpg\" alt=\"SCIS sliding inclinometer system: probe, control cable and Bluetooth cable reel\" width=\"1000\" height=\"704\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Measure deep horizontal displacement, distributed by depth\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          The SCIS sliding inclinometer measures how the horizontal displacement of subsurface soil or structures is distributed with depth. A proprietary auto-measurement mode, smart Bluetooth-app interaction and real-time cloud sync completely reinvent the traditional two-person survey workflow.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Single-operator surveys</b><p>Proprietary auto-measurement mode: a 30 m borehole in 5 minutes.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Bluetooth app + cloud sync</b><p>Data flows from field to cloud in real time — zero manual handling.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Built for harsh sites</b><p>IP68 stainless-steel probe rated to 3 MPa (300 m water depth).</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.005 mm</div><div class=\"name\">Resolution / 500 mm</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">≤±1.5 mm</div><div class=\"name\">System Accuracy / 30 m</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">IP68 · 3 MPa</div><div class=\"name\">Ingress Protection</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">80 h</div><div class=\"name\">Battery Life</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Measurement principle</div>\n      <h2>How a Sliding Inclinometer Works</h2>\n      <p>\n        The casing is permanently installed in a vertical borehole through the zone of expected movement, with its bottom keyed into a stable stratum as the datum. The probe's gravity-referenced MEMS accelerometer reads the inclination θ at every 0.5&nbsp;m step; summing each segment's horizontal component from the bottom up rebuilds the full displacement profile.\n        \n      </p>\n    </div>\n\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 420\" role=\"img\" aria-label=\"Sliding inclinometer measurement principle diagram\">\n        <!-- ground surface -->\n        <line x1=\"40\" y1=\"70\" x2=\"380\" y2=\"70\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <line x1=\"58\" y1=\"70\" x2=\"70\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"90\" y1=\"70\" x2=\"102\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"122\" y1=\"70\" x2=\"134\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"154\" y1=\"70\" x2=\"166\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"258\" y1=\"70\" x2=\"270\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"290\" y1=\"70\" x2=\"302\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"322\" y1=\"70\" x2=\"334\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <line x1=\"354\" y1=\"70\" x2=\"366\" y2=\"58\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <!-- stable stratum -->\n        <rect x=\"70\" y=\"345\" width=\"280\" height=\"46\" rx=\"4\" class=\"svg-fill-soft\"/>\n        <!-- casing -->\n        <line x1=\"196\" y1=\"64\" x2=\"196\" y2=\"378\" class=\"svg-stroke-soft\" stroke-width=\"2.5\"/>\n        <line x1=\"224\" y1=\"64\" x2=\"224\" y2=\"378\" class=\"svg-stroke-soft\" stroke-width=\"2.5\"/>\n        <!-- vertical (gravity) reference -->\n        <line x1=\"210\" y1=\"104\" x2=\"210\" y2=\"302\" class=\"svg-stroke-soft\" stroke-width=\"1.4\" stroke-dasharray=\"5 5\"/>\n        <!-- probe -->\n        <g transform=\"translate(210 215) rotate(10)\">\n          <line x1=\"0\" y1=\"-112\" x2=\"0\" y2=\"72\" class=\"svg-stroke\" stroke-width=\"1.4\" stroke-dasharray=\"5 5\"/>\n          <rect x=\"-6\" y=\"-40\" width=\"12\" height=\"80\" rx=\"6\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"2\"/>\n          <circle cx=\"6\" cy=\"-30\" r=\"4\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.8\"/>\n          <circle cx=\"-6\" cy=\"30\" r=\"4\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.8\"/>\n        </g>\n        <!-- angle arc + theta -->\n        <path d=\"M 210 135 A 80 80 0 0 1 223.9 136.2\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <text x=\"212.5\" y=\"130\" font-size=\"14\" class=\"svg-text-accent\">θ</text>\n        <!-- L·sin(theta) offset arrow -->\n        <line x1=\"210\" y1=\"112\" x2=\"222\" y2=\"112\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <path d=\"M 219 108.8 L 225.5 112 L 219 115.2\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <text x=\"234\" y=\"116\" font-size=\"13\" class=\"svg-text-accent\">L·sin θ</text>\n        <!-- L bracket (wheel spacing) -->\n        <path d=\"M 240 186 L 248 186 L 248 244 L 240 244\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <text x=\"256\" y=\"211\" font-size=\"13\" class=\"svg-text-accent\">L = 0.5 m</text>\n        <text x=\"256\" y=\"228\" font-size=\"11.5\" class=\"svg-text lang-en\">step interval</text>\n        <text x=\"256\" y=\"228\" font-size=\"11.5\" class=\"svg-text lang-zh\">测量步距</text>\n        <!-- labels -->\n        <text x=\"40\" y=\"56\" font-size=\"13\" class=\"svg-text lang-en\">Ground surface</text>\n        <text x=\"40\" y=\"56\" font-size=\"13\" class=\"svg-text lang-zh\">地表</text>\n        <line x1=\"226\" y1=\"90\" x2=\"246\" y2=\"90\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <text x=\"250\" y=\"94\" font-size=\"13\" class=\"svg-text lang-en\">70 mm grooved casing</text>\n        <text x=\"250\" y=\"94\" font-size=\"13\" class=\"svg-text lang-zh\">70mm 导槽测斜管</text>\n        <line x1=\"194\" y1=\"226\" x2=\"186\" y2=\"226\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <text x=\"182\" y=\"230\" font-size=\"13\" text-anchor=\"end\" class=\"svg-text lang-en\">Probe (MEMS)</text>\n        <text x=\"182\" y=\"230\" font-size=\"13\" text-anchor=\"end\" class=\"svg-text lang-zh\">探头（MEMS）</text>\n        <line x1=\"208\" y1=\"298\" x2=\"194\" y2=\"312\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n        <text x=\"190\" y=\"320\" font-size=\"13\" text-anchor=\"end\" class=\"svg-text lang-en\">Vertical reference (gravity)</text>\n        <text x=\"190\" y=\"320\" font-size=\"13\" text-anchor=\"end\" class=\"svg-text lang-zh\">铅垂基准（重力）</text>\n        <text x=\"40\" y=\"412\" font-size=\"13\" class=\"svg-text lang-en\">Bottom keyed into stable stratum (datum)</text>\n        <text x=\"40\" y=\"412\" font-size=\"13\" class=\"svg-text lang-zh\">底端嵌入稳定地层（基准）</text>\n        <!-- accumulation column -->\n        <text x=\"470\" y=\"104\" font-size=\"13\" text-anchor=\"middle\" class=\"svg-text-strong lang-en\">Cumulative profile D(z)</text>\n        <text x=\"470\" y=\"104\" font-size=\"13\" text-anchor=\"middle\" class=\"svg-text-strong lang-zh\">管形曲线 D(z)</text>\n        <line x1=\"460\" y1=\"120\" x2=\"460\" y2=\"350\" class=\"svg-stroke-soft\" stroke-width=\"1.4\" stroke-dasharray=\"5 5\"/>\n        <path d=\"M 460 350 C 455 300 463 268 474 240 C 488 205 496 168 498 125\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2.5\"/>\n        <circle cx=\"460\" cy=\"350\" r=\"3.5\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n        <line x1=\"460\" y1=\"250\" x2=\"468\" y2=\"250\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <path d=\"M 465 246.8 L 471 250 L 465 253.2\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <line x1=\"460\" y1=\"200\" x2=\"486\" y2=\"200\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <path d=\"M 483 196.8 L 489 200 L 483 203.2\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <line x1=\"460\" y1=\"150\" x2=\"493\" y2=\"150\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <path d=\"M 490 146.8 L 496 150 L 490 153.2\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.4\"/>\n        <line x1=\"425\" y1=\"345\" x2=\"425\" y2=\"138\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <path d=\"M 420.5 146 L 425 134 L 429.5 146\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <text x=\"419\" y=\"126\" font-size=\"15\" class=\"svg-text-accent\">Σ</text>\n        <text x=\"404\" y=\"372\" font-size=\"12.5\" class=\"svg-text lang-en\">datum · D = 0</text>\n        <text x=\"404\" y=\"372\" font-size=\"12.5\" class=\"svg-text lang-zh\">基准 · D = 0</text>\n        <!-- formula block -->\n        <text x=\"552\" y=\"192\" font-size=\"18\" class=\"svg-text-accent\">D(z) = Σ L · sin θ</text>\n        <text x=\"552\" y=\"224\" font-size=\"12.5\" class=\"svg-text lang-en\">Horizontal offsets summed</text>\n        <text x=\"552\" y=\"224\" font-size=\"12.5\" class=\"svg-text lang-zh\">各段水平分量自孔底基准</text>\n        <text x=\"552\" y=\"242\" font-size=\"12.5\" class=\"svg-text lang-en\">upward from the bottom datum.</text>\n        <text x=\"552\" y=\"242\" font-size=\"12.5\" class=\"svg-text lang-zh\">向上逐段累加。</text>\n        <text x=\"552\" y=\"272\" font-size=\"12.5\" class=\"svg-text lang-en\">Later surveys minus the first</text>\n        <text x=\"552\" y=\"272\" font-size=\"12.5\" class=\"svg-text lang-zh\">后续测量与首测基准相减，</text>\n        <text x=\"552\" y=\"290\" font-size=\"12.5\" class=\"svg-text lang-en\">baseline = displacement change.</text>\n        <text x=\"552\" y=\"290\" font-size=\"12.5\" class=\"svg-text lang-zh\">即得位移变化量。</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        The probe slides up the grooved casing in 0.5&nbsp;m steps; each segment contributes a horizontal offset L·sin&nbsp;θ, summed from the bottom datum into the profile D(z). Probe tilt exaggerated for clarity.\n        \n      </div>\n    </div>\n\n    <div class=\"grid grid-2\" style=\"margin-top:36px;\">\n      <ul class=\"feature-list reveal\">\n        <li><span class=\"fi\">1</span><div><b>Pass 1 — A0 direction</b><p>The A-axis positive guide wheels run in the A0 groove; reading bottom-up at every 0.5&nbsp;m records R<sub>A0</sub> = sin&nbsp;θ + b, where b is the sensor's zero offset — from residual assembly stress, circuit bias and temperature drift.</p></div></li>\n        <li><span class=\"fi\">2</span><div><b>Pass 2 — rotate 180°</b><p>The probe is withdrawn, rotated 180° about its axis so the same wheels run in the A180 groove, and the survey is repeated: R<sub>A180</sub> = −sin&nbsp;θ + b.</p></div></li>\n      </ul>\n      <ul class=\"feature-list reveal\">\n        <li><span class=\"fi\">−</span><div><b>Subtraction cancels the zero offset</b><p>(R<sub>A0</sub> − R<sub>A180</sub>) / 2 = the true sin&nbsp;θ — the zero offset b cancels exactly. That is why both passes are mandatory on the first, baseline survey: a missed reverse pass locks the drift into every later result.</p></div></li>\n        <li><span class=\"fi\">+</span><div><b>Addition yields the checksum</b><p>R<sub>A0</sub> + R<sub>A180</sub> = 2b ≈ 0. The checksum distribution is reviewed before data is delivered: |checksum| &lt; 0.5&nbsp;mm/m passes; values persistently above the threshold flag instrument zero drift — recalibrate the probe rather than trust the curve.</p></div></li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ====== DATA OUTPUT ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Data output</div>\n      <h2>Curves You Can Act On</h2>\n      <p>\n        After each survey the app jumps straight to plots and data: the casing profile, change versus the baseline and the previous survey, and the checksum distribution — all reviewed on site before the data ships to the cloud.\n        \n      </p>\n    </div>\n    <div class=\"split\" style=\"align-items:start;\">\n      <div class=\"diagram-box reveal\">\n        <svg viewBox=\"0 0 520 460\" role=\"img\" aria-label=\"Representative cumulative displacement versus depth profile\">\n          <!-- grid -->\n          <line x1=\"166\" y1=\"60\" x2=\"166\" y2=\"408\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"242\" y1=\"60\" x2=\"242\" y2=\"408\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"318\" y1=\"60\" x2=\"318\" y2=\"408\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"394\" y1=\"60\" x2=\"394\" y2=\"408\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"90\" y1=\"128\" x2=\"478\" y2=\"128\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"90\" y1=\"196\" x2=\"478\" y2=\"196\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"90\" y1=\"264\" x2=\"478\" y2=\"264\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <line x1=\"90\" y1=\"332\" x2=\"478\" y2=\"332\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n          <!-- axes -->\n          <line x1=\"90\" y1=\"60\" x2=\"478\" y2=\"60\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n          <path d=\"M 471 55.5 L 481 60 L 471 64.5\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n          <line x1=\"90\" y1=\"60\" x2=\"90\" y2=\"408\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n          <path d=\"M 85.5 401 L 90 411 L 94.5 401\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n          <text x=\"284\" y=\"38\" font-size=\"13.5\" text-anchor=\"middle\" class=\"svg-text-strong lang-en\">Displacement (mm)</text>\n          <text x=\"284\" y=\"38\" font-size=\"13.5\" text-anchor=\"middle\" class=\"svg-text-strong lang-zh\">位移 (mm)</text>\n          <text x=\"52\" y=\"234\" font-size=\"13.5\" text-anchor=\"middle\" transform=\"rotate(-90 52 234)\" class=\"svg-text-strong lang-en\">Depth (m)</text>\n          <text x=\"52\" y=\"234\" font-size=\"13.5\" text-anchor=\"middle\" transform=\"rotate(-90 52 234)\" class=\"svg-text-strong lang-zh\">深度 (m)</text>\n          <!-- baseline -->\n          <line x1=\"98\" y1=\"60\" x2=\"96\" y2=\"400\" class=\"svg-stroke-soft\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n          <!-- successive survey curves -->\n          <path d=\"M 128 60 C 170 110 205 160 212 232 C 216 290 160 360 98 400\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\" opacity=\"0.35\"/>\n          <path d=\"M 142 60 C 205 110 268 160 280 232 C 287 295 185 365 98 400\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\" opacity=\"0.6\"/>\n          <path d=\"M 152 60 C 235 110 330 165 348 234 C 358 300 205 370 98 400\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2.5\"/>\n          <!-- max deformation annotation -->\n          <line x1=\"352\" y1=\"226\" x2=\"376\" y2=\"158\" class=\"svg-stroke-soft\" stroke-width=\"1.2\"/>\n          <text x=\"364\" y=\"128\" font-size=\"12.5\" class=\"svg-text lang-en\">Max deformation</text>\n          <text x=\"364\" y=\"128\" font-size=\"12.5\" class=\"svg-text lang-zh\">最大变形出现</text>\n          <text x=\"364\" y=\"145\" font-size=\"12.5\" class=\"svg-text lang-en\">at mid-depth</text>\n          <text x=\"364\" y=\"145\" font-size=\"12.5\" class=\"svg-text lang-zh\">在中部深度</text>\n          <!-- legend -->\n          <line x1=\"95\" y1=\"436\" x2=\"133\" y2=\"436\" class=\"svg-stroke-soft\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n          <text x=\"141\" y=\"440\" font-size=\"12.5\" class=\"svg-text lang-en\">Initial survey (baseline)</text>\n          <text x=\"141\" y=\"440\" font-size=\"12.5\" class=\"svg-text lang-zh\">首测基准</text>\n          <line x1=\"305\" y1=\"436\" x2=\"343\" y2=\"436\" class=\"svg-stroke\" stroke-width=\"2.5\"/>\n          <text x=\"351\" y=\"440\" font-size=\"12.5\" class=\"svg-text lang-en\">Successive surveys</text>\n          <text x=\"351\" y=\"440\" font-size=\"12.5\" class=\"svg-text lang-zh\">后续多期测量</text>\n        </svg>\n        <div class=\"diagram-caption\">\n          Representative cumulative-displacement profile of the kind produced in the Xinghu Street CX34 same-borehole validation (37&nbsp;m borehole, half a month of surveys). Axes are unitless for illustration.\n          \n        </div>\n      </div>\n      <ul class=\"feature-list reveal\" style=\"margin-top:8px;\">\n        <li><span class=\"fi\">✓</span><div><b>Casing profile</b><p>Cumulative offset (mm) against depth (m). First check: is the overall shape smooth, with no sudden jumps? A jump usually means a depth was recorded wrongly — check the cable depth markings.</p></div></li>\n        <li><span class=\"fi\">✓</span><div><b>Cumulative &amp; incremental change</b><p>Offset change relative to the first survey reveals displacement trends; change versus the previous survey shows the short-term rate. Overlaying successive surveys shows whether movement is still growing — the key call for early warning, and a way to locate the sliding surface.</p></div></li>\n        <li><span class=\"fi\">✓</span><div><b>Checksum distribution</b><p>Checksum (mm/m) against depth. Before any report is delivered the whole hole should sit within ±0.5&nbsp;mm/m — the checksum identifies instrument anomalies before they contaminate the displacement record.</p></div></li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>Two Classes, One Standard of Quality</h2>\n      <p>Class A serves high-accuracy rail-transit and major energy projects; Class B provides a high-value configuration for routine foundation-pit and slope monitoring.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">Class A High-Precision (SCIS Series)</th>\n            <th scope=\"col\">Class B Standard (RCIS/SCIS 20xx)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Sensor</td><td>MEMS accelerometer</td><td>MEMS accelerometer</td></tr>\n          <tr><td>Resolution</td><td class=\"hl\">0.005 mm / 500 mm</td><td>0.01 mm / 500 mm</td></tr>\n          <tr><td>Repeatability</td><td class=\"hl\">±0.003°</td><td>±0.006°</td></tr>\n          <tr><td>System accuracy</td><td class=\"hl\">≤±1.5 mm / 30 m</td><td>≤±2.0 mm / 30 m</td></tr>\n          <tr><td>Range</td><td>±30° / ±15°</td><td>±15° / ±30°</td></tr>\n          <tr><td>IP rating</td><td>IP68 · 3 MPa</td><td>IP68 · 3 MPa</td></tr>\n          <tr><td>Battery life</td><td>80 h</td><td>60–80 h</td></tr>\n          <tr><td>Operating temperature</td><td>-20 ~ 70 ℃</td><td>-20 ~ 70 ℃</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px;\">\n      <h2 style=\"font-size:24px;\">Four Components — Carried in One Hand</h2>\n    </div>\n    <div class=\"grid grid-4\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v20\"/><circle cx=\"12\" cy=\"18\" r=\"3\"/><path d=\"M9 6h6M9 10h6\"/></svg></div><h3>1 · Probe</h3><p>MEMS-sensor probe handles data acquisition in a stainless-steel body.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12c4-6 12-6 16 0M4 12c4 6 12 6 16 0\"/></svg></div><h3>2 · Control Cable</h3><p>0.5 m positioning rings provide precise, repeatable depth positioning.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></div><h3>3 · Bluetooth Reel</h3><p>Built-in 7.4 V lithium battery enables fully wireless transmission.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\"/><line x1=\"12\" y1=\"18\" x2=\"12.01\" y2=\"18\"/></svg></div><h3>4 · Mobile App</h3><p>Android app for processing, on-site plotting and cloud sync.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== AUTO-MEASUREMENT MODE ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Proprietary technology</div>\n      <h2>Auto-Measurement Mode: Just Pull the Probe</h2>\n      <p>The traditional workflow needs two people and 15–20 minutes per borehole. SoilCreate reinvents it — start the app once, then never touch the phone again.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Launch auto-measurement in the app</b><p>One tap on an Android phone starts the session.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Software auto-detects stability</b><p>Lower the probe to depth; stability confirmed when 3 consecutive readings differ by &lt;0.02 mm.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Auto-record + voice prompt</b><p>Once stable, data records automatically and the voice prompt says \"Pull now.\"</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Pull detection</b><p>Raise the probe 0.5 m — a &gt;0.1 mm change is auto-recognized as a pull, and the next point begins.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Repeat to the top — hands-free</b><p>The operator never touches the phone until the survey is complete.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"visual reveal\"><img src=\"/images/products/sliding-inclinometer/sliding-auto-mode-system.jpg\" alt=\"SCIS sliding inclinometer probe, control cable and Bluetooth reel for auto-measurement\" width=\"1000\" height=\"704\" decoding=\"async\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FIELD WORKFLOW & QC ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Field workflow &amp; quality control</div>\n      <h2>The Complete A0 + A180 Survey, Step by Step</h2>\n      <p>\n        Both passes are mandatory on the first, baseline survey — and the app walks the operator through every step, from Bluetooth pairing to the on-screen checksum.\n        \n      </p>\n    </div>\n    <div class=\"grid grid-2\">\n      <ul class=\"feature-list reveal\">\n        <li><span class=\"fi\">1</span><div><b>Power on &amp; pair</b><p>Switch on the reel (green power indicator), launch the app on the Android terminal and connect to the Bluetooth device whose RTI-prefixed name matches your instrument — a steady blue light means connected.</p></div></li>\n        <li><span class=\"fi\">2</span><div><b>Open the project, enter the A0 groove</b><p>Tap Measure to open or create the project. Slide the A-axis positive guide wheels into the A0 groove and lower the probe to the starting depth — the cable marking must match the depth shown in the app.</p></div></li>\n        <li><span class=\"fi\">3</span><div><b>Survey the A0 pass, bottom-up</b><p>At each 0.5&nbsp;m station, wait for the reading to stabilize, record, then pull to the next depth until the probe reaches the top. In auto mode the software detects stability and each pull for you.</p></div></li>\n      </ul>\n      <ul class=\"feature-list reveal\">\n        <li><span class=\"fi\">4</span><div><b>Rotate 180°</b><p>Withdraw the probe and rotate it 180° about its axis so the A-axis positive wheels enter the A180 groove; lower it back to the starting depth.</p></div></li>\n        <li><span class=\"fi\">5</span><div><b>Survey the A180 pass</b><p>Start the 180° series. The app now shows the live checksum — the A0 + A180 sum, ideally ≈ 0 — beneath each reading as you repeat the pass to the top.</p></div></li>\n        <li><span class=\"fi\">6</span><div><b>Review plots before leaving site</b><p>The app jumps straight to the plots-and-data screen. Check the checksum distribution and profile curves on site; the survey syncs to the cloud automatically.</p></div></li>\n      </ul>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px; margin-bottom:32px;\">\n      <h2 style=\"font-size:24px;\">Five Checks Before Every Survey</h2>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><h3>1 · Serial-number match</h3><p>Probe and Bluetooth-reel serial numbers must correspond one-to-one — never mix sets.</p></div>\n      <div class=\"card reveal\"><h3>2 · Top screw</h3><p>Don't over-tighten the probe's top screw — it damages the cable connector and shortens O-ring life.</p></div>\n      <div class=\"card reveal\"><h3>3 · Guided in &amp; out</h3><p>Use a hand to guide the positioning wheels as they slide into and out of the casing grooves.</p></div>\n      <div class=\"card reveal\"><h3>4 · Gentle to the bottom</h3><p>Lower with care so the probe never strikes the casing bottom.</p></div>\n      <div class=\"card reveal\"><h3>5 · Temperature window</h3><p>Keep the ambient temperature within −20 to 70&nbsp;°C.</p></div>\n      <div class=\"card reveal\"><h3>Quality gates</h3><p>Checksum |A0+A180| &lt; 0.5&nbsp;mm/m; same-depth repeatability &lt; 0.3&nbsp;mm/m; cumulative curve smooth with no jumps.</p></div>\n    </div>\n\n    <div class=\"gallery\" style=\"margin-top:42px;\">\n      <figure class=\"reveal\"><img src=\"/images/products/sliding-inclinometer/sliding-detail-reel-probe.jpg\" alt=\"Bluetooth control reel with built-in lithium battery and docked probe\" loading=\"lazy\" width=\"1000\" height=\"750\" decoding=\"async\"><figcaption>Bluetooth control reel (built-in lithium battery) with the probe docked on top.</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/sliding-inclinometer/sliding-detail-guide-wheels.jpg\" alt=\"Stainless-steel spring-loaded guide-wheel carriage of the probe\" loading=\"lazy\" width=\"1000\" height=\"1333\" decoding=\"async\"><figcaption>Stainless-steel guide-wheel carriage — the wheels ride in the casing's orthogonal grooves.</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/sliding-inclinometer/sliding-detail-probe-body.jpg\" alt=\"Stainless-steel probe bodies with positioning wheels\" loading=\"lazy\" width=\"768\" height=\"1024\" decoding=\"async\"><figcaption>Stainless-steel probe bodies; positioning-wheel centre spacing 500&nbsp;mm.</figcaption></figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== COMPETITIVE COMPARISON ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Benchmarked</div>\n      <h2>Head-to-Head with the Industry Benchmark</h2>\n      <p>In a same-borehole comparison at Xinghu Street CX34 (37 m borehole, half a month of testing), SoilCreate's cumulative-change curve closely matched the reference instrument throughout the test period.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap reveal\">\n      <table class=\"spec-table versus-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Dimension</th>\n            <th scope=\"col\">SoilCreate SCIS</th>\n            <th scope=\"col\">Reference Instrument</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Readout device</td><td class=\"hl\">Smartphone app</td><td>Dedicated readout unit</td></tr>\n          <tr><td>Operators</td><td class=\"hl\">1 person</td><td>2 people</td></tr>\n          <tr><td>Time per borehole</td><td class=\"hl\">5 min / 30 m</td><td>15–20 min</td></tr>\n          <tr><td>Data transfer</td><td class=\"hl\">Bluetooth → cloud, real-time</td><td>Manual export</td></tr>\n          <tr><td>System weight</td><td class=\"hl\">7.5 kg</td><td>~15 kg</td></tr>\n          <tr><td>Accuracy validation</td><td>Xinghu St. CX34 same-borehole match</td><td>Industry benchmark</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:42px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">-50%</div><div class=\"name\">Labor Cost</div><p>One operator replaces a two-person crew.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">3×</div><div class=\"name\">Survey Efficiency</div><p>5 minutes vs. 15–20 minutes per 30 m borehole.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">0</div><div class=\"name\">Manual Data Handling</div><p>Field → cloud with zero touch, eliminating transcription errors.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">CX34</div><div class=\"name\">Field Validation</div><p>Same-borehole field comparison with closely aligned curves.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== PROJECTS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Track record</div>\n      <h2>Proven Across Benchmark Projects</h2>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><span class=\"tag\">Metro</span><h3 style=\"margin-top:12px;\">Suzhou Metro Line 6</h3><p>Jinchu Street Station — wall inclinometer monitoring with manual comparison.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Metro</span><h3 style=\"margin-top:12px;\">Guangzhou Metro Line 13</h3><p>Shangyong Park Station — foundation-pit monitoring, cross-validated against in-place data.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Metro</span><h3 style=\"margin-top:12px;\">Hangzhou Metro Line 3</h3><p>Chaowang Road Station — emergency-response monitoring with automated verification.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Hydropower</span><h3 style=\"margin-top:12px;\">Baihetan Hydropower Station</h3><p>Deep-displacement measurement of surrounding hillsides at a 300 m-class world-scale project.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Benchmark test</span><h3 style=\"margin-top:12px;\">Xinghu Street CX34, Suzhou</h3><p>Same-borehole comparison with a reference instrument, with closely aligned data over half a month.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Geohazard</span><h3 style=\"margin-top:12px;\">PetroChina Pipeline, Nanning</h3><p>Geohazard landslide-body monitoring along an operating pipeline corridor.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Sliding Inclinometer FAQ</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>Is the SCIS compatible with inclinometer casing I already have installed?</summary>\n        <div class=\"faq-body\">\n          Yes. The SCIS runs in any standard 70&nbsp;mm internal-diameter, four-groove PVC/ABS inclinometer casing. The 70&nbsp;mm casing with four orthogonal grooves and 500&nbsp;mm wheel spacing is an international common specification — not a vendor-proprietary format — so probes and casings from different manufacturers are interchangeable.\n          \n        </div>\n      </details>\n      <details>\n        <summary>How do I choose the control-cable length for deep boreholes?</summary>\n        <div class=\"faq-body\">\n          The standard configuration ships with a 50&nbsp;m cable, suited to routine foundation pits. We recommend 80&nbsp;m for deep pits and retaining walls and 100&nbsp;m for dams and slopes; longer lengths are custom-built — up to a 180&nbsp;m cable proven in a 180&nbsp;m-deep hydropower borehole. For deep holes and long-term programmes, also stock spares: a backup reel, two guide-wheel kits (wheels wear faster in deep holes), O-rings and cable connectors.\n          \n        </div>\n      </details>\n      <details>\n        <summary>What should I do when the checksum is abnormal?</summary>\n        <div class=\"faq-body\">\n          The checksum (A0&nbsp;+&nbsp;A180) should stay within ±0.5&nbsp;mm/m. If most points in a hole exceed it, the probe's zero position has drifted — the instrument needs calibration or service, and persistent exceedance means a metrology-institute recalibration before further reporting. If repeated readings at the same depth differ by more than 0.3&nbsp;mm/m, also check the guide wheels, springs and cable contacts. A sudden jump in the cumulative curve usually points to a wrongly recorded depth — verify the cable depth markings.\n          \n        </div>\n      </details>\n      <details>\n        <summary>Readings take a long time to stabilize, or auto mode saves points by mistake — how do I fix it?</summary>\n        <div class=\"faq-body\">\n          Both are threshold settings in the app's measurement-control menu. If readings won't stabilize (an over-strict threshold or probe disturbance), relax the measurement-precision parameter from the default 0.02&nbsp;mm to 0.05&nbsp;mm. If auto mode mis-saves during normal stabilization, the auto-measurement change threshold (default 0.2&nbsp;mm) is set too small — increase it to a moderate value.\n          \n        </div>\n      </details>\n      <details>\n        <summary>How long does the battery last, and what if Bluetooth won't connect?</summary>\n        <div class=\"faq-body\">\n          The Bluetooth reel's built-in lithium battery supports 80 hours of continuous operation; charge it through the charging port on the reel panel, and charge whenever the red battery indicator lights. If Bluetooth won't connect: confirm you selected the device with the RTI name prefix matching your instrument, shorten the distance, check the reel's battery, and re-pair — a steady blue indicator means connected.\n          \n        </div>\n      </details>\n      <details>\n        <summary>How should the probe and cable be maintained — and when must the probe go back for recalibration?</summary>\n        <div class=\"faq-body\">\n          After the last survey of the day, wipe the probe and cable dry and keep the cable connector dry; lubricate the positioning wheels with a few drops of light machine oil (never chlorine-containing solvents), grease the connector O-rings, clean contacts with an alcohol swab rather than electrical contact cleaner, and store the system in a dry place. Send the probe for metrology-institute calibration when the checksum persistently exceeds 0.5&nbsp;mm/m. On a water-ingress alarm, stop using the probe immediately, replace the O-ring and have the unit inspected after drying — never just wipe it dry and continue.\n          \n        </div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "in-place-inclinometer": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>In-Place Inclinometer</span>\n    </div>\n    <h1>In-Place Inclinometer</h1>\n    <p class=\"sub\">\n      7×24 automated deep-displacement monitoring. One RS485 cable chains up to 128 sensors, and a 120&nbsp;g/m carbon-fiber rod lets a single operator install by hand — even in 60–100&nbsp;m boreholes.\n      \n    </p>\n    <div class=\"model\">SCIS-IPI-01 · RS485 ×128 · CARBON FIBER</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/in-place-inclinometer/in-place-inclinometer-sensor-chain.jpg\" alt=\"SCIS-IPI-01 lightweight in-place inclinometer sensor string with carbon-fiber rods and RS485 bus cabling\" width=\"1000\" height=\"1017\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Real-time data that manual surveys can never capture\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          If the sliding inclinometer solves manual-survey efficiency, the in-place inclinometer answers the need for 7×24 automated monitoring. It samples continuously at minute-level frequency — as fast as one reading per minute — capturing the instantaneous changes a daily site visit could never detect.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Carbon-fiber rod, 120 g/m</b><p>One-fifth the weight of a traditional metal rod — light yet high-strength (≥5.5 kN).</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>One RS485 cable, 128 nodes, AutoID</b><p>A single bus chains 128 segments; AutoID auto-addressing means no per-unit configuration.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Electrolytic-solution sensor option</b><p>Proprietary sensing element with 1×10⁻⁸-level long-term stability for multi-year projects.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.005 mm</div><div class=\"name\">Resolution / 500 mm</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">×128</div><div class=\"name\">Sensors on One RS485 Bus</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">120 g/m</div><div class=\"name\">Carbon-Fiber Rod</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">IP68 · 2 MPa</div><div class=\"name\">Waterproof Rating</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>A Permanent Sensor String Inside the Casing</h2>\n      <p>If the sliding inclinometer is a stethoscope lowered into the borehole for each visit, the in-place inclinometer is a permanently implanted ECG: it seals the entire manual-survey process inside the grooved casing and runs it automatically, around the clock.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"diagram-box reveal\">\n        <svg viewBox=\"0 0 760 420\" role=\"img\" aria-label=\"In-place inclinometer system diagram: chained sensor segments in a grooved casing, one RS485 bus cable rising to a collector box and on to the cloud\">\n          <!-- ground line -->\n          <line class=\"svg-stroke-soft\" x1=\"40\" y1=\"100\" x2=\"720\" y2=\"100\" stroke-width=\"2\"/>\n          <g class=\"svg-stroke-soft\" stroke-width=\"1.4\">\n            <line x1=\"60\" y1=\"100\" x2=\"50\" y2=\"112\"/><line x1=\"100\" y1=\"100\" x2=\"90\" y2=\"112\"/><line x1=\"140\" y1=\"100\" x2=\"130\" y2=\"112\"/><line x1=\"180\" y1=\"100\" x2=\"170\" y2=\"112\"/>\n            <line x1=\"580\" y1=\"100\" x2=\"570\" y2=\"112\"/><line x1=\"620\" y1=\"100\" x2=\"610\" y2=\"112\"/><line x1=\"660\" y1=\"100\" x2=\"650\" y2=\"112\"/><line x1=\"700\" y1=\"100\" x2=\"690\" y2=\"112\"/>\n          </g>\n          <!-- casing walls -->\n          <line class=\"svg-stroke-soft\" x1=\"208\" y1=\"100\" x2=\"208\" y2=\"398\" stroke-width=\"2.5\"/>\n          <line class=\"svg-stroke-soft\" x1=\"252\" y1=\"100\" x2=\"252\" y2=\"398\" stroke-width=\"2.5\"/>\n          <!-- casing-mouth protector -->\n          <rect class=\"svg-fill-soft svg-stroke\" x=\"200\" y=\"90\" width=\"60\" height=\"14\" rx=\"3\" stroke-width=\"1.5\"/>\n          <!-- bus cable: top segment -> mouth -> collector box -->\n          <path class=\"svg-stroke\" d=\"M230 120 L230 104 Q230 78 256 78 L402 78\" fill=\"none\" stroke-width=\"2\"/>\n          <!-- segments -->\n          <g>\n            <rect class=\"svg-fill-soft svg-stroke\" x=\"219\" y=\"120\" width=\"22\" height=\"44\" rx=\"6\" stroke-width=\"1.6\"/>\n            <rect class=\"svg-fill-soft svg-stroke\" x=\"219\" y=\"186\" width=\"22\" height=\"44\" rx=\"6\" stroke-width=\"1.6\"/>\n            <rect class=\"svg-fill-soft svg-stroke\" x=\"219\" y=\"252\" width=\"22\" height=\"44\" rx=\"6\" stroke-width=\"1.6\"/>\n            <rect class=\"svg-fill-soft svg-stroke\" x=\"219\" y=\"318\" width=\"22\" height=\"44\" rx=\"6\" stroke-width=\"1.6\"/>\n          </g>\n          <!-- wheels touching casing -->\n          <g class=\"svg-stroke\" fill=\"none\" stroke-width=\"1.4\">\n            <circle cx=\"214\" cy=\"127\" r=\"4\"/><circle cx=\"246\" cy=\"127\" r=\"4\"/>\n            <circle cx=\"214\" cy=\"193\" r=\"4\"/><circle cx=\"246\" cy=\"193\" r=\"4\"/>\n            <circle cx=\"214\" cy=\"259\" r=\"4\"/><circle cx=\"246\" cy=\"259\" r=\"4\"/>\n            <circle cx=\"214\" cy=\"325\" r=\"4\"/><circle cx=\"246\" cy=\"325\" r=\"4\"/>\n          </g>\n          <!-- connecting rods -->\n          <g class=\"svg-stroke\" stroke-width=\"3\">\n            <line x1=\"230\" y1=\"164\" x2=\"230\" y2=\"186\"/>\n            <line x1=\"230\" y1=\"230\" x2=\"230\" y2=\"252\"/>\n            <line x1=\"230\" y1=\"296\" x2=\"230\" y2=\"318\"/>\n          </g>\n          <!-- bottom steel-wire clamp -->\n          <rect class=\"svg-fill-soft svg-stroke\" x=\"222\" y=\"368\" width=\"16\" height=\"12\" rx=\"2\" stroke-width=\"1.5\"/>\n          <!-- segment numbers -->\n          <g class=\"svg-text-accent\" font-size=\"10\" text-anchor=\"middle\">\n            <text x=\"230\" y=\"146\">#N</text>\n            <text x=\"230\" y=\"212\">#3</text>\n            <text x=\"230\" y=\"278\">#2</text>\n            <text x=\"230\" y=\"344\">#1</text>\n          </g>\n          <!-- gauge-length dimension between segment centers -->\n          <g class=\"svg-stroke\" stroke-width=\"1.2\">\n            <line x1=\"252\" y1=\"274\" x2=\"276\" y2=\"274\"/>\n            <line x1=\"252\" y1=\"340\" x2=\"276\" y2=\"340\"/>\n            <line x1=\"268\" y1=\"274\" x2=\"268\" y2=\"340\"/>\n            <path d=\"M268 274 L264 282 L272 282 Z\" fill=\"currentColor\" stroke=\"none\" class=\"svg-fill-soft\"/>\n          </g>\n          <text class=\"svg-text lang-en\" x=\"282\" y=\"303\" font-size=\"12\">Gauge length (wheelbase) 0.5–1 m</text>\n          <text class=\"svg-text lang-zh\" x=\"282\" y=\"303\" font-size=\"12\">标距（定位轮轮距）0.5–1 m</text>\n          <!-- collector box -->\n          <rect class=\"svg-fill-soft svg-stroke\" x=\"402\" y=\"46\" width=\"148\" height=\"54\" rx=\"8\" stroke-width=\"1.8\"/>\n          <text class=\"svg-text-strong lang-en\" x=\"476\" y=\"68\" font-size=\"12.5\" text-anchor=\"middle\">Collector box (IP65)</text>\n          <text class=\"svg-text-strong lang-zh\" x=\"476\" y=\"68\" font-size=\"12.5\" text-anchor=\"middle\">集电箱（IP65）</text>\n          <text class=\"svg-text lang-en\" x=\"476\" y=\"86\" font-size=\"11\" text-anchor=\"middle\">Controller · Power supply</text>\n          <text class=\"svg-text lang-zh\" x=\"476\" y=\"86\" font-size=\"11\" text-anchor=\"middle\">控制器 · 供电模块</text>\n          <!-- wireless link to cloud -->\n          <line class=\"svg-stroke\" x1=\"550\" y1=\"66\" x2=\"606\" y2=\"66\" stroke-width=\"1.6\" stroke-dasharray=\"5 5\"/>\n          <text class=\"svg-text-accent\" x=\"578\" y=\"56\" font-size=\"10.5\" text-anchor=\"middle\">4G/5G</text>\n          <!-- cloud -->\n          <rect class=\"svg-fill-soft svg-stroke\" x=\"606\" y=\"40\" width=\"134\" height=\"52\" rx=\"26\" stroke-width=\"1.8\"/>\n          <text class=\"svg-text-strong lang-en\" x=\"673\" y=\"62\" font-size=\"12\" text-anchor=\"middle\">SoilCreate Monitoring</text>\n          <text class=\"svg-text-strong lang-en\" x=\"673\" y=\"78\" font-size=\"12\" text-anchor=\"middle\">Cloud</text>\n          <text class=\"svg-text-strong lang-zh\" x=\"673\" y=\"70\" font-size=\"12.5\" text-anchor=\"middle\">瑞茨柏监测云平台</text>\n          <!-- left-side labels -->\n          <g font-size=\"12\" text-anchor=\"end\">\n            <text class=\"svg-text lang-en\" x=\"190\" y=\"92\">Casing-mouth protector</text>\n            <text class=\"svg-text lang-zh\" x=\"190\" y=\"92\">管口保护装置</text>\n            <text class=\"svg-text lang-en\" x=\"190\" y=\"152\">Grooved inclinometer casing</text>\n            <text class=\"svg-text lang-zh\" x=\"190\" y=\"152\">测斜管（带导槽）</text>\n            <text class=\"svg-text lang-en\" x=\"190\" y=\"245\">Connecting rod</text>\n            <text class=\"svg-text lang-zh\" x=\"190\" y=\"245\">连接杆</text>\n            <text class=\"svg-text lang-en\" x=\"190\" y=\"377\">Steel-wire-rope clamp, bottom segment</text>\n            <text class=\"svg-text lang-zh\" x=\"190\" y=\"377\">钢丝绳夹（底部节点固定）</text>\n          </g>\n          <g class=\"svg-stroke-soft\" stroke-width=\"1\">\n            <line x1=\"194\" y1=\"89\" x2=\"200\" y2=\"94\"/>\n            <line x1=\"194\" y1=\"148\" x2=\"208\" y2=\"143\"/>\n            <line x1=\"194\" y1=\"241\" x2=\"226\" y2=\"238\"/>\n            <line x1=\"194\" y1=\"373\" x2=\"220\" y2=\"373\"/>\n          </g>\n          <!-- right-side segment label -->\n          <text class=\"svg-text lang-en\" x=\"290\" y=\"200\" font-size=\"12\">Sensor segment — MEMS or</text>\n          <text class=\"svg-text lang-en\" x=\"290\" y=\"216\" font-size=\"12\">electrolytic-solution tilt sensor</text>\n          <text class=\"svg-text lang-zh\" x=\"290\" y=\"208\" font-size=\"12\">测斜仪节段——MEMS 或电解质溶液传感器</text>\n          <line class=\"svg-stroke-soft\" x1=\"286\" y1=\"204\" x2=\"252\" y2=\"206\" stroke-width=\"1\"/>\n          <!-- bus cable label -->\n          <text class=\"svg-text lang-en\" x=\"392\" y=\"64\" font-size=\"12\" text-anchor=\"end\">One RS485 bus cable</text>\n          <text class=\"svg-text lang-zh\" x=\"392\" y=\"64\" font-size=\"12\" text-anchor=\"end\">一根 RS485 总线电缆</text>\n        </svg>\n        <div class=\"diagram-caption\">System composition: sensor segments, connecting rods, steel wire rope, casing-mouth protector and the data-service system (controller + power + collector box). Numbering runs bottom-up — segment #1 sits deepest.</div>\n      </div>\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Permanent, not periodic</b><p>A sliding system competes on flexibility — one probe surveys many boreholes weekly or monthly during construction. The in-place type competes on permanence: installed once, it samples automatically at minute-level frequency with no site visits. Projects running three years or longer, or sites needing remote access, are IPI territory; sub-one-year construction monitoring usually favors the sliding type.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Segment number ↔ depth, on record</b><p>Segments are installed bottom-up, and each one is logged into a segment-number-to-depth table as it goes in. Any later anomaly in the remote data maps straight back to a specific segment at a specific depth — so maintenance targets one node instead of guessing.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Cloud-managed alarms, automatically</b><p>Devices are bound to the cloud platform at the factory; on site, the controller registers and comes online by itself. Engineers then set rate and cumulative alarm thresholds per measuring point — when a reading exceeds them, the platform pushes SMS alerts, with multi-account views for owner, contractor, supervisor and third parties.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"split\" style=\"margin-top:48px;\">\n      <div class=\"reveal\">\n        <h3 style=\"font-size:22px; margin-bottom:14px;\">What the Data Looks Like</h3>\n        <p style=\"color:var(--text-2);\">Each segment continuously measures tilt over its gauge length; the platform converts the chain of readings into a displacement-vs-depth profile. Because sampling is automatic — as fast as one reading per minute — the profile is redrawn continuously, revealing how deflection develops over time instead of waiting for the next manual survey.</p>\n        <p style=\"color:var(--text-2); margin-top:14px;\">On network loss, each string buffers data in 16 GB of onboard storage — over a year of history — and resumes upload automatically once the connection recovers.</p>\n      </div>\n      <div class=\"diagram-box reveal\">\n        <svg viewBox=\"0 0 760 420\" role=\"img\" aria-label=\"Representative displacement versus depth profile evolving over successive automated readings\">\n          <!-- plot frame -->\n          <g class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.6\">\n            <line x1=\"140\" y1=\"150\" x2=\"690\" y2=\"150\"/>\n            <line x1=\"140\" y1=\"220\" x2=\"690\" y2=\"220\"/>\n            <line x1=\"140\" y1=\"290\" x2=\"690\" y2=\"290\"/>\n          </g>\n          <!-- axes -->\n          <line class=\"svg-stroke-soft\" x1=\"140\" y1=\"80\" x2=\"140\" y2=\"368\" stroke-width=\"2\"/>\n          <line class=\"svg-stroke-soft\" x1=\"140\" y1=\"80\" x2=\"690\" y2=\"80\" stroke-width=\"2\"/>\n          <!-- depth ticks -->\n          <g class=\"svg-stroke-soft\" stroke-width=\"1.5\">\n            <line x1=\"134\" y1=\"150\" x2=\"140\" y2=\"150\"/><line x1=\"134\" y1=\"220\" x2=\"140\" y2=\"220\"/><line x1=\"134\" y1=\"290\" x2=\"140\" y2=\"290\"/><line x1=\"134\" y1=\"360\" x2=\"140\" y2=\"360\"/>\n          </g>\n          <!-- zero line -->\n          <line class=\"svg-stroke-soft\" x1=\"168\" y1=\"80\" x2=\"168\" y2=\"368\" stroke-width=\"1.2\" stroke-dasharray=\"4 5\"/>\n          <!-- axis labels -->\n          <text class=\"svg-text-strong lang-en\" x=\"415\" y=\"48\" font-size=\"13\" text-anchor=\"middle\">Displacement (mm)</text>\n          <text class=\"svg-text-strong lang-zh\" x=\"415\" y=\"48\" font-size=\"13\" text-anchor=\"middle\">位移（mm）</text>\n          <text class=\"svg-text-strong lang-en\" x=\"70\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" transform=\"rotate(-90 70 224)\">Depth (m)</text>\n          <text class=\"svg-text-strong lang-zh\" x=\"70\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" transform=\"rotate(-90 70 224)\">深度（m）</text>\n          <!-- profiles: common fixed toe, growing deflection -->\n          <path class=\"svg-stroke-soft\" d=\"M168 360 C166 300 178 220 192 162 C198 134 201 110 203 92\" fill=\"none\" stroke-width=\"2\"/>\n          <path class=\"svg-stroke\" d=\"M168 360 C164 300 196 222 228 162 C240 132 246 108 249 92\" fill=\"none\" stroke-width=\"2\" opacity=\"0.55\"/>\n          <path class=\"svg-stroke\" d=\"M168 360 C162 300 214 230 268 166 C288 132 297 108 301 92\" fill=\"none\" stroke-width=\"2.5\"/>\n          <!-- legend -->\n          <g font-size=\"12\">\n            <line class=\"svg-stroke-soft\" x1=\"470\" y1=\"120\" x2=\"502\" y2=\"120\" stroke-width=\"2\"/>\n            <text class=\"svg-text lang-en\" x=\"510\" y=\"124\">Initial reading</text>\n            <text class=\"svg-text lang-zh\" x=\"510\" y=\"124\">初始读数</text>\n            <line class=\"svg-stroke\" x1=\"470\" y1=\"146\" x2=\"502\" y2=\"146\" stroke-width=\"2\" opacity=\"0.55\"/>\n            <text class=\"svg-text lang-en\" x=\"510\" y=\"150\">Interim reading</text>\n            <text class=\"svg-text lang-zh\" x=\"510\" y=\"150\">中期读数</text>\n            <line class=\"svg-stroke\" x1=\"470\" y1=\"172\" x2=\"502\" y2=\"172\" stroke-width=\"2.5\"/>\n            <text class=\"svg-text lang-en\" x=\"510\" y=\"176\">Latest reading</text>\n            <text class=\"svg-text lang-zh\" x=\"510\" y=\"176\">最新读数</text>\n          </g>\n        </svg>\n        <div class=\"diagram-caption\">Representative continuous-monitoring profile shape: successive automated readings reveal progressive deflection with depth. Illustrative curve shape only — not project data.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>Built for Unattended, Long-Term Duty</h2>\n      <p>Two figures stand out: 0.05 W per segment means the system runs stably on solar power alone, and 5.5 kN tensile strength keeps deep-borehole installation structurally safe.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">SCIS-IPI-01 Specification</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Sensor</td><td>MEMS accelerometer / electrolytic-solution sensor (optional)</td></tr>\n          <tr><td>Range</td><td>±15° / ±30°</td></tr>\n          <tr><td>Resolution</td><td class=\"hl\">0.01 mm / 0.005 mm</td></tr>\n          <tr><td>Repeatability</td><td class=\"hl\">±0.003°</td></tr>\n          <tr><td>Long-term stability</td><td>&lt;±0.01%</td></tr>\n          <tr><td>Operating temperature</td><td>-20 ~ 70 ℃</td></tr>\n          <tr><td>Waterproof rating</td><td>IP68 / 2 MPa</td></tr>\n          <tr><td>Power consumption</td><td class=\"hl\">≤0.05 W / segment</td></tr>\n          <tr><td>Tensile strength</td><td>≥5.5 kN</td></tr>\n          <tr><td>Rod length</td><td>0.79 m / 1 m</td></tr>\n          <tr><td>Net weight</td><td>~1 kg / segment</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== STRUCTURE & CORE ADVANTAGES ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Structure &amp; core advantages</div>\n      <h2>\"Light yet Strong\" — the Design Philosophy</h2>\n      <p>While holding 5.5 kN tensile strength, the carbon-fiber rod cuts weight to one-fifth of a traditional metal rod — so operators install in 60–100 m deep boreholes by hand, with no hoisting equipment.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Centralizing wheel set</b><p>Fixed wheels plus spring-loaded wheels keep the sensor precisely aligned in the casing.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Rod — carbon fiber / aluminum alloy</b><p>120 g/m, one-fifth the weight of a traditional metal rod, with deep anodized corrosion protection.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>High-precision tilt sensor</b><p>The core measuring element: MEMS, or the proprietary electrolytic-solution sensor for ultimate long-term stability.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Universal joint connection</b><p>Flexibly links the segments to accommodate a degree of casing bend.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Positioning cable + casing-mouth fixture</b><p>Anchors and protects the entire sensor string.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"visual reveal\"><img src=\"/images/products/in-place-inclinometer/ipi-casing-schematic.jpg\" alt=\"Schematic showing chained in-place inclinometer segments inside deformed inclinometer casing\" width=\"523\" height=\"1024\" decoding=\"async\"></div>\n    </div>\n    <div class=\"grid grid-3\" style=\"margin-top:48px;\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12h16\"/><circle cx=\"7\" cy=\"12\" r=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/><circle cx=\"17\" cy=\"12\" r=\"2\"/></svg></div><h3>Bus Connection</h3><p>One RS485 cable chains 128 segments. Each sensor ships with a factory-unique long address; AutoID assigns short addresses on site — plug-and-play, no per-unit configuration.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><polyline points=\"12 7 12 12 15.5 14\"/></svg></div><h3>Smart Automation</h3><p>Scheduled sampling configurable from 1 min to 24 h; ultra-low-power sleep mode; breakpoint-resume on network loss with 16 GB local storage; remote configuration and firmware upgrades.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6z\"/><polyline points=\"9 12 11 14 15 10\"/></svg></div><h3>Long-Term Stability</h3><p>Even the best MEMS accelerometers drift at the 1×10⁻⁵ level over the years; SoilCreate's proprietary electrolytic-solution sensor holds 1×10⁻⁸ — three orders of magnitude less drift, ideal for 5-year-plus monitoring.</p></div>\n    </div>\n    <p class=\"reveal\" style=\"color:var(--text-2); margin-top:28px; text-align:center;\">\n      <b>In-place + sliding, better together:</b> the in-place type captures instantaneous changes in real time (such as tidal fluctuations); the sliding type cancels zero drift with forward-and-reverse runs. Combined, they form the most complete deep-displacement monitoring solution.\n      \n    </p>\n  </div>\n</section>\n\n<!-- ====== INSTALLATION ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation</div>\n      <h2>Installation: 12 Steps, Bottom-Up</h2>\n      <p>Before starting: identify the string's top (the segment with the aviation-plug cable) and bottom (no plug), and clamp the steel wire rope to the bottom segment. Three checkpoints gate the whole procedure — fixed-wheel orientation, connecting-rod engagement, and steel-wire-rope lock-off.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Compress the spring-loaded wheels</b><p>Press the moving-wheel springs on the segment firmly before it enters the casing.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Slide the wheel set into the guide grooves — checkpoint</b><p>The fixed wheels must face the expected deformation direction of the excavation. Wrong orientation distorts all subsequent data.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Mate the connecting rod — checkpoint</b><p>Carefully insert the quick-connect port of the rod above the segment onto the metal connecting rod — fully seated, no gap. Any gap is an error source.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Tension and lock the steel wire rope — checkpoint</b><p>Pull the wire rope through the rod fully taut, then lock the segment's rope clamp. An untensioned rope leaves segments unloaded and lets them drop out of position.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Secure the spare cable</b><p>Wind excess cable around the connecting rod and fasten with cable clips, so it cannot rub against the casing wall.</p></div></li>\n          <li><span class=\"fi\">6</span><div><b>Lower and connect the next segment</b><p>Push the rod down, then insert the next segment's bottom metal rod into the quick-connect port — again with no gap.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">7</span><div><b>Repeat for every segment</b><p>Repeat steps 1–5 segment by segment, bottom-up, until the string is complete.</p></div></li>\n          <li><span class=\"fi\">8</span><div><b>Lead out the top cable</b><p>Bring the top segment's cable and aviation plug out through the side slot of the casing-mouth protector.</p></div></li>\n          <li><span class=\"fi\">9</span><div><b>Seat the casing-mouth protector</b><p>Place the protector into the casing with its rim pressed onto the casing mouth.</p></div></li>\n          <li><span class=\"fi\">10</span><div><b>Tension the top wire, tighten the screws</b><p>Pull the wire rope above the protector until fully fixed, then tighten the butterfly screws on the protector.</p></div></li>\n          <li><span class=\"fi\">11</span><div><b>Stability check before power</b><p>Visually confirm the whole system sits firmly in the casing before energizing anything.</p></div></li>\n          <li><span class=\"fi\">12</span><div><b>Power up and go online</b><p>Connect power and the controller, then bring the string online on the cloud platform — and verify the first remote reading before leaving site.</p></div></li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px; margin-bottom:32px;\">\n      <h2 style=\"font-size:24px;\">The Three Gates</h2>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><h3>1 · Fixed-wheel orientation</h3><p>The fixed wheels must face the excavation's expected deformation direction. Installed the wrong way, readings persistently trend to one side — and the only remedy is re-installing with the correct orientation.</p></div>\n      <div class=\"card reveal\"><h3>2 · Connecting-rod engagement</h3><p>Every metal connecting rod must be fully seated in its quick-connect port with no gap. A loose segment-to-segment joint is a permanent error source.</p></div>\n      <div class=\"card reveal\"><h3>3 · Steel-wire-rope lock-off</h3><p>Tension first, then lock the rope clamp. If the rope will not pull through, the previous segment's clamp is still locked — open it before pulling. An untensioned rope leaves segments unloaded and out of position.</p></div>\n    </div>\n\n    <p class=\"reveal\" style=\"color:var(--text-2); margin-top:28px; text-align:center;\">\n      <b>Field rule:</b> no matter how tight the schedule, if any of the three checkpoints — fixed-wheel orientation, rod engagement, wire-rope lock-off — is wrong, stop and redo it. Continuing and patching later always costs more than redoing now.\n      \n    </p>\n  </div>\n</section>\n\n<!-- ====== GALLERY ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">In detail</div>\n      <h2>Hardware Up Close</h2>\n    </div>\n    <div class=\"gallery reveal\">\n      <figure>\n        <img src=\"/images/products/in-place-inclinometer/in-place-inclinometer-string.jpg\" alt=\"SCIS-IPI-01 lightweight in-place inclinometer string with slim rods and top connectors\" loading=\"lazy\" width=\"1000\" height=\"954\" decoding=\"async\">\n        <figcaption>Lightweight SCIS-IPI-01 sensor string — slim rods, top connectors and one RS485 bus for long-depth automated monitoring.</figcaption>\n      </figure>\n      <figure>\n        <img src=\"/images/products/in-place-inclinometer/ipi-casing-schematic.jpg\" alt=\"Schematic of chained inclinometer segments conforming to casing deformation, and a single segment with wheel sets\" loading=\"lazy\" width=\"523\" height=\"1024\" decoding=\"async\">\n        <figcaption>Chained segments deform with the casing; the double wheel sets keep each rod centered in the casing.</figcaption>\n      </figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== COMPETITIVE COMPARISON ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Engineering comparison</div>\n      <h2>World-Leading Accuracy · High-Value Pricing</h2>\n      <p>SCIS-IPI-01 combines a 128-node RS485 bus, AutoID addressing and a 120 g/m carbon-fiber rod. The result is less field wiring, simpler deep-borehole installation and a system designed for long-term automated monitoring.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap reveal\">\n      <table class=\"spec-table versus-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Dimension</th>\n            <th scope=\"col\">SoilCreate SCIS-IPI-01</th>\n            <th scope=\"col\">Conventional Multi-Cable Systems</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Wiring</td><td class=\"hl\">One RS485 cable for 128 segments</td><td>Multi-core cable, one run per sensor</td></tr>\n          <tr><td>Signal &amp; addressing</td><td class=\"hl\">Digital bus + AutoID auto-addressing</td><td>Analog signal, per-unit configuration</td></tr>\n          <tr><td>Rod weight</td><td class=\"hl\">Carbon fiber, 120 g/m</td><td>Metal rod, ~5× the weight</td></tr>\n          <tr><td>Deep-borehole install</td><td class=\"hl\">Single person, by hand, 60–100 m</td><td>Heavier string, hoisting often needed</td></tr>\n          <tr><td>Offline resilience</td><td class=\"hl\">16 GB storage, breakpoint-resume, remote upgrade</td><td>Depends on external logger</td></tr>\n          <tr><td>Commercial model</td><td class=\"hl\">High-value project pricing</td><td>Varies by system and service scope</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:42px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">1/5</div><div class=\"name\">Rod Weight</div><p>Carbon fiber vs. a traditional metal rod.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1 : 128</div><div class=\"name\">Cable to Sensors</div><p>One RS485 line replaces 128 cable runs.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1×10⁻⁸</div><div class=\"name\">Long-Term Stability</div><p>Electrolytic-solution option vs. ~1×10⁻⁵ for the best MEMS.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">VALUE</div><div class=\"name\">High-Value Pricing</div><p>World-leading accuracy in a project-ready system.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== CASE STUDIES ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Track record</div>\n      <h2>Where Real-Time Data Proved Its Worth</h2>\n      <p>SoilCreate in-place inclinometers have supported long-term deep-displacement monitoring at major energy, foundation-pit and rail-transit projects. Minute-level automated sampling preserves changes that periodic manual surveys can miss.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><span class=\"tag\">Major energy project</span><h3 style=\"margin-top:12px;\">Coastal Energy Site — the \"Ocean Breathing\" of a 107 m Borehole</h3><p>In reclaimed soft soil 23 m from the sea, automated monitoring recorded an approximately 12-hour periodic casing-top movement with an amplitude near 100 mm. The continuous series provided clear evidence for identifying the influence of Ocean Tide Loading.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Foundation pit</span><h3 style=\"margin-top:12px;\">Suzhou Xiangcheng Foundation Pit</h3><p>Long-term automated monitoring captured twice-daily periodic displacement of the retaining structure, closely matching the tides — deformation that once-a-day manual surveys could never reveal.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Metro</span><h3 style=\"margin-top:12px;\">Suzhou Metro Line 5</h3><p>A deformation-rate exceedance triggered a Level III alert — pushed by SMS and app to the responsible parties before the construction team had noticed anything abnormal. The system is faster, and more accurate, than people.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Frequently Asked Questions</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>What kind of casing does the in-place inclinometer require?</summary>\n        <div class=\"faq-body\">A standard grooved inclinometer casing. Each segment's spring-loaded wheels engage the casing's guide grooves, and the fixed wheels must be oriented toward the expected deformation direction. If a segment will not slide in during installation, the usual causes are a spring wheel that is not fully compressed or misalignment with the grooves — press the spring again and rotate the segment 90° to find the groove position.</div>\n      </details>\n      <details>\n        <summary>No data is coming through after power-up — what should we check first?</summary>\n        <div class=\"faq-body\">Check remotely before dismantling anything on site: first the 4G SIM card (including balance), then the APN configuration, then the controller's 12 V DC supply. Note that a network outage alone does not lose data — each string buffers over a year of history in 16 GB of onboard storage and resumes uploading automatically when the connection recovers.</div>\n      </details>\n      <details>\n        <summary>The data keeps trending to one side — is the sensor drifting?</summary>\n        <div class=\"faq-body\">Persistent one-sided readings usually point to a fixed-wheel orientation installed the wrong way, not sensor drift. The remedy is to re-install the affected string with the correct orientation — which is exactly why orientation is treated as a hard checkpoint during installation: with the wrong orientation, all alarms based on that borehole lose their meaning.</div>\n      </details>\n      <details>\n        <summary>Who sets the alarm thresholds, and can they be changed later?</summary>\n        <div class=\"faq-body\">After the controller registers on the cloud platform, engineers configure per-point thresholds — both rate-of-change and cumulative values. When a reading exceeds them, the platform pushes SMS alerts. Thresholds can be revised, but every change should carry a version record; without that audit trail, a post-event review of \"why did the alarm not fire\" cannot be traced. The platform supports separate accounts for owner, contractor, supervisor and third-party users.</div>\n      </details>\n      <details>\n        <summary>MEMS or electrolytic-solution sensor — which should a multi-year project choose?</summary>\n        <div class=\"faq-body\">MEMS accelerometers use metal measuring elements that fatigue over time (S Liu et al 2020, J. Phys.: Conf. Ser. 1520 012009); even the best hold roughly 1×10⁻⁵ long-term stability and need periodic recalibration. SoilCreate's proprietary electrolytic-solution sensor reaches the 1×10⁻⁸ level — its drift is more than an order of magnitude smaller than the ADC's own error — and needs almost no recalibration. For monitoring of five years or longer, choose the electrolytic-solution option.</div>\n      </details>\n      <details>\n        <summary>If remote data turns anomalous, how do you locate the problem segment?</summary>\n        <div class=\"faq-body\">Through the installation archive. As each segment goes in, its number, depth, fixed-wheel orientation and wire-rope lock state are recorded, and every borehole is delivered with an installation archive, a segment-number-to-depth table, an initial-values table and a remote-online certificate. Any remote anomaly is first matched against this archive to identify the exact segment and depth before deciding whether site maintenance is needed. Also note the two end cables are factory-fitted and waterproof-tested — never loosen them on site.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "flexible-inclinometer": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Flexible Inclinometer</span>\n    </div>\n    <h1>Flexible Inclinometer (Shape Array, SAA)</h1>\n    <p class=\"sub\">\n      A spine-structure 3D deformation monitoring array for large deformation and complex conditions. Segmented like building blocks, it can be assembled on site, dismantled at project end and redeployed on the next project.\n      \n    </p>\n    <div class=\"model\">SCIS-SAA-02 · 3-AXIS · SEGMENTED &amp; RECOVERABLE</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/flexible-inclinometer/flexible-inclinometer-shape-array.jpg\" alt=\"SCIS-SAA-02 flexible inclinometer: rigid segments joined by flexible hinges, folded for transport\" width=\"594\" height=\"594\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          3D deformation, segmented &amp; recoverable, multi-mode layout\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          The SCIS-SAA-02 measures displacement in X, Y and Z simultaneously through a spine-structure array of rigid sensing segments and flexible hinges. AutoID + RS485 chain up to 128 segments on a single cable — vertical in a borehole, horizontal in a trench, or ring-laid around a tunnel section.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>3-axis measurement, 0–360° coverage</b><p>Full all-direction sensing with no blind spots — hard to exceed range even in large deformation.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>±0.002° measurement accuracy</b><p>Equivalent to 0.02 mm per 500 mm, with 0.005 mm displacement resolution.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>180° maximum bending</b><p>Flexible hinges naturally adapt to curved layouts — tunnels, ring sections, uneven trenches.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>IP68 · 3 MPa, tested to 4 MPa</b><p>Backed by a Ministry of Water Resources 4 MPa test report; 8 MPa custom available.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">±0.002°</div><div class=\"name\">Measurement Accuracy</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">0.005 mm</div><div class=\"name\">Displacement Resolution</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">180°</div><div class=\"name\">Max Bending</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">4 MPa</div><div class=\"name\">MWR Test Report</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>A Spine of Rigid Segments and Flexible Joints</h2>\n      <p>Rigid sensing tubes alternate with flexible joints — the tubes measure, the joints take the deformation. Each rigid segment carries a 3-axis MEMS sensor that measures its own orientation in space across 0–360°; chaining every segment's vector end-to-end reconstructs the full 3D deformation shape of the borehole or structure.</p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 420\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Working principle of the flexible inclinometer shape array\">\n        <!-- zone titles -->\n        <text x=\"130\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Array in deformed casing</text>\n        <text x=\"130\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">阵列贴合变形测斜管</text>\n        <text x=\"355\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Single segment (magnified)</text>\n        <text x=\"355\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">单节放大</text>\n        <text x=\"612\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">3D shape reconstruction</text>\n        <text x=\"612\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">三维形状重构</text>\n\n        <!-- left: deformed casing walls -->\n        <path d=\"M 106,55 C 108,130 130,170 150,210 S 162,290 126,355\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <path d=\"M 136,55 C 138,125 160,168 180,208 S 192,288 156,355\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <!-- left: segment chain -->\n        <g stroke-width=\"4\" class=\"svg-stroke\">\n          <line x1=\"120\" y1=\"62\" x2=\"123\" y2=\"100\"/>\n          <line x1=\"123\" y1=\"100\" x2=\"131\" y2=\"138\"/>\n          <line x1=\"131\" y1=\"138\" x2=\"146\" y2=\"174\"/>\n          <line x1=\"146\" y1=\"174\" x2=\"163\" y2=\"208\"/>\n          <line x1=\"163\" y1=\"208\" x2=\"172\" y2=\"245\"/>\n          <line x1=\"172\" y1=\"245\" x2=\"170\" y2=\"283\"/>\n          <line x1=\"170\" y1=\"283\" x2=\"157\" y2=\"318\"/>\n          <line x1=\"157\" y1=\"318\" x2=\"142\" y2=\"350\"/>\n        </g>\n        <g stroke-width=\"1.6\" class=\"svg-stroke svg-fill-soft\">\n          <circle cx=\"123\" cy=\"100\" r=\"4.5\"/><circle cx=\"131\" cy=\"138\" r=\"4.5\"/>\n          <circle cx=\"146\" cy=\"174\" r=\"4.5\"/><circle cx=\"163\" cy=\"208\" r=\"4.5\"/>\n          <circle cx=\"172\" cy=\"245\" r=\"4.5\"/><circle cx=\"170\" cy=\"283\" r=\"4.5\"/>\n          <circle cx=\"157\" cy=\"318\" r=\"4.5\"/>\n        </g>\n        <text x=\"130\" y=\"382\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Rigid tubes measure · joints bend</text>\n        <text x=\"130\" y=\"382\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">硬管测量 · 软管承担变形</text>\n\n        <!-- magnification leader lines -->\n        <line x1=\"152\" y1=\"178\" x2=\"252\" y2=\"120\" stroke-width=\"1.2\" stroke-dasharray=\"4 4\" class=\"svg-stroke-soft\"/>\n        <line x1=\"160\" y1=\"205\" x2=\"252\" y2=\"232\" stroke-width=\"1.2\" stroke-dasharray=\"4 4\" class=\"svg-stroke-soft\"/>\n\n        <!-- middle: magnified rigid segment -->\n        <path d=\"M 237,176 q 14,-9 28,-1\" fill=\"none\" stroke-width=\"9\" stroke-linecap=\"round\" class=\"svg-stroke-soft\"/>\n        <path d=\"M 445,175 q 14,8 28,0\" fill=\"none\" stroke-width=\"9\" stroke-linecap=\"round\" class=\"svg-stroke-soft\"/>\n        <rect x=\"265\" y=\"160\" width=\"180\" height=\"30\" rx=\"9\" stroke-width=\"2\" class=\"svg-stroke svg-fill-soft\"/>\n        <rect x=\"347\" y=\"167\" width=\"16\" height=\"16\" rx=\"2\" stroke-width=\"1.6\" class=\"svg-stroke svg-fill-soft\"/>\n        <!-- 3-axis arrows -->\n        <g stroke-width=\"2\" fill=\"none\" class=\"svg-stroke\">\n          <line x1=\"355\" y1=\"175\" x2=\"412\" y2=\"175\"/><polyline points=\"404,170 412,175 404,180\"/>\n          <line x1=\"355\" y1=\"175\" x2=\"355\" y2=\"122\"/><polyline points=\"350,130 355,122 360,130\"/>\n          <line x1=\"355\" y1=\"175\" x2=\"317\" y2=\"212\"/><polyline points=\"319,203 317,212 326,210\"/>\n        </g>\n        <text x=\"420\" y=\"179\" font-size=\"12\" class=\"svg-text-accent\">X</text>\n        <text x=\"350\" y=\"114\" font-size=\"12\" class=\"svg-text-accent\">Y</text>\n        <text x=\"305\" y=\"224\" font-size=\"12\" class=\"svg-text-accent\">Z</text>\n        <!-- flexible joint label -->\n        <line x1=\"251\" y1=\"166\" x2=\"251\" y2=\"140\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" class=\"svg-stroke-soft\"/>\n        <text x=\"251\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Flexible joint</text>\n        <text x=\"251\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">软管柔性铰链</text>\n        <text x=\"355\" y=\"250\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-en\">Rigid segment · 3-axis MEMS · 0–360°</text>\n        <text x=\"355\" y=\"250\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-zh\">硬管测量节段 · 三轴 MEMS · 0~360°</text>\n        <text x=\"355\" y=\"272\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-en\">Segment length = joint center to joint center · 0.3 / 0.5 / 1 m</text>\n        <text x=\"355\" y=\"272\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-zh\">单节长度＝软管中心到软管中心 · 0.3 / 0.5 / 1 m</text>\n\n        <!-- right: vector chain reconstruction -->\n        <path d=\"M 540,345 C 550,300 565,260 586,235 S 640,185 678,168\" fill=\"none\" stroke-width=\"2\" stroke-dasharray=\"5 5\" class=\"svg-stroke-soft\"/>\n        <g stroke-width=\"2.4\" fill=\"none\" class=\"svg-stroke\">\n          <line x1=\"540\" y1=\"345\" x2=\"558\" y2=\"288\"/><polyline points=\"551,294 558,288 560,297\"/>\n          <line x1=\"558\" y1=\"288\" x2=\"586\" y2=\"235\"/><polyline points=\"578,239 586,235 586,244\"/>\n          <line x1=\"586\" y1=\"235\" x2=\"628\" y2=\"193\"/><polyline points=\"619,195 628,193 626,202\"/>\n          <line x1=\"628\" y1=\"193\" x2=\"678\" y2=\"168\"/><polyline points=\"669,167 678,168 673,176\"/>\n        </g>\n        <text x=\"536\" y=\"318\" font-size=\"11.5\" class=\"svg-text-accent\">v1</text>\n        <text x=\"558\" y=\"262\" font-size=\"11.5\" class=\"svg-text-accent\">v2</text>\n        <text x=\"594\" y=\"216\" font-size=\"11.5\" class=\"svg-text-accent\">v3</text>\n        <text x=\"640\" y=\"186\" font-size=\"11.5\" class=\"svg-text-accent\">v4</text>\n        <text x=\"612\" y=\"382\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Segment vectors chained head-to-tail rebuild the shape</text>\n        <text x=\"612\" y=\"382\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">节段向量首尾相接，重构变形曲线</text>\n\n        <!-- footer badges -->\n        <text x=\"380\" y=\"410\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-accent lang-en\">Torsion correction better than 0.5° · Per-segment real-time temperature recording</text>\n        <text x=\"380\" y=\"410\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-accent lang-zh\">扭转校正优于 0.5° · 每节实时温度记录</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        Outputs: 3D shape curves, a per-segment orientation matrix and per-segment temperature records — synced automatically to the monitoring cloud.\n        \n      </div>\n    </div>\n    <div class=\"grid grid-3\" style=\"margin-top:42px;\">\n      <div class=\"card reveal\"><h3>01 · Sense</h3><p>Every rigid segment measures its 3-axis orientation across 0–360° and logs its own temperature in real time.</p></div>\n      <div class=\"card reveal\"><h3>02 · Flex</h3><p>Flexible joints between segments take the bending, so measurement and deformation are cleanly separated.</p></div>\n      <div class=\"card reveal\"><h3>03 · Reconstruct</h3><p>Segment vectors are chained into the 3D shape curve; torsion correction aligns all segments to one coordinate system, better than 0.5°.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== DATA SAMPLE ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Data output</div>\n      <h2>A Continuous Profile, One Point per Segment</h2>\n      <p>\n        Every rigid segment is a measurement point, so the array returns a continuous displacement profile with no blind spots — and because acquisition is automated, the deformation trajectory can be replayed in real time as it develops.\n        \n      </p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 420\" role=\"img\" aria-label=\"Representative shape-array output: displacement profile along the array position\">\n        <!-- grid -->\n        <line x1=\"214\" y1=\"60\" x2=\"214\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"338\" y1=\"60\" x2=\"338\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"462\" y1=\"60\" x2=\"462\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"586\" y1=\"60\" x2=\"586\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"90\" y1=\"180\" x2=\"710\" y2=\"180\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"90\" y1=\"240\" x2=\"710\" y2=\"240\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <line x1=\"90\" y1=\"300\" x2=\"710\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1\" opacity=\"0.35\"/>\n        <!-- axes -->\n        <line x1=\"90\" y1=\"60\" x2=\"90\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <path d=\"M 85.5 363 L 90 373 L 94.5 363\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <line x1=\"90\" y1=\"370\" x2=\"710\" y2=\"370\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <path d=\"M 703 365.5 L 713 370 L 703 374.5\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <!-- unitless ticks -->\n        <line x1=\"214\" y1=\"370\" x2=\"214\" y2=\"376\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"338\" y1=\"370\" x2=\"338\" y2=\"376\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"462\" y1=\"370\" x2=\"462\" y2=\"376\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"586\" y1=\"370\" x2=\"586\" y2=\"376\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"84\" y1=\"180\" x2=\"90\" y2=\"180\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"84\" y1=\"240\" x2=\"90\" y2=\"240\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <line x1=\"84\" y1=\"300\" x2=\"90\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n        <!-- axis labels -->\n        <text x=\"400\" y=\"394\" font-size=\"13.5\" text-anchor=\"middle\" class=\"svg-text-strong lang-en\">Array position (m)</text>\n        <text x=\"400\" y=\"394\" font-size=\"13.5\" text-anchor=\"middle\" class=\"svg-text-strong lang-zh\">阵列位置 (m)</text>\n        <text x=\"40\" y=\"215\" font-size=\"13.5\" text-anchor=\"middle\" transform=\"rotate(-90 40 215)\" class=\"svg-text-strong lang-en\">Displacement (mm)</text>\n        <text x=\"40\" y=\"215\" font-size=\"13.5\" text-anchor=\"middle\" transform=\"rotate(-90 40 215)\" class=\"svg-text-strong lang-zh\">位移 (mm)</text>\n        <!-- baseline -->\n        <line x1=\"95\" y1=\"120\" x2=\"700\" y2=\"120\" class=\"svg-stroke-soft\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n        <!-- successive automated readings -->\n        <polyline points=\"95,120 145,122 195,128 245,137 295,149 345,160 395,166 445,164 495,156 545,144 595,133 645,125 700,121\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\" opacity=\"0.35\"/>\n        <polyline points=\"95,121 145,125 195,135 245,153 295,177 345,199 395,211 445,209 495,192 545,168 595,145 645,130 700,122\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\" opacity=\"0.6\"/>\n        <polyline points=\"95,121 145,128 195,145 245,175 295,215 345,252 395,272 445,268 495,240 545,200 595,162 645,136 700,123\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2.5\"/>\n        <!-- segment nodes on latest reading -->\n        <g class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.4\">\n          <circle cx=\"95\" cy=\"121\" r=\"3.2\"/><circle cx=\"145\" cy=\"128\" r=\"3.2\"/><circle cx=\"195\" cy=\"145\" r=\"3.2\"/>\n          <circle cx=\"245\" cy=\"175\" r=\"3.2\"/><circle cx=\"295\" cy=\"215\" r=\"3.2\"/><circle cx=\"345\" cy=\"252\" r=\"3.2\"/>\n          <circle cx=\"395\" cy=\"272\" r=\"3.2\"/><circle cx=\"445\" cy=\"268\" r=\"3.2\"/><circle cx=\"495\" cy=\"240\" r=\"3.2\"/>\n          <circle cx=\"545\" cy=\"200\" r=\"3.2\"/><circle cx=\"595\" cy=\"162\" r=\"3.2\"/><circle cx=\"645\" cy=\"136\" r=\"3.2\"/>\n          <circle cx=\"700\" cy=\"123\" r=\"3.2\"/>\n        </g>\n        <!-- annotations -->\n        <line x1=\"595\" y1=\"159\" x2=\"612\" y2=\"112\" class=\"svg-stroke-soft\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n        <text x=\"616\" y=\"104\" font-size=\"12.5\" text-anchor=\"end\" class=\"svg-text lang-en\">Each point = one sensing segment</text>\n        <text x=\"616\" y=\"104\" font-size=\"12.5\" text-anchor=\"end\" class=\"svg-text lang-zh\">每个测点＝一节测量节段</text>\n        <line x1=\"395\" y1=\"278\" x2=\"395\" y2=\"310\" class=\"svg-stroke-soft\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n        <text x=\"395\" y=\"328\" font-size=\"12.5\" text-anchor=\"middle\" class=\"svg-text lang-en\">Profile rebuilt segment by segment — continuous, no blind spots</text>\n        <text x=\"395\" y=\"328\" font-size=\"12.5\" text-anchor=\"middle\" class=\"svg-text lang-zh\">剖面逐节段重构——连续无盲区</text>\n        <!-- legend -->\n        <line x1=\"95\" y1=\"412\" x2=\"130\" y2=\"412\" class=\"svg-stroke-soft\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n        <text x=\"138\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-en\">Initial survey (baseline)</text>\n        <text x=\"138\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-zh\">首测基准</text>\n        <line x1=\"330\" y1=\"412\" x2=\"365\" y2=\"412\" class=\"svg-stroke\" stroke-width=\"2.5\"/>\n        <text x=\"373\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-en\">Successive automated readings</text>\n        <text x=\"373\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-zh\">后续自动采集</text>\n        <circle cx=\"600\" cy=\"412\" r=\"3.2\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.4\"/>\n        <text x=\"610\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-en\">Segment node</text>\n        <text x=\"610\" y=\"416\" font-size=\"12.5\" class=\"svg-text lang-zh\">节段测点</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        Representative shape-array output: the displacement profile along a horizontally buried array, rebuilt segment by segment; successive automated readings trace the deformation as it develops. Axes are unitless for illustration.\n        \n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>Full Technical Specifications</h2>\n      <p>Segment lengths of 0.3 m, 0.5 m or 1 m to match your measurement-density requirements, with sampling up to 10 kHz for dynamic events.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">Specification (SCIS-SAA-02)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Measurement dimensions</td><td>3D (X/Y/Z)</td></tr>\n          <tr><td>Angular range</td><td>0 ~ 360°</td></tr>\n          <tr><td>Measurement accuracy</td><td class=\"hl\">±0.002° (0.02 mm / 500 mm)</td></tr>\n          <tr><td>Displacement resolution</td><td class=\"hl\">0.005 mm</td></tr>\n          <tr><td>System stability</td><td class=\"hl\">±0.3 mm / 30 m</td></tr>\n          <tr><td>Max bending angle</td><td>180°</td></tr>\n          <tr><td>Segment length</td><td>0.3 m / 0.5 m / 1 m options</td></tr>\n          <tr><td>Segments per cable</td><td>Up to 128 (AutoID auto-addressing)</td></tr>\n          <tr><td>Communication interface</td><td>RS-485 (Modbus RTU)</td></tr>\n          <tr><td>Ingress protection</td><td>IP68, 3 MPa water pressure (tested to 4 MPa)</td></tr>\n          <tr><td>Operating temperature</td><td>-40 ~ 60 ℃</td></tr>\n          <tr><td>Sampling rate</td><td>Up to 10 kHz</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== COMPETITIVE COMPARISON ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Engineering comparison</div>\n      <h2>Designed for Reuse, Integration and Field Service</h2>\n      <p>SCIS-SAA-02 uses field-assembled segments, so system length can follow each project and individual sections can be inspected, replaced or redeployed. This reduces transport, installation and lifecycle constraints common to fixed-length arrays.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap reveal\">\n      <table class=\"spec-table versus-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Dimension</th>\n            <th scope=\"col\">SoilCreate SCIS-SAA-02</th>\n            <th scope=\"col\">Conventional Fixed-Length SAA</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Sensor</td><td class=\"hl\">MEMS / high-end electrolytic-solution sensor</td><td>MEMS sensor</td></tr>\n          <tr><td>On-site assembly</td><td class=\"hl\">Segment-based field assembly; length adjusted on site</td><td>Factory-defined length; adjustment depends on supplier</td></tr>\n          <tr><td>Recovery &amp; reuse</td><td class=\"hl\">Designed for segment recovery and project-to-project redeployment</td><td>Depends on installation method and product configuration</td></tr>\n          <tr><td>Installation</td><td class=\"hl\">Centered installation in inclinometer casing</td><td>Installation method varies by project</td></tr>\n          <tr><td>Protection</td><td class=\"hl\">4 MPa standard; 8 MPa available by configuration</td><td>Varies by model</td></tr>\n          <tr><td>Data access</td><td class=\"hl\">Direct raw-data interface for system integration</td><td>Depends on the vendor software ecosystem</td></tr>\n          <tr><td>Weight</td><td class=\"hl\">~0.6 kg/m</td><td>Varies by configuration</td></tr>\n          <tr><td>Commercial model</td><td class=\"hl\">High-value project pricing with reusable hardware</td><td>Imported-system pricing and service model</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:42px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.6 kg/m</div><div class=\"name\">Lightweight Array</div><p>Lower transport, hoisting and on-site handling effort.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">VALUE</div><div class=\"name\">High-Value Pricing</div><p>World-leading accuracy with pricing designed for engineering deployment.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">REUSE</div><div class=\"name\">Recoverable &amp; Reusable</div><p>Dismantle, inspect and redeploy the array after project completion.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">360°</div><div class=\"name\">All-Direction Deployment</div><p>Vertical, horizontal and ring layouts from one product.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== DEPLOYMENT & CORE FEATURES ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Deployment</div>\n      <h2>Three Deployment Modes, One Product</h2>\n      <p>Vertical for inclinometry, horizontal for settlement, ring for convergence — the flexible structure adapts wherever rigid probes cannot go.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v16\"/><path d=\"M8 14l4 4 4-4\"/><path d=\"M5 22h14\"/></svg></div><h3>Vertical · Inclinometry</h3><p>Deep displacement of foundation pits and slopes. Drops straight into the inclinometer casing — no guide wheels needed. The most common scenario.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 12h16\"/><path d=\"M14 8l4 4-4 4\"/><path d=\"M2 19c4-2 8 2 12 0s6-1 8 0\" opacity=\"0.5\"/></svg></div><h3>Horizontal · Settlement</h3><p>Settlement of subgrades and rockfill dams — buried in a trench inside a PVC conduit, pulled in by wire rope from one end.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 3a9 9 0 0 1 9 9\" stroke-dasharray=\"2 3\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></div><h3>Ring · Convergence</h3><p>Tunnel cross-section convergence — laid circumferentially along the wall or lining segments; the flexible structure naturally follows the curve.</p></div>\n    </div>\n\n    <div class=\"split\" style=\"margin-top:64px;\">\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Core features</div>\n        <h2 style=\"font-size:26px; margin-bottom:16px;\">\n          Built around two core capabilities\n          \n        </h2>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Segmented &amp; recoverable</b><p>Segmented design → flexible on-site assembly → dismantled &amp; recovered at project end → transported to the next project → lower hardware amortization cost.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Torsion correction</b><p>Built-in algorithm detects axial torsion → auto-computes azimuth → aligns to a unified coordinate system → correction accuracy better than 0.5°.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>AutoID + RS485 bus</b><p>One cable chains up to 128 segments with automatic addressing — simple wiring, open protocol, ready for any logger or platform.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"visual reveal\"><img src=\"/images/products/flexible-inclinometer/flexible-inclinometer-segments.jpg\" alt=\"Rack of assembled SCIS-SAA-02 stainless-steel sensing segments with flexible hinges\" width=\"1000\" height=\"954\" decoding=\"async\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== INSTALLATION: VERTICAL & HORIZONTAL PATHS ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation</div>\n      <h2>Installation: Vertical &amp; Horizontal Paths</h2>\n      <p>The deployment modes above tell you where the array goes — this is how it gets there. Vertical (chained in casing) and horizontal (trench-laid) follow two entirely different procedures that are not interchangeable: confirm which one applies before work starts.</p>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card reveal\">\n        <h3>Vertical — chained inside the casing</h3>\n        <ul class=\"feature-list\" style=\"margin-top:14px;\">\n          <li><span class=\"fi\">1</span><div><b>Prepare the casing</b><p>Seal the casing bottom and fill the casing with clean water.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Connect the controller</b><p>The lead-out cable at the top of the array connects to the controller.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Lower top-down</b><p>Lower the array into the casing from the top; slight bending is allowed at each flexible joint.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Fix and protect</b><p>Fix the array at the top and fit a protective device on the casing mouth.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Casing twist self-corrects</b><p>If the casing twists during monitoring, the rotation it imparts to the array is corrected automatically by the torsion-correction algorithm.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Horizontal — trench + PVC conduit</h3>\n        <p style=\"margin-top:10px; font-size:14px;\">Ships as a kit: PVC conduit matched to the run, end caps and mouth fittings, traction wire rope and marker posts.</p>\n        <ul class=\"feature-list\" style=\"margin-top:14px;\">\n          <li><span class=\"fi\">1</span><div><b>Excavate the trench</b><p>Trench bottom flat and level, length matched — avoid local dips.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Lay the conduit</b><p>Every PVC conduit seam must be sealed with PVC primer + cement — otherwise water gets in later.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Pull in — never push</b><p>Pull the array into the conduit with the wire rope from one end. Pushing destabilizes the flexible joints and damages the hinges.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Check every bend radius</b><p>At any curve the bend radius must stay ≥ R<sub>min</sub> (about 0.3 m); any section below the limit is re-laid.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Finish &amp; seal</b><p>Waterproof the lead-out end and seal the end caps.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"section-head reveal\" style=\"margin-top:56px;\">\n      <h2 style=\"font-size:24px;\">After Burial: Remote Inspection for Horizontal Layouts</h2>\n      <p>A horizontal run leaves nothing visible at the surface — periodic inspection happens remotely on the cloud platform.</p>\n    </div>\n    <div class=\"grid grid-4\">\n      <div class=\"number-card reveal\"><div class=\"num\">1×/wk</div><div class=\"name\">Curve-Shape Check</div><p>Review the overall displacement-curve shape remotely every week.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1×/mo</div><div class=\"name\">Temperature Comparison</div><p>Compare readings against same-period per-segment temperature records.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1×/qtr</div><div class=\"name\">Benchmark Check</div><p>Verify benchmark stability to separate true displacement from foundation movement.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1×/yr</div><div class=\"name\">Metrology Spot Test</div><p>Send for a metrology-institute spot calibration every year.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== STRUCTURE GALLERY ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Gallery</div>\n      <h2>Assembly &amp; Structure in Detail</h2>\n    </div>\n    <div class=\"gallery\">\n      <figure class=\"reveal\"><img src=\"/images/products/flexible-inclinometer/saa-structure-folded.jpg\" alt=\"CAD rendering of the flexible inclinometer array: rigid sensing tubes alternating with flexible joints, folded flat\" loading=\"lazy\" width=\"848\" height=\"1515\" decoding=\"async\"><figcaption>Rigid sensing tubes alternate with flexible joints — the array folds flat for transport and recovery.</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/flexible-inclinometer/saa-convergence-monitoring.svg\" alt=\"SAA flexible array installed around a tunnel section for convergence monitoring\" loading=\"lazy\" width=\"1200\" height=\"760\" decoding=\"async\"><figcaption>Ring installation around a tunnel section — the flexible array tracks convergence along the lining curve.</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/flexible-inclinometer/saa-reel-rack.jpg\" alt=\"CAD rendering of the assembled array folded on its deployment stand\" loading=\"lazy\" width=\"860\" height=\"484\" decoding=\"async\"><figcaption>Assembled array folded on its deployment stand, ready to pay out on site.</figcaption></figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== LIFECYCLE VALUE & VALIDATION ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Lifecycle value</div>\n      <h2>Every Segment Is a Reusable Asset</h2>\n      <p>Recovered segments can be inspected and configured for a new project, allowing the same hardware investment to serve multiple deployments and reducing lifecycle cost with each reuse.</p>\n    </div>\n    <div class=\"grid grid-4\">\n      <div class=\"number-card reveal\"><div class=\"num\">01</div><div class=\"name\">Initial Deployment</div><p>Modular assembly — installed by 2 people in 30 minutes.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">02</div><div class=\"name\">Monitoring</div><p>Automated acquisition, zero manual effort.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">03</div><div class=\"name\">Project End</div><p>Dismantled and recovered segment by segment.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">04</div><div class=\"name\">Multi-Project Amortization</div><p>Hardware cost falls with each reuse.</p></div>\n    </div>\n\n    <div class=\"split\" style=\"margin-top:64px;\">\n      <div class=\"visual reveal\"><img src=\"/images/products/flexible-inclinometer/saa-displacement-profile.jpg\" alt=\"Cumulative deep-displacement profile curves recorded by automated flexible inclinometer monitoring\" style=\"background:#fff; border-radius:8px; padding:10px;\" width=\"499\" height=\"824\" decoding=\"async\">\n        <p style=\"margin-top:10px; font-size:13px; color:var(--text-3); text-align:center;\">Real monitoring output: cumulative deep-displacement profiles — depth on the vertical axis, displacement on the horizontal; successive automated readings trace the deformation history.</p>\n      </div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Same-borehole validation</div>\n        <h2 style=\"font-size:26px; margin-bottom:16px;\">\n          Shaoxing Metro Line 2: validated against the sliding inclinometer\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          At Paojiang Lianghu Station, a flexible and a sliding inclinometer were installed just 20 cm apart in the same borehole. Over six months, A-axis displacement trends matched closely — proving automated SAA monitoring can fully replace manual sliding surveys with equally reliable data.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Method</b><p>Two sensor types buried 20 cm apart in the same borehole.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Duration</b><p>6+ months of continuous monitoring.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Result</b><p>A-axis trends matched closely; the two datasets mutually verified.</p></div></li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SAA vs IPI SELECTION ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Selection guide</div>\n      <h2>SAA or In-Place Inclinometer — Which to Choose?</h2>\n      <p>A simple rule: complex large deformation, settlement or convergence — choose the flexible SAA. Vertical deep boreholes where small displacements matter — choose the in-place inclinometer. Combining the two delivers the best results.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 3\" data-aria-en=\"Scrollable technical table 3\" data-aria-zh=\"可横向滚动的技术参数表 3\" class=\"table-wrap reveal\">\n      <table class=\"spec-table versus-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Feature</th>\n            <th scope=\"col\">Flexible Inclinometer (SAA)</th>\n            <th scope=\"col\">In-Place Inclinometer (IPI)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Structure</td><td>Flexible joints, bendable</td><td>Rigid rod, must stay straight</td></tr>\n          <tr><td>Measurement density</td><td class=\"hl\">Continuous, no blind spots</td><td>Discrete (1–3 m spacing)</td></tr>\n          <tr><td>Range</td><td class=\"hl\">0–360°, hard to exceed range</td><td>±15° / ±30°</td></tr>\n          <tr><td>Deployment</td><td class=\"hl\">Vertical / horizontal / ring</td><td>Mainly vertical</td></tr>\n          <tr><td>Weight</td><td>~0.6 kg/m</td><td>Carbon fiber 0.12 kg/m (lighter)</td></tr>\n          <tr><td>Best for</td><td class=\"hl\">Complex large deformation / settlement / convergence</td><td>Small displacements in vertical deep boreholes</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p class=\"reveal\" style=\"margin-top:26px; color:var(--text-2);\">\n      Monitoring a vertical deep borehole with small displacements? \n      <a href=\"/products/deformation-monitoring/in-place-inclinometer\" style=\"color:var(--accent); font-weight:600;\">Explore the In-Place Inclinometer →</a>\n    </p>\n  </div>\n</section>\n\n<!-- ====== CASE STUDIES ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Track record</div>\n      <h2>Four Benchmark Case Studies</h2>\n      <p>From same-borehole validation to a tidal pattern no human survey could ever catch — each case proves a different capability.</p>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card reveal\">\n        <span class=\"tag\">Same-borehole · 2022</span>\n        <h3 style=\"margin-top:12px;\">Shaoxing Metro Line 2 · Paojiang Lianghu Station</h3>\n        <p>Flexible and sliding inclinometers installed 20 cm apart in the same borehole. Six months of monitoring: A-axis trends matched closely — automation reliably replaces manual surveys.</p>\n      </div>\n      <div class=\"card reveal\">\n        <span class=\"tag\">Alert validation · 2020</span>\n        <h3 style=\"margin-top:12px;\">Suzhou Metro Line 5 · Jinchu Street Station</h3>\n        <p>Automated monitoring triggered a displacement-rate alert, catching sudden displacement from delayed strut installation — proof of high-frequency response to sudden conditions.</p>\n      </div>\n      <div class=\"card reveal\">\n        <span class=\"tag\">Tidal finding · 2023</span>\n        <h3 style=\"margin-top:12px;\">Suzhou Xiangcheng Foundation Pit</h3>\n        <p>High-frequency sampling revealed twice-daily periodic fluctuation of the retaining structure — a tidal deformation pattern undetectable by manual surveys, linking groundwater level to structural deformation.</p>\n      </div>\n      <div class=\"card reveal\">\n        <span class=\"tag\">300 m borehole · 2022</span>\n        <h3 style=\"margin-top:12px;\">Baihetan Hydropower Station · Ultra-Deep Borehole</h3>\n        <p>High-precision monitoring in a 300 m-class ultra-deep borehole, operating stably long-term in harsh conditions — product reliability proven under extreme conditions.</p>\n      </div>\n    </div>\n    <p class=\"reveal\" style=\"margin-top:28px; color:var(--text-3); font-size:14.5px;\">\n      More deployments: Hangzhou Metro Line 3 · Qingdao Jiaozhou Bay Tunnel (65 units) · Shanghai Metro Line 18 · Nanning CNPC pipeline geohazard monitoring\n      \n    </p>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Frequently Asked Questions</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>Horizontal settlement profiles or tunnel convergence rings — flexible array or in-place inclinometer?</summary>\n        <div class=\"faq-body\">Choose the flexible array. The in-place inclinometer (IPI) is a rigid-rod string deployed mainly vertically, while the flexible array installs vertically, horizontally or in curved/ring layouts. For subgrade and rockfill-dam settlement it is trench-buried horizontally; for tunnel cross-section convergence it is laid circumferentially along the wall or lining segments. The rule works both ways: in a vertical deep borehole where small displacements dominate, the IPI is the better fit — and combining the two delivers the best results.</div>\n      </details>\n      <details>\n        <summary>Does vertical installation need inclinometer casing with guide grooves?</summary>\n        <div class=\"faq-body\">No. The array drops straight into the casing with no guide wheels, and no casing guide grooves are needed. Forced centering inside the casing keeps the array tightly fitted against the casing wall.</div>\n      </details>\n      <details>\n        <summary>What is the minimum bend radius?</summary>\n        <div class=\"faq-body\">Flexible does not mean \"bend freely\": at any curve the bend radius must stay at or above R<sub>min</sub>, about 0.3 m. Bending below that limit sharply shortens the array's design life, so any non-conforming section is re-laid rather than delivered.</div>\n      </details>\n      <details>\n        <summary>Can I push the array into the conduit on a horizontal run?</summary>\n        <div class=\"faq-body\">Never. Pushing destabilizes the flexible joints and can damage the hinges. The array is always pulled into the PVC conduit with a wire rope from the far end.</div>\n      </details>\n      <details>\n        <summary>How does recovery and reuse work between projects?</summary>\n        <div class=\"faq-body\">At project end the array is dismantled and recovered segment by segment, inspected, shipped to the next site and re-assembled to the length required by the new project. Modular assembly takes 2 people about 30 minutes, and each qualified reuse reduces lifecycle hardware cost.</div>\n      </details>\n      <details>\n        <summary>How is axial torsion handled?</summary>\n        <div class=\"faq-body\">A built-in algorithm detects axial torsion, computes the azimuth and aligns all segments to a unified coordinate system, with correction accuracy better than 0.5°. In vertical installs, twist imparted by the casing during monitoring is corrected automatically.</div>\n      </details>\n      <details>\n        <summary>How do I inspect and maintain a horizontal layout once it is buried?</summary>\n        <div class=\"faq-body\">Remotely, on the cloud platform: check the overall curve shape weekly, compare same-period temperature records monthly, verify benchmark stability quarterly, and send for a metrology-institute spot test yearly. A single drifting segment can be located remotely and just that segment lifted; data-uplink interruptions (controller power, 4G link, SIM) are diagnosed remotely first.</div>\n      </details>\n      <details>\n        <summary>The whole curve jumped — or has drifted slowly for months. What does each signature mean?</summary>\n        <div class=\"faq-body\">A sudden jump across the entire curve indicates a broken flexible joint: the full array is lifted and re-laid. Long-term slow drift usually means the trench itself is settling and dragging the array — reconcile readings against the benchmark point to separate true displacement from foundation movement. A drift surge on one single segment points instead to sensor damage or water ingress in that segment; it is located remotely so only that segment needs lifting.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "gnss-monitoring-system": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>GNSS Monitoring System</span>\n    </div>\n    <h1>GNSS Monitoring System</h1>\n    <p class=\"sub\">\n      An all-in-one, all-constellation GNSS receiver for millimetre-level 3D surface-displacement monitoring. BeiDou short-message keeps remote sites reporting even where there is no cellular network at all.\n      \n    </p>\n    <div class=\"model\">SCIS-GNSS-100 · ALL-CONSTELLATION · MM-LEVEL</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/gnss-monitoring-system/gnss-monitoring-station.jpg\" alt=\"SCIS-GNSS-100 GNSS monitoring station with mushroom dome antenna and solar panels\" width=\"900\" height=\"900\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Millimetre-level displacement, anywhere the sky is open\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          The SCIS-GNSS-100 pairs a base station on stable bedrock with rover stations on the deformation body. RTK double-difference carrier-phase processing cancels clock and atmospheric errors, then fixes integer ambiguities to deliver millimetre-level 3D displacement in real time — around the clock, in any weather, with no line of sight required between points.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>All-constellation, BDS-3 triple-frequency</b><p>Tracks GPS, GLONASS, Galileo and BDS-3; B1C/B2a/B3I triple-frequency cancels first-order ionospheric error, holding mm-level accuracy on baselines up to 30 km.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>BeiDou short-message for no-network sites</b><p>Where there is no cellular coverage, monitoring data returns via BeiDou short message — ideal for slopes deep in remote mountains.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Low-power all-in-one</b><p>Receiver, antenna and comms in one sealed unit drawing under 1.2 W — a small solar panel keeps it running, plug-and-play.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Kalman + sidereal-day filtering</b><p>The AI layer denoises with Kalman and sidereal-day filtering, suppressing repeating multipath errors and pushing long-term noise to 1–2 mm.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">±2.5 mm</div><div class=\"name\">Static Accuracy (+0.5 ppm)</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">&lt;1.2 W</div><div class=\"name\">Power Consumption</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">4</div><div class=\"name\">Constellations Tracked</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">30 km</div><div class=\"name\">mm-Level Baseline (BDS-3)</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Working principle</div>\n      <h2>RTK Double-Difference: How Millimetres Emerge From Space</h2>\n      <p>A base station on stable bedrock and a rover on the monitored structure observe the carrier phase of the same satellites. Differencing across the two receivers and across two satellites cancels the dominant error sources — what remains is pure geometry plus an integer ambiguity that, once fixed, unlocks millimetre-level relative displacement.</p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 420\" role=\"img\" aria-label=\"RTK double-difference geometry: two satellites observed by a base station on bedrock and a rover on the monitored slope\">\n        <!-- satellites -->\n        <g>\n          <rect x=\"148\" y=\"36\" width=\"34\" height=\"20\" rx=\"4\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n          <rect x=\"118\" y=\"40\" width=\"24\" height=\"12\" rx=\"2\" class=\"svg-fill-soft\"/>\n          <rect x=\"188\" y=\"40\" width=\"24\" height=\"12\" rx=\"2\" class=\"svg-fill-soft\"/>\n          <text x=\"165\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Satellite i</text>\n          <text x=\"165\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">卫星 i</text>\n        </g>\n        <g>\n          <rect x=\"562\" y=\"36\" width=\"34\" height=\"20\" rx=\"4\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n          <rect x=\"532\" y=\"40\" width=\"24\" height=\"12\" rx=\"2\" class=\"svg-fill-soft\"/>\n          <rect x=\"602\" y=\"40\" width=\"24\" height=\"12\" rx=\"2\" class=\"svg-fill-soft\"/>\n          <text x=\"579\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Satellite j</text>\n          <text x=\"579\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">卫星 j</text>\n        </g>\n        <!-- terrain -->\n        <path d=\"M30 330 L250 330 L470 330 Q560 318 620 282 Q680 248 730 240 L730 360 L30 360 Z\" class=\"svg-fill-soft\" stroke=\"none\"/>\n        <!-- bedrock block under base -->\n        <rect x=\"120\" y=\"306\" width=\"120\" height=\"24\" rx=\"4\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <line x1=\"130\" y1=\"330\" x2=\"146\" y2=\"310\" stroke-width=\"1.4\" class=\"svg-stroke-soft\"/>\n        <line x1=\"156\" y1=\"330\" x2=\"172\" y2=\"310\" stroke-width=\"1.4\" class=\"svg-stroke-soft\"/>\n        <line x1=\"182\" y1=\"330\" x2=\"198\" y2=\"310\" stroke-width=\"1.4\" class=\"svg-stroke-soft\"/>\n        <line x1=\"208\" y1=\"330\" x2=\"224\" y2=\"310\" stroke-width=\"1.4\" class=\"svg-stroke-soft\"/>\n        <!-- base station -->\n        <line x1=\"180\" y1=\"306\" x2=\"180\" y2=\"240\" stroke-width=\"3\" class=\"svg-stroke\"/>\n        <circle cx=\"180\" cy=\"232\" r=\"9\" fill=\"none\" stroke-width=\"2.5\" class=\"svg-stroke\"/>\n        <text x=\"180\" y=\"352\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Base station · stable bedrock</text>\n        <text x=\"180\" y=\"352\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">基准站 · 稳定基岩</text>\n        <!-- rover station on slope -->\n        <line x1=\"620\" y1=\"282\" x2=\"620\" y2=\"216\" stroke-width=\"3\" class=\"svg-stroke\"/>\n        <circle cx=\"620\" cy=\"208\" r=\"9\" fill=\"none\" stroke-width=\"2.5\" class=\"svg-stroke\"/>\n        <text x=\"620\" y=\"312\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Rover · monitored structure</text>\n        <text x=\"620\" y=\"312\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">监测站 · 变形体</text>\n        <!-- observation lines: sat i -->\n        <line x1=\"168\" y1=\"60\" x2=\"179\" y2=\"220\" stroke-width=\"1.6\" stroke-dasharray=\"6 5\" class=\"svg-stroke\"/>\n        <line x1=\"186\" y1=\"58\" x2=\"612\" y2=\"200\" stroke-width=\"1.6\" stroke-dasharray=\"6 5\" class=\"svg-stroke\"/>\n        <!-- observation lines: sat j -->\n        <line x1=\"560\" y1=\"58\" x2=\"188\" y2=\"226\" stroke-width=\"1.6\" stroke-dasharray=\"2 5\" class=\"svg-stroke-soft\"/>\n        <line x1=\"582\" y1=\"60\" x2=\"620\" y2=\"196\" stroke-width=\"1.6\" stroke-dasharray=\"2 5\" class=\"svg-stroke-soft\"/>\n        <text x=\"390\" y=\"106\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-en\">Same satellites, same carrier phase Φ — observed by both receivers</text>\n        <text x=\"390\" y=\"106\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-zh\">两台接收机同时观测同一组卫星的载波相位 Φ</text>\n        <!-- correction link base -> rover -->\n        <path d=\"M200 250 Q 400 200 600 222\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n        <path d=\"M600 222 l-14 -3 l8 12 z\" class=\"svg-fill-soft\" stroke=\"none\"/>\n        <text x=\"400\" y=\"186\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-accent\">RTCM 3.x · 4G / UHF / NTRIP</text>\n        <!-- double-difference chain -->\n        <rect x=\"60\" y=\"378\" width=\"640\" height=\"0\" fill=\"none\"/>\n        <text x=\"380\" y=\"264\" text-anchor=\"middle\" font-size=\"14\" class=\"svg-text-accent\">ΔΦ = (Φᵣⁱ − Φᵦⁱ) − (Φᵣʲ − Φᵦʲ)</text>\n        <text x=\"380\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-en\">clock errors + most atmospheric delay cancel</text>\n        <text x=\"380\" y=\"288\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-zh\">钟差与大部分大气延迟相互抵消</text>\n        <!-- output chain -->\n        <text x=\"380\" y=\"398\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-en\">Integer ambiguity fixed (LAMBDA, 1–60 s) → fixed solution → Kalman + sidereal-day filtering → mm-level displacement</text>\n        <text x=\"380\" y=\"398\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-zh\">整周模糊度固定（LAMBDA，1–60 秒）→ 固定解 → 卡尔曼 + 恒星日滤波 → 毫米级位移</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        Double-difference geometry: receiver-pair and satellite-pair differencing leaves only the baseline geometry and the integer ambiguity N.\n        \n      </div>\n    </div>\n    <div class=\"grid grid-3\" style=\"margin-top:32px;\">\n      <div class=\"card reveal\">\n        <h3>Difference Twice</h3>\n        <p>Differencing the carrier phase between the two receivers and between two satellites cancels receiver clock error, satellite clock error and most of the atmospheric delay — the errors never need to be measured, only cancelled.</p>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Fix the Ambiguity</h3>\n        <p>The remaining unknown is the integer number of carrier wavelengths. The LAMBDA algorithm resolves it to whole numbers within 1–60 s — the \"fixed solution\" — at which point positioning enters the millimetre regime. Corrections stream from base to rover as standard RTCM 3.x.</p>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Average Down the Noise</h3>\n        <p>Short-baseline RTK delivers ±8 mm + 1 ppm horizontal and ±15 mm + 1 ppm vertical; for long-term monitoring, minute-level epoch averaging compresses the noise floor to 1–2 mm.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>SCIS-GNSS-100 Technical Specifications</h2>\n      <p>RTCM 3.x standard corrections, four communication options plus BeiDou short message, and a power budget small enough for a single solar panel.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">SCIS-GNSS-100</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Constellations</td><td>GPS / GLONASS / Galileo / BDS-3</td></tr>\n          <tr><td>Static accuracy</td><td class=\"hl\">±2.5 mm + 0.5 ppm</td></tr>\n          <tr><td>Dynamic accuracy (RTK)</td><td>±8 mm + 1 ppm horizontal · ±15 mm + 1 ppm vertical</td></tr>\n          <tr><td>Long-term monitoring noise</td><td class=\"hl\">1–2 mm with epoch averaging</td></tr>\n          <tr><td>Correction protocol</td><td>RTCM 3.x</td></tr>\n          <tr><td>Communication</td><td>4G / NB-IoT / LoRa / UHF + BeiDou short message</td></tr>\n          <tr><td>Denoising</td><td>Kalman + sidereal-day filtering</td></tr>\n          <tr><td>Power supply</td><td>DC 12–36 V, solar / mains</td></tr>\n          <tr><td>Power consumption</td><td class=\"hl\">&lt; 1.2 W</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px;\">\n      <h2 style=\"font-size:24px;\">Deployed the Right Way, So the Data Can Be Trusted</h2>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21h18\"/><path d=\"M12 3l8 8H4l8-8z\"/><path d=\"M12 11v10\"/></svg></div><h3>Base Station on Stable Bedrock</h3><p>The base sits on known, stable ground and is verified by periodic static comparison — if the reference moves, every reading is suspect.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20\"/><path d=\"M12 2v20\"/></svg></div><h3>Clear 15° Horizon</h3><p>Obstructions are kept below a 15° elevation angle to maximize visible satellites; rigid antenna mounts keep self-vibration out of the data.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div><h3>Dual Links + Quality Flags</h3><p>4G primary with UHF backup; the cloud flags any station whose fixed-solution rate drops below 80% for review before issuing an alert.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== COMPETITIVE COMPARISON ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Benchmarked</div>\n      <h2>All-In-One Design vs. Imported-Module Receivers</h2>\n      <p>Many monitoring receivers on the market are built around third-party OEM modules — which shows up as complex setup, higher power draw and higher cost. The SCIS-GNSS-100 takes a different route: a fully in-house technology stack in one sealed unit.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap reveal\">\n      <table class=\"spec-table versus-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Dimension</th>\n            <th scope=\"col\">SoilCreate SCIS-GNSS-100</th>\n            <th scope=\"col\">Imported-module receivers</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Core technology</td><td class=\"hl\">Fully in-house technology stack</td><td>Built around imported OEM modules</td></tr>\n          <tr><td>Commissioning</td><td class=\"hl\">All-in-one, plug-and-play</td><td>Complex setup and configuration</td></tr>\n          <tr><td>No-network sites</td><td class=\"hl\">BeiDou short-message fallback</td><td>Cellular only — data gaps</td></tr>\n          <tr><td>Power draw</td><td class=\"hl\">&lt; 1.2 W — small solar panel</td><td>Higher draw, larger solar arrays</td></tr>\n          <tr><td>Total cost</td><td class=\"hl\">High-value system pricing</td><td>Varies by module and service scope</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SITE INSTALLATION ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation</div>\n      <h2>Site Installation: Geometry and Links First</h2>\n      <p>GNSS monitoring accuracy is decided as much by where and how stations are installed as by the receiver itself. Five field rules from the installation manual.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Plan the baseline length first</b><p>Under 10 km is the RTK comfort zone. At 10–30 km, mid-baseline parameters need adjustment; beyond 30 km, upgrade to PPP or a multi-base-station network.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Mount the rover rigidly</b><p>The rover antenna connects rigidly to the monitored foundation — typically a concrete pier or steel frame. A flexible mount lets the antenna's own vibration enter the displacement data.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Run dual communication links</b><p>4G as the primary link with UHF as redundant backup. A 4G-only setup in mountainous or below-grade terrain is prone to data loss.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Size the power with margin</b><p>Solar systems are sized for 7 days of overcast plus a 30% safety reserve. With mains power, plan for outages — the often-overlooked failure mode.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Inspect link quality weekly</b><p>4G signal quality at urban fringes degrades over time. A weekly link-quality check keeps RTK from silently degrading toward single-point positioning.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"visual reveal\"><img src=\"/images/products/gnss-monitoring-system/gnss-station-slope.jpg\" alt=\"GNSS monitoring station installed on a slope, overlooking the valley\" loading=\"lazy\" width=\"1000\" height=\"813\" decoding=\"async\"></div>\n    </div>\n    <div class=\"gallery\" style=\"margin-top:40px;\">\n      <figure class=\"reveal\">\n        <img src=\"/images/products/gnss-monitoring-system/gnss-station-solar.jpg\" alt=\"GNSS monitoring station on a concrete pier with solar panels\" loading=\"lazy\" width=\"531\" height=\"535\" decoding=\"async\">\n        <figcaption>Rover station on a concrete pier — rigid mounting with solar supply</figcaption>\n      </figure>\n      <figure class=\"reveal\">\n        <img src=\"/images/products/gnss-monitoring-system/gnss-station-ridge.jpg\" alt=\"GNSS monitoring station deployed beside a cut slope\" loading=\"lazy\" width=\"362\" height=\"503\" decoding=\"async\">\n        <figcaption>Slope-site deployment with open sky above the 15° elevation mask</figcaption>\n      </figure>\n      <figure class=\"reveal\">\n        <img src=\"/images/products/gnss-monitoring-system/gnss-receiver-base.jpg\" alt=\"Underside of the all-in-one GNSS receiver showing mounting and connector interfaces\" loading=\"lazy\" width=\"232\" height=\"221\" decoding=\"async\">\n        <figcaption>All-in-one receiver underside: mounting and connector interfaces</figcaption>\n      </figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== APPLICATIONS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Applications</div>\n      <h2>Where the SCIS-GNSS-100 Earns Its Keep</h2>\n      <p>Continuous, unattended surface-displacement monitoring — from unstaffed mountain slopes to dam crests and long-span bridges.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><span class=\"tag\">Geohazard</span><h3 style=\"margin-top:12px;\">Slopes &amp; Landslides in Remote Mountains</h3><p>Solar power plus BeiDou short-message suit unattended sites far beyond cellular coverage; pairs with flexible inclinometers and water level gauges as a standardized geohazard early-warning kit.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Hydropower</span><h3 style=\"margin-top:12px;\">Dam Crest Deformation</h3><p>Continuous 3D displacement of the dam crest and abutments; sidereal-day filtering separates true movement from repeating multipath, supporting long-term trend analysis.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Bridge</span><h3 style=\"margin-top:12px;\">Bridge Towers &amp; Main Girders</h3><p>Tracks tower tilt and girder deformation through wind, temperature and traffic loading — all-weather, day and night, with no line of sight required.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Frequently Asked Questions</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>Our site has no cellular network at all. Can it still report?</summary>\n        <div class=\"faq-body\">Yes. The SCIS-GNSS-100 supports BeiDou short message in addition to 4G / NB-IoT / LoRa / UHF, so monitoring data returns via satellite where there is no cellular coverage — the typical case for slopes deep in remote mountains.</div>\n      </details>\n      <details>\n        <summary>How long can the baseline between base and rover be?</summary>\n        <div class=\"faq-body\">Under 10 km is the RTK comfort zone. From 10–30 km, mid-baseline parameters need adjustment; beyond 30 km, the system should move to PPP or a multi-base-station network. With BDS-3 B1C/B2a/B3I triple-frequency, the first-order ionospheric error cancels in hardware and millimetre-level accuracy holds out to 30 km on a single baseline.</div>\n      </details>\n      <details>\n        <summary>What is a \"fixed solution\", and why does its rate matter?</summary>\n        <div class=\"faq-body\">A fixed solution means the carrier-phase integer ambiguity has been resolved to whole numbers — the precondition for millimetre-level output. If the link degrades and RTK falls back toward single-point positioning, accuracy drops from millimetres to metres and can masquerade as a sudden \"displacement jump\". That is why the platform tracks the fixed-solution rate separately: a station below 80% is flagged for link review, and a sub-80% rate is never used as the sole basis for a deformation conclusion — it is cross-validated with hydrostatic levelling, tilt and other measurements.</div>\n      </details>\n      <details>\n        <summary>The station sees few satellites or the fixed rate is low. What do I check?</summary>\n        <div class=\"faq-body\">Few satellites usually means obstructions inside the 15° elevation mask — relocate the antenna. A persistently low fixed rate often points to multipath from nearby reflective surfaces — fit a choke-ring (anti-multipath) antenna. If RTK will not converge at all, the 4G/LoRa link is the usual suspect: switch links. A long-term slow drift in the data calls for a static comparison of the base station itself.</div>\n      </details>\n      <details>\n        <summary>How long can a station run on solar power alone?</summary>\n        <div class=\"faq-body\">The receiver draws under 1.2 W, and solar systems are sized to the field rule of 7 days of continuous overcast plus a 30% safety reserve — so a small panel sustains unattended operation through extended bad weather.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "hydrostatic-level-gauge": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Settlement Monitoring</span>\n    </div>\n    <h1>Settlement Monitoring</h1>\n    <p class=\"sub\">\n      Hydrostatic level gauges across three measurement principles and three range bands — 0.01&nbsp;mm resolution, ranges to 2000&nbsp;mm — plus layered settlement gauges for subgrade consolidation, covering everything from routine foundation pits to precision engineering.\n      \n    </p>\n    <div class=\"model\">SCST 01/02 · RLS · HYDROSTATIC + MAGNETOSTRICTIVE</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/hydrostatic-level-gauge/hydrostatic-level-gauge-product.jpg\" alt=\"SCST hydrostatic level gauge with precision-machined chamber and tubing connectors\" width=\"512\" height=\"458\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Sub-millimeter settlement, from one pit to a whole district\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          Hydrostatic leveling networks measure each point's settlement relative to a stable reference cell using the connected-vessel principle. SoilCreate offers three sensing principles — differential-pressure, magnetostrictive and ultrasonic — so the right physics is matched to each project's range and accuracy needs. On most structures they are deployed together with our <a href=\"/products/settlement-tilt-monitoring/tiltmeter-series\" style=\"color:var(--accent);\">tiltmeter series</a> for a complete deformation picture.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Three principles, three range bands</b><p>From 0–200 mm best-value monitoring to 0–2000 mm extra-large range and ultra-high-accuracy non-contact measurement.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>0.01 mm-class resolution</b><p>Resolves the slow, small settlements that decide whether a structure is safe — long before they are visible.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>RS485 to DAQ &amp; cloud</b><p>Every gauge feeds the SoilCreate data loggers and Monitoring Cloud for automated, unattended operation.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.01 mm</div><div class=\"name\">Resolution / Accuracy</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">0–2000 mm</div><div class=\"name\">Maximum Range</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">3</div><div class=\"name\">Measurement Principles</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">RS485</div><div class=\"name\">Bus Output</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>One Liquid Loop, One Stable Reference</h2>\n      <p>\n        Every gauge in the network is joined at the bottom by a liquid line and at the top by a separate air line, forming a system of communicating vessels: at rest, all liquid surfaces settle to one common level H₀. When monitoring point i settles, its sensor moves down relative to that shared surface and the liquid column above it grows — the cell reads ΔPᵢ&nbsp;=&nbsp;ρ·g·(H₀&nbsp;−&nbsp;z_sensor,i), so settlement is sᵢ&nbsp;=&nbsp;(ΔPᵢ&nbsp;−&nbsp;ΔPᵢ,₀)&nbsp;/&nbsp;(ρ·g). The glycol working fluid (≈1050&nbsp;kg/m³) carries a density temperature correction ρ(T)&nbsp;=&nbsp;ρ₀[1&nbsp;−&nbsp;β(T&nbsp;−&nbsp;T₀)], β&nbsp;≈&nbsp;4×10⁻⁴/°C.\n        \n      </p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 400\" role=\"img\" aria-label=\"Hydrostatic leveling network: three gauges on the structure and a reference cell on bedrock sharing one liquid loop\">\n        <!-- structure line -->\n        <line x1=\"50\" y1=\"120\" x2=\"200\" y2=\"120\" class=\"svg-stroke-soft\" stroke-width=\"4\"/>\n        <line x1=\"200\" y1=\"120\" x2=\"250\" y2=\"150\" class=\"svg-stroke-soft\" stroke-width=\"4\"/>\n        <line x1=\"250\" y1=\"150\" x2=\"320\" y2=\"150\" class=\"svg-stroke-soft\" stroke-width=\"4\"/>\n        <line x1=\"320\" y1=\"150\" x2=\"370\" y2=\"120\" class=\"svg-stroke-soft\" stroke-width=\"4\"/>\n        <line x1=\"370\" y1=\"120\" x2=\"500\" y2=\"120\" class=\"svg-stroke-soft\" stroke-width=\"4\"/>\n        <text x=\"100\" y=\"108\" font-size=\"12\" class=\"svg-text lang-en\">structure</text>\n        <text x=\"100\" y=\"108\" font-size=\"12\" class=\"svg-text lang-zh\">被测结构</text>\n        <!-- original line of settled segment (dashed) + Δh arrow -->\n        <line x1=\"250\" y1=\"120\" x2=\"320\" y2=\"120\" class=\"svg-stroke-soft\" stroke-width=\"1.4\" stroke-dasharray=\"5 4\"/>\n        <line x1=\"335\" y1=\"120\" x2=\"335\" y2=\"150\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <polyline points=\"330,141 335,150 340,141\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <text x=\"344\" y=\"140\" font-size=\"12.5\" class=\"svg-text-accent\">Δh</text>\n        <text x=\"380\" y=\"166\" font-size=\"11.5\" class=\"svg-text lang-en\">settled point</text>\n        <text x=\"380\" y=\"166\" font-size=\"11.5\" class=\"svg-text lang-zh\">发生沉降的测点</text>\n        <line x1=\"376\" y1=\"162\" x2=\"322\" y2=\"160\" class=\"svg-stroke-soft\" stroke-width=\"1\"/>\n\n        <!-- common liquid level H0 -->\n        <line x1=\"50\" y1=\"225\" x2=\"710\" y2=\"225\" class=\"svg-stroke\" stroke-width=\"1.4\" stroke-dasharray=\"7 5\"/>\n        <text x=\"56\" y=\"218\" font-size=\"12\" class=\"svg-text-accent\">H₀</text>\n        <text x=\"120\" y=\"218\" font-size=\"11.5\" class=\"svg-text lang-en\">common liquid level</text>\n        <text x=\"120\" y=\"218\" font-size=\"11.5\" class=\"svg-text lang-zh\">公共液面</text>\n\n        <!-- gauge 1 -->\n        <g>\n          <rect x=\"80\" y=\"120\" width=\"64\" height=\"140\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\" rx=\"6\"/>\n          <rect x=\"82\" y=\"225\" width=\"60\" height=\"33\" class=\"svg-fill-soft\"/>\n          <text x=\"112\" y=\"277\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">gauge 1</text>\n          <text x=\"112\" y=\"277\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">测点 1</text>\n        </g>\n        <!-- gauge 2 (settled, hangs 30 lower) -->\n        <g>\n          <rect x=\"253\" y=\"150\" width=\"64\" height=\"140\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\" rx=\"6\"/>\n          <rect x=\"255\" y=\"225\" width=\"60\" height=\"63\" class=\"svg-fill-soft\"/>\n          <text x=\"285\" y=\"307\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">gauge 2 — taller column</text>\n          <text x=\"285\" y=\"307\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">测点 2——液柱增高</text>\n        </g>\n        <!-- gauge 3 -->\n        <g>\n          <rect x=\"420\" y=\"120\" width=\"64\" height=\"140\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\" rx=\"6\"/>\n          <rect x=\"422\" y=\"225\" width=\"60\" height=\"33\" class=\"svg-fill-soft\"/>\n          <text x=\"452\" y=\"277\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">gauge 3</text>\n          <text x=\"452\" y=\"277\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">测点 3</text>\n        </g>\n        <!-- reference cell on bedrock -->\n        <g>\n          <rect x=\"600\" y=\"120\" width=\"64\" height=\"140\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2.6\" rx=\"6\"/>\n          <rect x=\"602\" y=\"225\" width=\"60\" height=\"33\" class=\"svg-fill-soft\"/>\n          <text x=\"632\" y=\"105\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-en\">reference cell</text>\n          <text x=\"632\" y=\"105\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-zh\">基准罐</text>\n          <!-- bedrock -->\n          <line x1=\"560\" y1=\"300\" x2=\"710\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"3\"/>\n          <line x1=\"572\" y1=\"312\" x2=\"586\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n          <line x1=\"598\" y1=\"312\" x2=\"612\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n          <line x1=\"624\" y1=\"312\" x2=\"638\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n          <line x1=\"650\" y1=\"312\" x2=\"664\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n          <line x1=\"676\" y1=\"312\" x2=\"690\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"1.4\"/>\n          <line x1=\"617\" y1=\"260\" x2=\"617\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"3\"/>\n          <line x1=\"647\" y1=\"260\" x2=\"647\" y2=\"300\" class=\"svg-stroke-soft\" stroke-width=\"3\"/>\n          <text x=\"635\" y=\"330\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-strong lang-en\">stable bedrock — must not move</text>\n          <text x=\"635\" y=\"330\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-strong lang-zh\">稳定基岩——长期不动点</text>\n        </g>\n\n        <!-- air line (top) -->\n        <path d=\"M 112 120 V 92 H 632 V 120\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <line x1=\"285\" y1=\"150\" x2=\"285\" y2=\"92\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <line x1=\"452\" y1=\"120\" x2=\"452\" y2=\"92\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <text x=\"372\" y=\"82\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">air line Φ8 mm PU — routed separately</text>\n        <text x=\"372\" y=\"82\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">通气管 Φ8mm PU——独立铺设</text>\n\n        <!-- liquid line (bottom) -->\n        <path d=\"M 112 260 V 350 H 632 V 260\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <line x1=\"285\" y1=\"290\" x2=\"285\" y2=\"350\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <line x1=\"452\" y1=\"260\" x2=\"452\" y2=\"350\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <text x=\"372\" y=\"370\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">liquid line Φ10 mm PU — connects every cell</text>\n        <text x=\"372\" y=\"370\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">通液管 Φ10mm PU——串联所有储液罐</text>\n\n        <!-- formula -->\n        <text x=\"372\" y=\"395\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-accent\">ΔP = ρ·g·Δh　→　s = (ΔP − ΔP₀) / (ρ·g)</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        Settlement of any point appears as a taller liquid column relative to the shared surface H₀ — which is why the reference cell sits on bedrock that must not move, and why liquid and air lines are routed separately. Until the reference is verified by periodic leveling surveys, every \"settlement value\" is relative, not absolute.\n        \n      </div>\n    </div>\n    <div class=\"grid grid-2\" style=\"margin-top:32px;\">\n      <div class=\"card reveal\">\n        <h3>Everything is relative to the reference</h3>\n        <p>Hydrostatic leveling outputs settlement relative to the reference cell. If the reference itself moves, the whole network drifts with it — so the reference goes on long-term stable bedrock and its own stability is re-verified by periodic leveling surveys. When all points drift in the same direction at once, suspect the reference first.</p>\n      </div>\n      <div class=\"card reveal\">\n        <h3>The magnetostrictive variant: absolute position</h3>\n        <p>SCST02 reads its float magnet by time-of-flight on a magnetostrictive alloy waveguide (FeNi, TbDyFe): a microsecond current pulse meets the magnet ring's axial field, and the Wiedemann effect launches a torsional strain wave traveling at ≈2850&nbsp;m/s toward a detection coil (inverse Wiedemann / Villari effect). Position is x&nbsp;=&nbsp;v·Δt — 100&nbsp;ps timing resolves 0.3&nbsp;µm, drift stays under 5&nbsp;ppm/°C, and because position is absolute, the reading is retained through power loss.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HYDROSTATIC LEVEL GAUGE COMPARISON ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Hydrostatic level gauges</div>\n      <h2>Three Principles, One Family</h2>\n      <p>Differential-pressure for best value, magnetostrictive for extra-large range, ultrasonic for the most demanding accuracy — together they cover the full spectrum of settlement projects.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">Differential-Pressure (SCST01)</th>\n            <th scope=\"col\">Magnetostrictive (SCST02)</th>\n            <th scope=\"col\">Ultrasonic</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Principle</td><td>Connected-vessel differential pressure</td><td>Magnetostrictive time-of-flight, absolute position</td><td>Non-contact ultrasonic</td></tr>\n          <tr><td>Range</td><td>0–200 mm</td><td class=\"hl\">0–2000 mm</td><td>approx. 100 mm</td></tr>\n          <tr><td>Resolution / accuracy</td><td class=\"hl\">0.01 mm resolution</td><td>0.01 mm accuracy</td><td class=\"hl\">Ultra-high accuracy</td></tr>\n          <tr><td>Output</td><td>RS485</td><td>RS485</td><td>RS485</td></tr>\n          <tr><td>Key strength</td><td class=\"hl\">Best value for money</td><td class=\"hl\">Extra-large range; reading retained on power loss</td><td>No contact with the liquid surface</td></tr>\n          <tr><td>Best for</td><td>Foundation-pit settlement</td><td>Large-area precision settlement: metro operation, building clusters</td><td>Precision engineering settlement</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px;\">\n      <h2 style=\"font-size:24px;\">Engineered So the Data Can Be Trusted</h2>\n      <p>Most hydrostatic-leveling failures happen at installation, not in the sensor. Our delivery process enforces the details that keep a network honest for years.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg></div><h3>Independent liquid &amp; air lines</h3><p>Liquid and air tubes are always routed separately — sharing one conduit causes siphoning and silently invalidates the whole network. We never compromise on this.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L4 7v10l8 5 8-5V7z\"/><path d=\"M12 22V12\"/><path d=\"M4 7l8 5 8-5\"/></svg></div><h3>Reference cell on stable ground</h3><p>Every settlement value is relative to the reference cell, so it is installed on long-term stable bedrock and periodically re-verified by leveling surveys.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 4v6.5a4 4 0 0 1-1 2.6L8.6 18a2 2 0 0 0 1.5 3.3h3.8a2 2 0 0 0 1.5-3.3L11 13.1a4 4 0 0 1-1-2.6V4\"/><line x1=\"7\" y1=\"4\" x2=\"17\" y2=\"4\"/></svg></div><h3>Temperature-corrected fluid</h3><p>Readings carry a fluid-density temperature correction, and antifreeze concentration is re-checked on a 1–2 year cycle for cold-climate reliability.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== LAYERED SETTLEMENT ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Layered settlement gauge · RLS</div>\n      <h2>See How Each Soil Layer Consolidates</h2>\n      <p>Surface settlement tells you how much; layered settlement tells you where. Magnet rings embedded at target depths track each stratum independently — essential for subgrade filling, surcharge preloading and construction above shield tunnels.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Magnet rings anchored to the soil</b><p>Each ring is set at a target depth with opening claws that grip the surrounding stratum — so it moves with the soil, not with the access tube.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Manual probe reading</b><p>A reed-switch probe lowered down the access tube locates each ring to ±1 mm — a simple, economical routine for short-term construction monitoring.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Vibrating-wire automation</b><p>A vibrating-wire option upgrades resolution to 0.05 mm and removes site visits entirely — built for long-term, remote operation.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Layer-by-layer consolidation curves</b><p>Depth-resolved settlement time series show exactly which stratum is still consolidating — the evidence engineers need to release the next construction stage.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"reveal\">\n        <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap\">\n          <table class=\"spec-table\">\n            <thead>\n              <tr>\n                <th scope=\"col\">Dimension</th>\n                <th scope=\"col\">Magnet-Ring Manual</th>\n                <th scope=\"col\">Vibrating-Wire Automated</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr><td>Accuracy</td><td>±1 mm</td><td class=\"hl\">±0.05 mm</td></tr>\n              <tr><td>Site visits</td><td>Weekly readings</td><td class=\"hl\">None — fully remote</td></tr>\n              <tr><td>Installation effort</td><td>Low</td><td>Moderate</td></tr>\n              <tr><td>Best for</td><td>Short-term construction</td><td>Long-term operation</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p style=\"color:var(--text-2); font-size:14.8px; margin-top:18px;\">\n          Typical deployments: expressway subgrade, airport runways, surcharge-preloading programs and ground above shield-tunneling drives.\n          \n        </p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SELECTION GUIDE ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Selection guide</div>\n      <h2>Settlement &amp; Tilt: Pick the Right Product in One Glance</h2>\n      <p>Settlement and tilt are usually monitored together on the same structure. This matrix covers both — tiltmeter details are on the <a href=\"/products/settlement-tilt-monitoring/tiltmeter-series\" style=\"color:var(--accent);\">Tiltmeter Series page</a>.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 3\" data-aria-en=\"Scrollable technical table 3\" data-aria-zh=\"可横向滚动的技术参数表 3\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Application Scenario</th>\n            <th scope=\"col\">Recommended Product</th>\n            <th scope=\"col\">Why</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Foundation-pit settlement</td><td class=\"hl\">Differential-Pressure Level Gauge (SCST01)</td><td>Best value for money</td></tr>\n          <tr><td>Large-area precision settlement</td><td class=\"hl\">Magnetostrictive Level Gauge (SCST02)</td><td>Extra-large 0–2000 mm range</td></tr>\n          <tr><td>Precision engineering settlement</td><td class=\"hl\">Ultrasonic Level Gauge</td><td>Ultra-high accuracy, non-contact</td></tr>\n          <tr><td>Layered subgrade consolidation</td><td class=\"hl\">Layered Settlement Gauge (RLS)</td><td>Depth-resolved, layer-by-layer settlement</td></tr>\n          <tr><td>Dilapidated building / tower tilt</td><td><a href=\"/products/settlement-tilt-monitoring/tiltmeter-series\" style=\"color:var(--accent); font-weight:600;\">Wireless Tiltmeter (LoRa)</a></td><td>Cable-free deployment, long battery life</td></tr>\n          <tr><td>High-support formwork / tunnel</td><td><a href=\"/products/settlement-tilt-monitoring/tiltmeter-series\" style=\"color:var(--accent); font-weight:600;\">Wired Tiltmeter (RS485)</a></td><td>Higher accuracy, continuous acquisition</td></tr>\n          <tr><td>Bridge tilt monitoring</td><td><a href=\"/products/settlement-tilt-monitoring/tiltmeter-series\" style=\"color:var(--accent); font-weight:600;\">Wireless Tiltmeter (NB-IoT)</a></td><td>More reliable remote transmission</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== INSTALLATION ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation</div>\n      <h2>The Install Gates That Keep a Network Honest</h2>\n      <p>None of these checks can be done at the factory — each one is confirmed on site, item by item, before the system goes live.</p>\n    </div>\n    <div class=\"split\" style=\"align-items:start;\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Keep every cell within range of the loop</b><p>Mount the reservoirs so height differences stay inside the sensor's range — beyond it, the differential-pressure output saturates.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Route liquid and air lines separately</b><p>Never share one PU conduit. A shared line creates a siphon: air squeezes the liquid column into interrupted flow and the whole network fails at once. This rule has no exceptions.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Put the reference cell on stable bedrock</b><p>All values are relative to the reference — install it on long-term stable bedrock and re-verify its stability with periodic leveling surveys.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Fill to level and purge air</b><p>Inject working fluid until every reservoir level is in place. A cell with trapped air bubbles reads erratically — re-bleed until the reading stabilizes.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Set the antifreeze verification cycle</b><p>Check or replenish antifreeze concentration every 1–2 years — concentration drifts with evaporation and refills, and an under-strength fluid freezes in cold climates. Check before winter, not after the first freeze.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"reveal\" style=\"display:grid; gap:22px;\">\n        <div class=\"card\">\n          <h3>Magnetostrictive cells: three boundaries</h3>\n          <p>The magnet ring slides over the waveguide but must never touch it — contact damages the alloy waveguide and scraps the unit. Keep clear of welders, variable-frequency drives and heavy-current cables, and flag-and-exclude data logged during welding work. A single waveguide runs to 7.5&nbsp;m at most; beyond that, switch to a segmented scheme. All three are confirmed at selection stage — discovering them on site usually means changing the model.</p>\n        </div>\n        <div class=\"card\">\n          <h3>Layered settlement (RLS): set right before grouting</h3>\n          <p>Pre-embed the access tube in the borehole at its design position. Slide each magnet ring over the outside of the tube with its claws opened to grip the surrounding stratum — an unanchored ring follows the casing, not the soil, and every \"settlement\" it reports is false. Record each ring's as-built depth against its stratum number before sealing the hole — a depth mismatch is the most fatal error in later data interpretation. On the vibrating-wire version, equalize the external spring pre-tension across points, or initial values carry a systematic offset into the whole history.</p>\n        </div>\n      </div>\n    </div>\n    <div class=\"gallery\" style=\"margin-top:42px;\">\n      <figure class=\"reveal\"><img src=\"/images/products/hydrostatic-level-gauge/dam-settlement-monitoring.jpg\" alt=\"Gravity dam — hydropower settlement monitoring scenario\" loading=\"lazy\" width=\"1000\" height=\"667\" decoding=\"async\"><figcaption>Dam &amp; hydropower scenario — settlement networks alongside IPI and piezometers</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/home/monitoring-consultation-cta.jpg\" alt=\"Metro station platform — operation-period settlement monitoring scenario\" loading=\"lazy\" width=\"714\" height=\"476\" decoding=\"async\"><figcaption>Metro operation-period scenario — large-area precision settlement</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/hydrostatic-level-gauge/foundation-pit-settlement-monitoring.jpg\" alt=\"High-rise construction site — foundation pit settlement monitoring scenario\" loading=\"lazy\" width=\"1000\" height=\"609\" decoding=\"async\"><figcaption>Foundation-pit &amp; building-cluster settlement scenario</figcaption></figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Field Questions, Straight Answers</h2>\n      <p>Compiled from our after-sales records and the fault tables in the field manuals.</p>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>All points are drifting in the same direction — is the whole site settling?</summary>\n        <div class=\"faq-body\">More likely the reference cell itself is settling. Every value in the network is relative to it, so a moving reference drags all readings the same way. Re-verify the reference with a leveling survey and, if confirmed, re-select a stable reference location.</div>\n      </details>\n      <details>\n        <summary>One point's reading keeps jumping around.</summary>\n        <div class=\"faq-body\">Air bubbles trapped in that cell. Re-bleed the cell until the reading stabilizes.</div>\n      </details>\n      <details>\n        <summary>Readings respond sluggishly to known movement.</summary>\n        <div class=\"faq-body\">A blocked or over-bent liquid line. Clear the tube and ease the bend radius along the run. If a 4–20&nbsp;mA channel reads exactly zero, check for reversed polarity or a broken wire with a multimeter.</div>\n      </details>\n      <details>\n        <summary>What maintenance does the liquid loop need — especially in cold climates?</summary>\n        <div class=\"faq-body\">Verify or replenish antifreeze concentration on a 1–2 year cycle: concentration drifts with evaporation and refills, and an under-strength fluid freezes in winter. In cold regions, check before each winter rather than reacting to a freeze. Readings also carry the working fluid's density temperature correction.</div>\n      </details>\n      <details>\n        <summary>Our magnetostrictive gauge jitters or spikes — is it broken?</summary>\n        <div class=\"faq-body\">Check the site log before suspecting the sensor. Sustained jitter points to strong electromagnetic interference — add shielding and re-route cabling away from welders and VFDs. A single spike usually coincides with welding or VFD transients: flag and exclude that period. No change at all suggests the magnet ring has detached; an outright invalid output means the waveguide is damaged and the unit is replaced as a whole.</div>\n      </details>\n      <details>\n        <summary>A layered-settlement magnet ring suddenly shows a centimeter-level shift.</summary>\n        <div class=\"faq-body\">Don't alarm on a single reading. After rain, moisture in the probe can false-trigger the reed switch and mimic a sudden sink — dry the probe and re-measure. If an entire hole never moves, the casing is settling or the rings never gripped the soil: re-install. If a single ring reads in reverse, re-check the tape-cable depth markings. Re-measure first, check records second, conclude last.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "tiltmeter-series": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Tiltmeter Series</span>\n    </div>\n    <h1>Tiltmeter Series</h1>\n    <p class=\"sub\">\n      Surface-tilt monitoring for buildings, bridges, towers, tunnels and heritage structures. Wireless LoRa / NB-IoT variants run 2–5 years on battery; wired RS485 variants deliver 0.0005° resolution with uninterrupted acquisition.\n      \n    </p>\n    <div class=\"model\">SCST-T01 · MEMS + ELECTROLYTIC</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/tiltmeter-series/tiltmeter-product.jpg\" alt=\"SCST-T01 dual-axis wireless tiltmeter with LoRa / NB-IoT antenna\" width=\"599\" height=\"538\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          One series, every tilt-monitoring scenario\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          The SCST-T01 tiltmeter series measures dual-axis surface tilt relative to the horizontal plane. Two sensing technologies and two communication architectures combine into a family that fits everything from a remote, unpowered tower to a continuously powered tunnel — and pairs naturally with our <a href=\"/products/settlement-tilt-monitoring/hydrostatic-level-gauge\" style=\"color:var(--accent);\">hydrostatic settlement gauges</a>. When vibration events and temperature need to be captured with tilt, use the <a href=\"/products/settlement-tilt-monitoring/wireless-tilt-vibration\" style=\"color:var(--accent);\">SCST-WV02 wireless tilt + vibration sensor</a>.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>MEMS &amp; electrolytic dual sensor options</b><p>MEMS for wide ±90° range and shock resistance; electrolytic for decade-scale long-term stability.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Wireless &amp; wired variants</b><p>LoRa / NB-IoT wireless with 2–5 year battery life, or RS485 wired for continuous high-accuracy acquisition.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Built for buildings, heritage &amp; formwork</b><p>From dilapidated-building alarms to high-support formwork safety and heritage preservation programs.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.0005°</div><div class=\"name\">Resolution (wired)</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">±90°</div><div class=\"name\">Measurement Range</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">2–5 yr</div><div class=\"name\">Battery Life (wireless)</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">IP68</div><div class=\"name\">All-Weather Outdoor</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>A Bubble in Liquid vs a Mass on Springs</h2>\n      <p>\n        An electrolytic tiltmeter seals a conductive electrolyte and an air bubble inside a vial with three platinum electrodes — one common, two differential. As the housing tilts, the bubble shifts and the length of liquid between the two outer electrodes changes, unbalancing their impedances R₁ / R₂. AC excitation prevents polarization, and a Wheatstone bridge turns the differential conductance directly into sin&nbsp;θ. A MEMS tiltmeter instead suspends a silicon proof mass on micro-springs: gravity displaces it by x&nbsp;=&nbsp;m·g·sin&nbsp;θ&nbsp;/&nbsp;k, and differential comb capacitors read the displacement as θ&nbsp;=&nbsp;arcsin(aₓ&nbsp;/&nbsp;g).\n        \n      </p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 380\" role=\"img\" aria-label=\"Electrolytic vial and MEMS capacitive proof-mass sensing principles\">\n        <!-- divider -->\n        <line x1=\"380\" y1=\"22\" x2=\"380\" y2=\"358\" class=\"svg-stroke-soft\" stroke-width=\"1\" stroke-dasharray=\"4 5\"/>\n\n        <!-- ===== LEFT: ELECTROLYTIC ===== -->\n        <text x=\"190\" y=\"30\" text-anchor=\"middle\" font-size=\"14.5\" class=\"svg-text-strong lang-en\">Electrolytic — differential conductance</text>\n        <text x=\"190\" y=\"30\" text-anchor=\"middle\" font-size=\"14.5\" class=\"svg-text-strong lang-zh\">电解液式——差分电导测角</text>\n\n        <defs>\n          <clipPath id=\"tilt-vial-clip\">\n            <rect x=\"65\" y=\"158\" width=\"250\" height=\"74\" rx=\"37\" transform=\"rotate(-9 190 195)\"/>\n          </clipPath>\n        </defs>\n        <!-- liquid below horizontal surface, clipped to tilted vial -->\n        <rect x=\"30\" y=\"196\" width=\"320\" height=\"120\" class=\"svg-fill-soft\" clip-path=\"url(#tilt-vial-clip)\"/>\n        <!-- horizontal liquid surface -->\n        <line x1=\"40\" y1=\"196\" x2=\"340\" y2=\"196\" class=\"svg-stroke\" stroke-width=\"1.6\" clip-path=\"url(#tilt-vial-clip)\"/>\n        <!-- vial outline (tilted) -->\n        <rect x=\"65\" y=\"158\" width=\"250\" height=\"74\" rx=\"37\" transform=\"rotate(-9 190 195)\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <!-- vial axis (tilted, dashed) -->\n        <line x1=\"85\" y1=\"195\" x2=\"295\" y2=\"195\" transform=\"rotate(-9 190 195)\" class=\"svg-stroke-soft\" stroke-width=\"1.2\" stroke-dasharray=\"5 5\"/>\n        <!-- electrodes (tilted with housing) -->\n        <g transform=\"rotate(-9 190 195)\">\n          <line x1=\"120\" y1=\"130\" x2=\"120\" y2=\"214\" class=\"svg-stroke\" stroke-width=\"2.4\"/>\n          <line x1=\"190\" y1=\"130\" x2=\"190\" y2=\"218\" class=\"svg-stroke-soft\" stroke-width=\"2.4\"/>\n          <line x1=\"260\" y1=\"130\" x2=\"260\" y2=\"214\" class=\"svg-stroke\" stroke-width=\"2.4\"/>\n        </g>\n        <text x=\"96\" y=\"136\" font-size=\"12.5\" class=\"svg-text-accent\">R₁</text>\n        <text x=\"258\" y=\"112\" font-size=\"12.5\" class=\"svg-text-accent\">R₂</text>\n        <text x=\"160\" y=\"118\" font-size=\"11\" class=\"svg-text lang-en\">common</text>\n        <text x=\"160\" y=\"118\" font-size=\"11\" class=\"svg-text lang-zh\">公共电极</text>\n        <!-- bubble label -->\n        <text x=\"322\" y=\"148\" text-anchor=\"end\" font-size=\"11.5\" class=\"svg-text lang-en\">air bubble</text>\n        <text x=\"322\" y=\"148\" text-anchor=\"end\" font-size=\"11.5\" class=\"svg-text lang-zh\">气泡</text>\n        <line x1=\"300\" y1=\"153\" x2=\"284\" y2=\"170\" class=\"svg-stroke-soft\" stroke-width=\"1\"/>\n        <!-- electrolyte label -->\n        <text x=\"62\" y=\"248\" font-size=\"11.5\" class=\"svg-text lang-en\">electrolyte</text>\n        <text x=\"62\" y=\"248\" font-size=\"11.5\" class=\"svg-text lang-zh\">电解质溶液</text>\n        <line x1=\"105\" y1=\"237\" x2=\"128\" y2=\"220\" class=\"svg-stroke-soft\" stroke-width=\"1\"/>\n        <!-- theta -->\n        <text x=\"312\" y=\"186\" font-size=\"13\" class=\"svg-text-accent\">θ</text>\n        <!-- formula + stability -->\n        <text x=\"190\" y=\"298\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-accent\">V_out ∝ (R₁ − R₂)/(R₁ + R₂) ∝ sin θ</text>\n        <text x=\"190\" y=\"327\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Long-term zero stability 1×10⁻⁸ rad</text>\n        <text x=\"190\" y=\"327\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">长期零漂稳定性 1×10⁻⁸ rad</text>\n        <text x=\"190\" y=\"349\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">±3° range · &lt;5 Hz bandwidth · mandatory temp. compensation</text>\n        <text x=\"190\" y=\"349\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">±3° 量程 · &lt;5 Hz 带宽 · 强制温度补偿</text>\n\n        <!-- ===== RIGHT: MEMS ===== -->\n        <text x=\"570\" y=\"30\" text-anchor=\"middle\" font-size=\"14.5\" class=\"svg-text-strong lang-en\">MEMS — capacitive proof mass</text>\n        <text x=\"570\" y=\"30\" text-anchor=\"middle\" font-size=\"14.5\" class=\"svg-text-strong lang-zh\">MEMS——电容式检验质量</text>\n\n        <!-- frame -->\n        <rect x=\"440\" y=\"78\" width=\"260\" height=\"172\" rx=\"8\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <!-- fixed plates -->\n        <line x1=\"505\" y1=\"116\" x2=\"505\" y2=\"214\" class=\"svg-stroke-soft\" stroke-width=\"5\"/>\n        <line x1=\"635\" y1=\"116\" x2=\"635\" y2=\"214\" class=\"svg-stroke-soft\" stroke-width=\"5\"/>\n        <text x=\"505\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-en\">fixed plate</text>\n        <text x=\"505\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-zh\">固定极板</text>\n        <text x=\"635\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-en\">fixed plate</text>\n        <text x=\"635\" y=\"232\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-zh\">固定极板</text>\n        <!-- springs (top & bottom) -->\n        <polyline points=\"560,78 560,90 552,96 568,104 552,112 568,120 560,126 560,130\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <polyline points=\"560,200 560,206 552,212 568,220 552,228 568,236 560,242 560,250\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <text x=\"578\" y=\"100\" font-size=\"11\" class=\"svg-text lang-en\">spring k</text>\n        <text x=\"578\" y=\"100\" font-size=\"11\" class=\"svg-text lang-zh\">硅弹簧 k</text>\n        <!-- proof mass (displaced toward left plate) -->\n        <rect x=\"525\" y=\"130\" width=\"70\" height=\"70\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.8\"/>\n        <text x=\"560\" y=\"161\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text-strong lang-en\">proof</text>\n        <text x=\"560\" y=\"175\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text-strong lang-en\">mass</text>\n        <text x=\"560\" y=\"169\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-strong lang-zh\">检验质量</text>\n        <!-- gaps -->\n        <line x1=\"507\" y1=\"188\" x2=\"523\" y2=\"188\" class=\"svg-stroke\" stroke-width=\"1\"/>\n        <line x1=\"597\" y1=\"188\" x2=\"633\" y2=\"188\" class=\"svg-stroke\" stroke-width=\"1\"/>\n        <text x=\"515\" y=\"182\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-accent\">d₁</text>\n        <text x=\"615\" y=\"182\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-accent\">d₂</text>\n        <!-- gravity component arrow -->\n        <line x1=\"610\" y1=\"268\" x2=\"534\" y2=\"268\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <polyline points=\"544,263 534,268 544,273\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"1.6\"/>\n        <text x=\"618\" y=\"272\" font-size=\"11.5\" class=\"svg-text-accent\">m·g·sin θ</text>\n        <!-- formula + stability -->\n        <text x=\"570\" y=\"298\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-accent\">ΔC → θ = arcsin(aₓ / g)</text>\n        <text x=\"570\" y=\"327\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Long-term zero stability 1×10⁻⁵ rad</text>\n        <text x=\"570\" y=\"327\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">长期零漂稳定性 1×10⁻⁵ rad</text>\n        <text x=\"570\" y=\"349\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">±90° range · &gt;1 kHz bandwidth · 10,000 g shock survival</text>\n        <text x=\"570\" y=\"349\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">±90° 量程 · &gt;1 kHz 带宽 · 抗冲击 10000 g</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        Why electrolytic holds zero for decades: its output depends only on liquid conduction between electrodes, limited by electrolyte thermal noise — with temperature compensation, zero drift reaches the ±0.1&nbsp;µrad (≈0.02″) class. A MEMS zero point rests on mechanical packaging stress and charge redistribution, which relax over the years toward 1×10⁻⁵&nbsp;rad (≈2″).\n        \n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>Wireless or Wired — Choose by Site Conditions</h2>\n      <p>Pick wireless for flexible, cable-free deployment and years of battery life; pick wired for the highest accuracy and uninterrupted continuous acquisition.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">Wireless Tiltmeter (SCST-T01 / SCST-WV02)</th>\n            <th scope=\"col\">Wired Tiltmeter (SCST-T01-RS485)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Communication</td><td class=\"hl\">LoRa / NB-IoT wireless</td><td>RS485 wired bus</td></tr>\n          <tr><td>Accuracy</td><td>0.005°</td><td class=\"hl\">0.003°</td></tr>\n          <tr><td>Resolution</td><td>0.001°</td><td class=\"hl\">0.0005°</td></tr>\n          <tr><td>Range</td><td>±90°</td><td>±90°</td></tr>\n          <tr><td>Power</td><td class=\"hl\">Battery, 2–5 year life</td><td>External, continuous operation</td></tr>\n          <tr><td>Protection</td><td class=\"hl\">IP68, all-weather outdoor</td><td>IP65</td></tr>\n          <tr><td>Operating temperature</td><td>-20 ~ 70 ℃</td><td>-20 ~ 70 ℃</td></tr>\n          <tr><td>Best for</td><td>Remote, unpowered sites: dilapidated buildings, towers, bridges</td><td>Powered sites: high-support formwork, tunnels</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SENSOR TECHNOLOGY ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Sensing technology</div>\n      <h2>MEMS and Electrolytic: Two Physics, One Honest Recommendation</h2>\n      <p>These are not a high/low configuration of the same product — they are two different physical principles. We recommend by monitoring period and site vibration, not by price.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 2\" data-aria-en=\"Scrollable technical table 2\" data-aria-zh=\"可横向滚动的技术参数表 2\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Dimension</th>\n            <th scope=\"col\">Electrolytic Sensor</th>\n            <th scope=\"col\">MEMS Sensor</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Long-term zero stability</td><td class=\"hl\">1×10⁻⁸ rad</td><td>1×10⁻⁵ rad</td></tr>\n          <tr><td>Range</td><td>±3° (typical)</td><td class=\"hl\">±90°</td></tr>\n          <tr><td>Bandwidth</td><td>&lt; 5 Hz</td><td class=\"hl\">&gt; 1 kHz</td></tr>\n          <tr><td>Shock / vibration tolerance</td><td>Moderate</td><td class=\"hl\">Extremely strong</td></tr>\n          <tr><td>Recommended when</td><td>Monitoring period ≥ 5 years: heritage buildings, dams, long-term programs</td><td>Vibration / shock environments, wide-range outdoor deployment</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"grid grid-3\" style=\"margin-top:42px;\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22V8\"/><path d=\"M5 12V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v7\"/><path d=\"M3 22h18\"/></svg></div><h3>Rigid mounting matters</h3><p>The base must be rigidly bonded to the structure itself — never to render, tiles or uncured concrete. Our installation guide eliminates \"the sensor shaking itself\" false signals.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 4v6.5a4 4 0 0 1-1 2.6L8.6 18a2 2 0 0 0 1.5 3.3h3.8a2 2 0 0 0 1.5-3.3L11 13.1a4 4 0 0 1-1-2.6V4\"/><line x1=\"7\" y1=\"4\" x2=\"17\" y2=\"4\"/></svg></div><h3>Temperature compensation built in</h3><p>Electrolytic sensors are temperature-sensitive; without compensation, day-night cycles masquerade as displacement. Compensation is mandatory, not optional, in our designs.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg></div><h3>Choose by decades, not by quarter</h3><p>For a 30-year heritage program, MEMS will drift; electrolytic will not. We state the physical boundary up front so the right choice is obvious before installation — not five years after.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== INSTALLATION ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation</div>\n      <h2>Accuracy Is Decided at the Mounting Surface</h2>\n      <p>A loosely coupled base makes the most expensive sensor worthless. These are the steps our field manual enforces on every installation.</p>\n    </div>\n    <div class=\"reveal\" style=\"max-width:860px;\">\n      <ul class=\"feature-list\">\n        <li><span class=\"fi\">1</span><div><b>Fix the base rigidly to the structure itself</b><p>The mounting base must connect rigidly to the load-bearing structure being measured — base rigidity matters even more than sensor accuracy.</p></div></li>\n        <li><span class=\"fi\">2</span><div><b>Reject weak surface media</b><p>Never install on surface render or paint, on tiles, or on uncured concrete. A base on these media produces \"the sensor shaking itself\" false signals — the most common field mistake.</p></div></li>\n        <li><span class=\"fi\">3</span><div><b>Align the measurement axes</b><p>The instrument measures dual-axis (A / B) tilt relative to the horizontal plane — align the axes with the directions the structure needs monitored.</p></div></li>\n        <li><span class=\"fi\">4</span><div><b>Shade from sun, enable temperature compensation</b><p>Sun-exposed installs show day-night cyclic swings. Fit a sun shade where needed; on electrolytic units, temperature compensation is mandatory, not optional.</p></div></li>\n        <li><span class=\"fi\">5</span><div><b>Wire, verify and baseline</b><p>Wired units take DC 7–12&nbsp;V with RS-485 / 4–20&nbsp;mA output — verify polarity with a multimeter (a reversed line reads zero). Record initial values, then sync tilt and temperature time series to the cloud with threshold alarms.</p></div></li>\n      </ul>\n    </div>\n    <div class=\"gallery\" style=\"margin-top:42px;\">\n      <figure class=\"reveal\"><img src=\"/images/products/tiltmeter-series/tiltmeter-unit.jpg\" alt=\"Tiltmeter unit with all-weather housing on a flange mounting base\" loading=\"lazy\" width=\"536\" height=\"488\" decoding=\"async\"><figcaption>Tiltmeter unit — all-weather housing, flange mounting base</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/about/bridge-monitoring-hero.jpg\" alt=\"Suspension bridge — pylon and deck tilt monitoring scenario\" loading=\"lazy\" width=\"774\" height=\"436\" decoding=\"async\"><figcaption>Bridge scenario — pylon and deck tilt monitoring</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"/images/products/tiltmeter-series/building-tilt-monitoring.jpg\" alt=\"High-rise construction site — building tilt monitoring scenario\" loading=\"lazy\" width=\"711\" height=\"475\" decoding=\"async\"><figcaption>Construction scenario — building tilt monitoring</figcaption></figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== APPLICATION SCENARIOS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Applications</div>\n      <h2>Where the Tiltmeter Series Works</h2>\n      <p>Tilt rarely tells the whole story alone — on most structures it is paired with settlement monitoring. See the combined <a href=\"/products/settlement-tilt-monitoring/hydrostatic-level-gauge\" style=\"color:var(--accent);\">selection guide</a> on our settlement page.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><span class=\"tag\">Wireless · LoRa</span><h3 style=\"margin-top:12px;\">Dilapidated Buildings</h3><p>Cable-free installation and multi-year battery life make city-wide aging-building alarm networks practical and affordable.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Wireless · LoRa</span><h3 style=\"margin-top:12px;\">Tower Tilt</h3><p>Transmission and telecom towers at remote, unpowered sites — IP68 housings survive all-weather outdoor exposure for years.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Wireless · NB-IoT</span><h3 style=\"margin-top:12px;\">Bridge Tilt</h3><p>NB-IoT cellular transmission gives more reliable long-distance reporting for piers, pylons and approach structures.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Wired · RS485</span><h3 style=\"margin-top:12px;\">High-Support Formwork</h3><p>During concrete pours, 0.003° accuracy and uninterrupted acquisition catch dangerous formwork movement in real time.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Wired · RS485</span><h3 style=\"margin-top:12px;\">Tunnels</h3><p>Stable site power supports continuous lining-tilt acquisition over the full construction and operation period.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Electrolytic</span><h3 style=\"margin-top:12px;\">Heritage Structures</h3><p>Decade-scale preservation programs for historic towers and timber structures demand 1×10⁻⁸ rad-class long-term stability.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Field Questions, Straight Answers</h2>\n      <p>Compiled from our after-sales records and the fault table in the field manual.</p>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>Why does the tilt reading cycle with day and night?</summary>\n        <div class=\"faq-body\">An electrolytic sensor without temperature compensation — or any unit installed in direct sunlight — shows day-night periodic swings that are easily misread as real displacement. Enable temperature compensation and fit a sun shade.</div>\n      </details>\n      <details>\n        <summary>What causes short-lived spikes in the data?</summary>\n        <div class=\"faq-body\">Shock or vibration reaching a MEMS unit. Check for vibration sources near the mounting point; if the disturbance persists on a long-term monitoring point, consider switching that point to an electrolytic unit.</div>\n      </details>\n      <details>\n        <summary>How do we handle slow drift over months and years?</summary>\n        <div class=\"faq-body\">Slow long-term drift is characteristic of MEMS aging. For projects of five years or longer, MEMS units should be sent to a metrology institute for periodic recalibration; electrolytic units do not need this round trip.</div>\n      </details>\n      <details>\n        <summary>How are the units powered — and what if a reading goes to zero?</summary>\n        <div class=\"faq-body\">Wireless LoRa / NB-IoT variants run 2–5 years on battery. Wired variants take an external DC 7–12&nbsp;V supply for uninterrupted acquisition. If a wired unit reads zero, check for a broken wire or reversed polarity with a multimeter before suspecting the sensor.</div>\n      </details>\n      <details>\n        <summary>Electrolytic or MEMS — how do we choose?</summary>\n        <div class=\"faq-body\">Two questions decide it: how many years will the point be monitored, and is there strong vibration on site? A monitoring period of 5 years or more favors electrolytic (1×10⁻⁸&nbsp;rad long-term stability); vibration / shock environments or the wide ±90° range favor MEMS. They are complementary physics — not a high/low configuration of one product.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "wireless-tilt-vibration": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Wireless Tilt + Vibration</span>\n    </div>\n    <h1>Wireless Tilt, Temperature &amp; Vibration Sensor</h1>\n    <p class=\"sub\">\n      A fully sealed, battery-powered edge sensor that measures three-axis tilt, acceleration, vibration frequency, vibration amplitude and temperature, then uploads event-aware data over NB-IoT or 4G — built for structures where a simple tiltmeter is not enough.\n      \n    </p>\n    <div class=\"model\">SCST-WV02 · TILT + TEMPERATURE + VIBRATION · NB-IOT / 4G</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/wireless-tilt-vibration/wireless-tilt-vibration-sensor.jpg\" alt=\"SCST-WV02 wireless tilt temperature and vibration sensor with sealed dome housing\" width=\"795\" height=\"645\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Tilt trend, vibration event and temperature context in one timestamp\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          SCST-WV02 combines a three-axis MEMS accelerometer, magnetometer, cellular communication, battery power and a sealed polyurethane housing. It reports routine long-term tilt changes, but can also wake on tilt or vibration events and capture high-frequency waveform features for structural health assessment.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Five measurement elements</b><p>Tilt, acceleration, vibration frequency, vibration amplitude and ambient temperature are acquired by one device.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Scheduled + triggered reporting</b><p>Routine low-power monitoring is paired with event-triggered high-frequency sampling when tilt or vibration changes.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>No field wiring</b><p>NB-IoT / 4G communication and battery operation fit bridges, towers, slopes and outdoor structures where cabling is expensive or fragile.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>IP68 sealed dome housing</b><p>High-strength aging-resistant polyurethane housing with a bolt-down base for harsh outdoor natural environments.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">±90°</div><div class=\"name\">Tilt Range</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">0.005°</div><div class=\"name\">Accuracy within ±15°</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">200 Hz</div><div class=\"name\">Vibration Bandwidth</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">IP68</div><div class=\"name\">Outdoor Protection</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>A Low-Power Watch Mode with High-Frequency Event Capture</h2>\n      <p>\n        The sensor normally stays in a reduced-rate watch mode. When scheduled acquisition is due, or when tilt or vibration is detected, it switches to working mode, samples at high frequency and extracts vibration-domain features using FFT.\n        \n      </p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 360\" role=\"img\" aria-label=\"SCST-WV02 sensing and reporting workflow\">\n        <text x=\"126\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">01 · Sense</text>\n        <text x=\"126\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">01 · 感知</text>\n        <text x=\"316\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">02 · Trigger</text>\n        <text x=\"316\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">02 · 触发</text>\n        <text x=\"506\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">03 · Analyze</text>\n        <text x=\"506\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">03 · 分析</text>\n        <text x=\"666\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">04 · Upload</text>\n        <text x=\"666\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">04 · 上报</text>\n\n        <rect x=\"44\" y=\"76\" width=\"164\" height=\"176\" rx=\"16\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n        <rect x=\"234\" y=\"76\" width=\"164\" height=\"176\" rx=\"16\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n        <rect x=\"424\" y=\"76\" width=\"164\" height=\"176\" rx=\"16\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n        <rect x=\"614\" y=\"76\" width=\"104\" height=\"176\" rx=\"16\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n\n        <circle cx=\"126\" cy=\"126\" r=\"30\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <path d=\"M126 96v60M96 126h60\" class=\"svg-stroke-soft\" stroke-width=\"1.6\"/>\n        <text x=\"126\" y=\"181\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-en\">3-axis MEMS</text>\n        <text x=\"126\" y=\"181\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-zh\">三轴 MEMS</text>\n        <text x=\"126\" y=\"202\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-en\">tilt · acceleration</text>\n        <text x=\"126\" y=\"219\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-en\">temperature</text>\n        <text x=\"126\" y=\"202\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-zh\">倾角 · 加速度</text>\n        <text x=\"126\" y=\"219\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-zh\">温度</text>\n\n        <path d=\"M288 134h56M316 106v56\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <circle cx=\"316\" cy=\"134\" r=\"34\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"2\"/>\n        <text x=\"316\" y=\"181\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-en\">Schedule or event</text>\n        <text x=\"316\" y=\"181\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong lang-zh\">定时或事件触发</text>\n        <text x=\"316\" y=\"204\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">tilt / vibration wake-up</text>\n        <text x=\"316\" y=\"204\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">倾角 / 振动唤醒</text>\n\n        <polyline points=\"454,150 476,118 498,160 520,108 542,150 562,138\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2.4\"/>\n        <rect x=\"454\" y=\"184\" width=\"18\" height=\"38\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.2\"/>\n        <rect x=\"482\" y=\"162\" width=\"18\" height=\"60\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.2\"/>\n        <rect x=\"510\" y=\"132\" width=\"18\" height=\"90\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.2\"/>\n        <rect x=\"538\" y=\"170\" width=\"18\" height=\"52\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.2\"/>\n        <text x=\"506\" y=\"244\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-accent\">FFT</text>\n        <text x=\"506\" y=\"278\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-strong lang-en\">dominant frequency</text>\n        <text x=\"506\" y=\"295\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-strong lang-en\">+ amplitude</text>\n        <text x=\"506\" y=\"278\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-strong lang-zh\">主频</text>\n        <text x=\"506\" y=\"295\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text-strong lang-zh\">+ 幅值</text>\n\n        <path d=\"M638 136c19-19 37-19 56 0M648 150c12-11 24-11 36 0M658 164c6-5 14-5 22 0\" fill=\"none\" class=\"svg-stroke\" stroke-width=\"2\"/>\n        <circle cx=\"666\" cy=\"189\" r=\"8\" class=\"svg-fill-soft svg-stroke\" stroke-width=\"1.6\"/>\n        <text x=\"666\" y=\"225\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-strong\">MQTT</text>\n        <text x=\"666\" y=\"246\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-en\">NB-IoT / 4G</text>\n        <text x=\"666\" y=\"246\" text-anchor=\"middle\" font-size=\"10.5\" class=\"svg-text lang-zh\">NB-IoT / 4G</text>\n\n        <path d=\"M208 164h26M398 164h26M588 164h26\" class=\"svg-stroke-soft\" stroke-width=\"1.7\"/>\n        <polyline points=\"226,158 234,164 226,170\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.7\"/>\n        <polyline points=\"416,158 424,164 416,170\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.7\"/>\n        <polyline points=\"606,158 614,164 606,170\" fill=\"none\" class=\"svg-stroke-soft\" stroke-width=\"1.7\"/>\n\n        <text x=\"380\" y=\"322\" text-anchor=\"middle\" font-size=\"11.2\" class=\"svg-text-accent lang-en\">400 Hz watch sampling · 2000 Hz event sampling</text>\n        <text x=\"380\" y=\"342\" text-anchor=\"middle\" font-size=\"11.2\" class=\"svg-text-accent lang-en\">0.1 Hz frequency resolution · 200 Hz bandwidth</text>\n        <text x=\"380\" y=\"322\" text-anchor=\"middle\" font-size=\"11.2\" class=\"svg-text-accent lang-zh\">400 Hz 守候采样 · 2000 Hz 事件采样</text>\n        <text x=\"380\" y=\"342\" text-anchor=\"middle\" font-size=\"11.2\" class=\"svg-text-accent lang-zh\">0.1 Hz 频率分辨率 · 200 Hz 带宽</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        The same device supports slow structural-trend monitoring and fast event capture. FFT converts the vibration waveform into dominant frequency and amplitude, so alarms can be based on motion signatures rather than tilt alone.\n        \n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== DATA OUTPUT ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/wireless-tilt-vibration/wireless-vibration-fft-output.jpg\" alt=\"SCST-WV02 time-domain vibration waveform and FFT spectrum output\" width=\"1293\" height=\"709\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Data output</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          From waveform to usable engineering indicators\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          For each acquisition period, SCST-WV02 can provide tilt, acceleration, vibration frequency, vibration amplitude, temperature, battery state and position metadata. The cloud platform then binds the data to measurement points, thresholds and project drawings.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Time-domain waveform</b><p>Captures event amplitude over time, useful for judging impact, short-term disturbance and vibration duration.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>FFT frequency spectrum</b><p>Extracts dominant frequency and amplitude, turning raw vibration into structural-health features.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Temperature-linked interpretation</b><p>Temperature is recorded with the same device, making it easier to separate thermal effects from true motion.</p></div></li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== SPECIFICATIONS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Specifications</div>\n      <h2>SCST-WV02 Technical Specifications</h2>\n      <p>The updated SCST-WV02 configuration adds temperature as a measured element, improves acceleration and vibration resolution, and supports NB-IoT or 4G network selection.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Item</th>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">Specification</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Measurement</td><td>Elements</td><td class=\"hl\">Tilt, acceleration, vibration frequency, vibration amplitude, temperature</td></tr>\n          <tr><td rowspan=\"5\">Tilt</td><td>Range</td><td>±90°</td></tr>\n          <tr><td>Resolution</td><td>0.001°</td></tr>\n          <tr><td>Accuracy 1</td><td class=\"hl\">0.005° within ±15°</td></tr>\n          <tr><td>Accuracy 2</td><td>0.01° within ±90°</td></tr>\n          <tr><td>Temperature drift</td><td>&lt;0.01° (-20 ℃ ~ +50 ℃)</td></tr>\n          <tr><td rowspan=\"3\">Acceleration</td><td>Range</td><td>±2g</td></tr>\n          <tr><td>Resolution</td><td class=\"hl\">0.001 mg (1 µg)</td></tr>\n          <tr><td>Accuracy</td><td class=\"hl\">0.01 mg (10 µg)</td></tr>\n          <tr><td rowspan=\"4\">Vibration</td><td>Frequency</td><td class=\"hl\">Resolution 0.1 Hz; bandwidth 200 Hz</td></tr>\n          <tr><td>Amplitude</td><td class=\"hl\">Resolution 0.01 mg; accuracy 0.05 mg</td></tr>\n          <tr><td>Noise density</td><td>18 µg/√Hz (≈0.001 °/√Hz)</td></tr>\n          <tr><td>Recommended amplitude</td><td>Suitable for amplitude above 1 mg</td></tr>\n          <tr><td>Reporting</td><td>Interval</td><td>0s ~ 7200s; default 7200s</td></tr>\n          <tr><td>Communication</td><td>Network</td><td>NB-IoT / 4G (select one)</td></tr>\n          <tr><td>Interface</td><td>Local port</td><td>USB-C (configuration &amp; charging)</td></tr>\n          <tr><td>Storage</td><td>Onboard flash</td><td>512 MB flash (optional)</td></tr>\n          <tr><td rowspan=\"4\">Power</td><td>Battery</td><td>Non-rechargeable Li-SOCl2 or rechargeable lithium battery</td></tr>\n          <tr><td>Operating life</td><td class=\"hl\">Li-SOCl2: up to 36 months at 4 acquisitions/day; rechargeable: up to 12 months</td></tr>\n          <tr><td>Charging</td><td>USB-C, 5 V (rechargeable version)</td></tr>\n          <tr><td>Consumption</td><td>&lt;0.65 mA @ DC 3.6 V</td></tr>\n          <tr><td>Protocol</td><td>Standard</td><td>MQTT v3.1.1</td></tr>\n          <tr><td rowspan=\"3\">Mechanical</td><td>Dimensions</td><td>Bottom OD 13 cm; height 15 cm</td></tr>\n          <tr><td>Material</td><td>High-strength aging-resistant polyurethane</td></tr>\n          <tr><td>Weight</td><td>1.5 kg</td></tr>\n          <tr><td>Environment</td><td>Temp. / rating</td><td>-20 ℃ ~ +85 ℃ / IP68</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== APPLICATIONS ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Applications</div>\n      <h2>Where SCST-WV02 Adds Value Beyond a Tiltmeter</h2>\n      <p>Choose SCST-WV02 when rotation, vibration and temperature need to be interpreted together, or when a remote point must operate without cabling or external power.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\"><span class=\"tag\">Building safety</span><h3 style=\"margin-top:12px;\">Building Tilt &amp; Vibration</h3><p>Tracks slow tilt while capturing short vibration events from construction, demolition or traffic disturbance nearby.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Tower assets</span><h3 style=\"margin-top:12px;\">Transmission &amp; Telecom Towers</h3><p>Cable-free tilt and vibration monitoring for unpowered outdoor towers, with IP68 protection and battery operation.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Bridge structures</span><h3 style=\"margin-top:12px;\">Bridge Tilt Monitoring</h3><p>Combines pier or deck tilt trends with vibration frequency signatures under traffic and wind.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Geohazards</span><h3 style=\"margin-top:12px;\">Slope and Rockfall Warning</h3><p>Low-power remote points can be deployed on unstable blocks or protection structures where wiring is impractical.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Outdoor monitoring</span><h3 style=\"margin-top:12px;\">Unattended Outdoor Sites</h3><p>Sealed housing and cellular upload support long unattended monitoring without sunlight or grid power.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">Structural health</span><h3 style=\"margin-top:12px;\">Event-Based Safety Assessment</h3><p>Dominant frequency, amplitude and tilt change help distinguish normal environmental vibration from abnormal structural response.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== INSTALLATION & CLOUD ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Installation &amp; cloud</div>\n      <h2>Bolt Down, Bind, Set Thresholds</h2>\n      <p>SCST-WV02 is designed for simple civil installation. The important engineering work is choosing a rigid mounting point, binding the device correctly and setting thresholds that reflect the structure's risk model.</p>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card reveal\">\n        <h3>Field installation checklist</h3>\n        <ul class=\"feature-list\" style=\"margin-top:14px;\">\n          <li><span class=\"fi\">1</span><div><b>Install on a rigid structural surface</b><p>The bolt-down base must couple directly to the monitored member, not to loose render, tiles or temporary fixtures.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Align the sensitive axes</b><p>Mark the monitored direction before drilling; record the initial tilt and installation orientation as the baseline.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Bind network and device ID</b><p>Choose NB-IoT or 4G before delivery, then bind the point in the cloud automation-management page.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Set rate and cumulative thresholds</b><p>Use control indicators for tilt rate, cumulative tilt and vibration-event alarms per point.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Cloud workflow</h3>\n        <ul class=\"feature-list\" style=\"margin-top:14px;\">\n          <li><span class=\"fi\">✓</span><div><b>Project overview</b><p>Project details, location, stakeholders and remarks are maintained in one project record.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Monitoring cloud map</b><p>Measurement points are placed on drawings or maps, with alarm status visible directly on the project view.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Data summary &amp; analysis</b><p>Tilt, vibration and temperature series can be filtered by time, form type and measurement zone.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Daily reports and automation status</b><p>Automated points feed daily reports and device-status management for O&amp;M teams.</p></div></li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Field Questions, Straight Answers</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>How is SCST-WV02 different from a normal wireless tiltmeter?</summary>\n        <div class=\"faq-body\">A normal wireless tiltmeter focuses on slow tilt change. SCST-WV02 adds acceleration, vibration frequency, vibration amplitude and temperature, so it can capture sudden vibration events and provide context for whether a tilt change is structural or environmental.</div>\n      </details>\n      <details>\n        <summary>When should I choose SCST-WV02 instead of the tiltmeter series page product?</summary>\n        <div class=\"faq-body\">Choose SCST-WV02 when vibration or impact matters: bridges under traffic, towers in wind, buildings near construction, slopes with block movement, or remote outdoor points where event-triggered reporting is valuable. For pure long-term low-frequency tilt, the standard tiltmeter series is usually enough.</div>\n      </details>\n      <details>\n        <summary>How long does the battery last?</summary>\n        <div class=\"faq-body\">With the non-rechargeable Li-SOCl2 battery, operating life is up to 36 months at 4 acquisitions per day. The rechargeable lithium version runs up to 12 months. High-frequency event triggers, shorter reporting intervals and weak network coverage will shorten life.</div>\n      </details>\n      <details>\n        <summary>Does it need sunlight or external power?</summary>\n        <div class=\"faq-body\">No. The battery-powered configuration is designed for sites without sunlight and without external power. If the rechargeable version is selected, USB-C charging is available at 5 V.</div>\n      </details>\n      <details>\n        <summary>Which network should we choose: NB-IoT or 4G?</summary>\n        <div class=\"faq-body\">NB-IoT is usually preferred for low-power sparse reporting where coverage is stable. 4G is preferred when event data, denser uploads or broader operator coverage are more important. The network mode is selected before delivery.</div>\n      </details>\n      <details>\n        <summary>Can it replace a professional vibration analyzer?</summary>\n        <div class=\"faq-body\">It is a structural monitoring sensor, not a lab vibration analyzer. Its strength is unattended long-term monitoring, triggered reporting and 0.1 Hz / 200 Hz vibration feature extraction at engineering points. For machinery diagnostics or very high-frequency vibration, use a dedicated vibration analyzer.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "vibrating-wire-sensors": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>Vibrating-Wire Sensors</span>\n    </div>\n    <h1>Vibrating-Wire Sensors &amp; Acquisition</h1>\n    <p class=\"sub\">\n      A one-stop stress-monitoring solution: six vibrating-wire sensor families plus an intelligent frequency-sweep acquisition system that also reads most other vendors' VW sensors — from foundation-pit struts to dam cores.\n      \n    </p>\n    <div class=\"model\">SCSE-VW01 · VIBRATING-WIRE ACQUISITION</div>\n  </div>\n</div>\n\n<!-- ====== OVERVIEW ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-stressmeter.jpg\" alt=\"Catalog rendering of a vibrating-wire concrete stressmeter with stainless-steel sensing body and signal cable\" width=\"1448\" height=\"1086\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Overview</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Frequency-based sensing that stays stable for decades\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          Vibrating-wire sensing converts stress, strain and pressure into the resonant frequency of a tensioned steel wire — a signal immune to cable-length attenuation, resistant to electromagnetic interference and nearly drift-free over years. That is why it remains the de-facto standard for permanently embedded monitoring of foundation-pit supports, tunnel linings, dam bodies and bridge pile foundations.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Engineered for permanent embedment</b><p>Frequency output is unaffected by long cables and EMI; long-term drift stays below 0.1% FS per year.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Synchronized temperature compensation</b><p>Every sensor carries a built-in thermistor sampled together with frequency, stripping thermal effects out of the stress reading.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>One family, every stress parameter</b><p>Rebar stress, surface and embedded strain, anchor-cable load, earth pressure and pore water pressure — all on one acquisition system.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">16-ch</div><div class=\"name\">Max Acquisition Channels</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">0.025%</div><div class=\"name\">Piezometer Resolution (FS)</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">&lt;0.1% FS</div><div class=\"name\">Long-Term Drift / Year</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">50Ω–10kΩ</div><div class=\"name\">Sensor Auto-ID Range</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== HOW IT WORKS ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Working principle</div>\n      <h2>How a Steel Wire Measures Stress</h2>\n      <p>A steel wire 0.15–0.20 mm thick and 100–150 mm long is tensioned between two end blocks fixed to the structure. Its resonant frequency follows f = (1/2L)·√(T/ρ): wire tension is proportional to f², so any strain in the member shifts the frequency — a principle in continuous dam-monitoring service since the 1930s.</p>\n    </div>\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 760 380\" role=\"img\" aria-label=\"Vibrating-wire sensor cross-section: tensioned wire, pluck/readout coil, thermistor and frequency output\">\n        <!-- structural member -->\n        <rect x=\"30\" y=\"300\" width=\"700\" height=\"34\" rx=\"6\" class=\"svg-fill-soft\"/>\n        <text x=\"380\" y=\"322\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text lang-en\">Monitored member (rebar / concrete / anchor cable)</text>\n        <text x=\"380\" y=\"322\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text lang-zh\">被测构件（钢筋 / 混凝土 / 锚索）</text>\n        <!-- sensor body -->\n        <rect x=\"100\" y=\"140\" width=\"400\" height=\"100\" rx=\"12\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <text x=\"110\" y=\"130\" font-size=\"13\" class=\"svg-text-strong lang-en\">Sensor body</text>\n        <text x=\"110\" y=\"130\" font-size=\"13\" class=\"svg-text-strong lang-zh\">传感器壳体</text>\n        <!-- end blocks anchored to member -->\n        <rect x=\"112\" y=\"160\" width=\"30\" height=\"60\" rx=\"4\" class=\"svg-fill-soft\"/>\n        <rect x=\"458\" y=\"160\" width=\"30\" height=\"60\" rx=\"4\" class=\"svg-fill-soft\"/>\n        <line x1=\"127\" y1=\"240\" x2=\"127\" y2=\"300\" stroke-width=\"2\" stroke-dasharray=\"4 4\" class=\"svg-stroke-soft\"/>\n        <line x1=\"473\" y1=\"240\" x2=\"473\" y2=\"300\" stroke-width=\"2\" stroke-dasharray=\"4 4\" class=\"svg-stroke-soft\"/>\n        <text text-anchor=\"end\" font-size=\"12\" class=\"svg-text lang-en\"><tspan x=\"121\" y=\"266\">End blocks fixed</tspan><tspan x=\"121\" y=\"282\">to structure</tspan></text>\n        <text x=\"121\" y=\"276\" text-anchor=\"end\" font-size=\"12\" class=\"svg-text lang-zh\">端块与结构固定</text>\n        <!-- tensioned wire -->\n        <line x1=\"142\" y1=\"190\" x2=\"458\" y2=\"190\" stroke-width=\"2.5\" class=\"svg-stroke\"/>\n        <path d=\"M150 190 Q 300 176 450 190\" fill=\"none\" stroke-width=\"1\" stroke-dasharray=\"3 4\" class=\"svg-stroke\"/>\n        <path d=\"M150 190 Q 300 204 450 190\" fill=\"none\" stroke-width=\"1\" stroke-dasharray=\"3 4\" class=\"svg-stroke\"/>\n        <text x=\"300\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Tensioned steel wire · tension ∝ f²</text>\n        <text x=\"300\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">张紧钢弦 · 张力 ∝ f²</text>\n        <!-- coil -->\n        <rect x=\"270\" y=\"92\" width=\"60\" height=\"34\" rx=\"6\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n        <path d=\"M278 109 q6 -9 12 0 q6 9 12 0 q6 -9 12 0 q6 9 12 0\" fill=\"none\" stroke-width=\"1.6\" class=\"svg-stroke\"/>\n        <line x1=\"300\" y1=\"126\" x2=\"300\" y2=\"186\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\" class=\"svg-stroke\"/>\n        <text x=\"340\" y=\"100\" font-size=\"13\" class=\"svg-text-strong lang-en\">Electromagnetic coil</text>\n        <text x=\"340\" y=\"100\" font-size=\"13\" class=\"svg-text-strong lang-zh\">电磁线圈</text>\n        <text x=\"340\" y=\"118\" font-size=\"12\" class=\"svg-text lang-en\">plucks with a 1–5 kHz sweep, then listens</text>\n        <text x=\"340\" y=\"118\" font-size=\"12\" class=\"svg-text lang-zh\">1–5kHz 扫频激励后转为接收</text>\n        <!-- thermistor -->\n        <circle cx=\"430\" cy=\"165\" r=\"7\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n        <text x=\"430\" y=\"155\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-en\">NTC thermistor</text>\n        <text x=\"430\" y=\"155\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-zh\">NTC 热敏电阻</text>\n        <!-- strain arrows -->\n        <line x1=\"38\" y1=\"190\" x2=\"92\" y2=\"190\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <path d=\"M44 190 l10 -6 v12 z\" class=\"svg-fill-soft\" stroke=\"none\"/>\n        <text x=\"64\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-accent\">ε</text>\n        <line x1=\"508\" y1=\"190\" x2=\"556\" y2=\"190\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <path d=\"M550 190 l-10 -6 v12 z\" class=\"svg-fill-soft\" stroke=\"none\"/>\n        <text x=\"532\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-accent\">ε</text>\n        <!-- frequency output -->\n        <path d=\"M560 190 q8 -26 16 0 q8 26 16 0 q8 -26 16 0 q8 26 16 0 q8 -26 16 0 q8 26 16 0\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke\"/>\n        <text x=\"612\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-en\">Frequency out</text>\n        <text x=\"612\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" class=\"svg-text-strong lang-zh\">频率信号输出</text>\n        <text x=\"612\" y=\"166\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-en\">1–10 mV ring-down</text>\n        <text x=\"612\" y=\"166\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text lang-zh\">余振感应 1–10mV</text>\n        <!-- formula -->\n        <text x=\"380\" y=\"262\" text-anchor=\"middle\" font-size=\"15\" class=\"svg-text-accent\">ε = K · (f² − f₀²) − k_T · (T − T₀)</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        The acquisition unit counts zero-crossings (or runs an FFT) on the ring-down to read f; the built-in thermistor is sampled in the same cycle to feed the temperature-compensation formula.\n        \n      </div>\n    </div>\n    <div class=\"grid grid-3\" style=\"margin-top:32px;\">\n      <div class=\"card reveal\">\n        <h3>Pluck, Then Listen</h3>\n        <p>The coil fires a 1–5 kHz frequency-sweep pulse to set the wire ringing, then switches to receive mode. The ring-down at the wire's resonant frequency induces a 1–10 mV signal from which frequency is extracted by zero-crossing counting or FFT.</p>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Frequency, Not Voltage</h3>\n        <p>Because the measurand is a frequency rather than an analog voltage, the signal is immune to long-cable attenuation and electromagnetic interference — the physical reason VW sensors survive decades of permanent embedment in concrete.</p>\n      </div>\n      <div class=\"card reveal\">\n        <h3>Temperature, Stripped Out</h3>\n        <p>A 10 °C swing can bias an uncompensated stress reading by 5–10%. The built-in NTC thermistor (typ. 10 kΩ at 25 °C) is sampled synchronously with frequency, and the k_T term in the formula strips the thermal effect out.</p>\n      </div>\n    </div>\n    <p class=\"reveal\" style=\"color:var(--text-2); margin-top:28px; max-width:860px;\">\n      Inside the piezometer, the same wire sits behind a stainless-steel diaphragm: water pressure deflects the diaphragm by a few micrometres, a push rod converts that into wire tension, and pressure follows P = G·(f² − f₀²) + Δ_T·(T − T₀) — a two-stage mechanical amplification that underpins its decade-scale stability.\n      \n    </p>\n  </div>\n</section>\n\n<!-- ====== SENSOR FAMILY ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Sensor series</div>\n      <h2>Six Families, One-Stop Stress Monitoring</h2>\n      <p>From rebar stress to pore water pressure, the vibrating-wire family covers the stress-monitoring needs of nearly every geotechnical structure.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card media-card reveal\"><div class=\"media\"><img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-rebar-stressmeter.jpg\" alt=\"Catalog rendering of a vibrating-wire rebar stressmeter with inline stainless-steel sensing section\" loading=\"lazy\" width=\"1448\" height=\"1086\" decoding=\"async\"></div><div class=\"body\"><span class=\"tag\">SCSE-VW01 REBAR</span><h3>Rebar Stressmeter</h3><p>Monitors rebar stress on the vibrating-wire principle — welded in line with the reinforcement before casting.</p></div></div>\n      <div class=\"card media-card reveal\"><div class=\"media\"><img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-surface-strain-gauge.jpg\" alt=\"Catalog rendering of a surface-mounted vibrating-wire strain gauge with machined mounting blocks\" loading=\"lazy\" width=\"1448\" height=\"1086\" decoding=\"async\"></div><div class=\"body\"><span class=\"tag\">SCSE-VW01-STRAIN</span><h3>Surface Strain Gauge</h3><p>Mounts directly on the structure surface to measure strain on existing concrete and steel members.</p></div></div>\n      <div class=\"card media-card reveal\"><div class=\"media\"><img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-stressmeter.jpg\" alt=\"Catalog rendering of a vibrating-wire concrete stressmeter with load-transfer flanges\" loading=\"lazy\" width=\"1448\" height=\"1086\" decoding=\"async\"></div><div class=\"body\"><span class=\"tag\">EMBEDDED VW</span><h3>Concrete Stressmeter</h3><p>Embedded during casting to track long-term stress changes inside concrete members and mass-concrete structures.</p></div></div>\n      <div class=\"card reveal\"><span class=\"tag\">SCSE-VW01-LOAD</span><h3 style=\"margin-top:12px;\">Anchor-Cable Load Cell</h3><p>High-range design monitors the load on anchor cables and rock bolts in slope and excavation support systems.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">SCSE-VW01-PRESSURE</span><h3 style=\"margin-top:12px;\">Earth Pressure Cell</h3><p>Diaphragm sensing measures soil pressure against retaining structures and within embankment fills.</p></div>\n      <div class=\"card reveal\"><span class=\"tag\">SCSE-VW01-PZ</span><h3 style=\"margin-top:12px;\">Piezometer</h3><p>Pore-water-pressure monitoring with a 0–4 MPa range; the diaphragm-plus-wire stage delivers 0.025% FS resolution.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== ACQUISITION SYSTEM ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Acquisition system</div>\n      <h2>SCSE-VW01 Series: The Hub Between Sensors and Cloud</h2>\n      <p>Three configurations — SCSE-VW01 (16-ch), 8-channel and 4-channel variants — digitize vibrating-wire signals and hand them to the data gateway and cloud platform. A handheld re-survey unit (handheld verification unit) covers manual on-site verification.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Intelligent frequency-sweep</b><p>Automatically matches each sensor's resonant frequency — a clear advantage on long cables and in strong electromagnetic interference.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>High-voltage excitation</b><p>Programmable high-voltage excitation keeps signals stable and reliable, even with slowly degrading sensor coils.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Plug-and-play, multi-vendor compatible</b><p>Auto-detects sensor type and reads coils from 50 Ω to 10 kΩ — most vendors' VW sensors connect with no replacement needed.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Built-in temperature channel</b><p>Thermistor channels sample synchronously with frequency for accurate temperature compensation.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"visual reveal\"><img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-field-cabinet.jpg\" alt=\"Vibrating-wire acquisition cabinet deployed at a foundation-pit site\" width=\"1000\" height=\"1178\" decoding=\"async\"></div>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px;\">\n      <h2 style=\"font-size:24px;\">From Wire to Cloud in Four Hops</h2>\n    </div>\n    <div class=\"grid grid-4\">\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 12h3l2-7 4 14 3-10 2 3h6\"/></svg></div><h3>1 · VW Sensor</h3><p>Stress, strain or pressure changes the steel wire's resonant frequency.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"12\" rx=\"2\"/><circle cx=\"8\" cy=\"12\" r=\"1.5\"/><circle cx=\"12\" cy=\"12\" r=\"1.5\"/><circle cx=\"16\" cy=\"12\" r=\"1.5\"/></svg></div><h3>2 · Acquisition Module</h3><p>Sweep-excites the wire, reads the ring-down and digitizes frequency plus temperature.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0\"/><path d=\"M1.42 9a16 16 0 0 1 21.16 0\"/><path d=\"M8.53 16.11a6 6 0 0 1 6.95 0\"/><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"/></svg></div><h3>3 · Data Gateway</h3><p>Uplinks over 4G / RS485 with local buffering against network loss.</p></div>\n      <div class=\"card reveal\"><div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg></div><h3>4 · Cloud Platform</h3><p>SoilCreate Monitoring Cloud handles curves, tiered alerts and reports.</p></div>\n    </div>\n\n    <div class=\"section-head reveal\" style=\"margin-top:64px;\">\n      <h2 style=\"font-size:24px;\">Acquisition Module Specifications</h2>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Parameter</th>\n            <th scope=\"col\">SCSE-VW01-4 (4-Channel)</th>\n            <th scope=\"col\">SCSE-VW01 (16-Channel)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Frequency range</td><td>1000–5000 Hz</td><td>1000–5000 Hz</td></tr>\n          <tr><td>Excitation</td><td>Programmable high-voltage</td><td class=\"hl\">Programmable high-voltage + programmable &amp; intelligent frequency-sweep</td></tr>\n          <tr><td>Sensor auto-ID</td><td>Coils 50 Ω – 10 kΩ</td><td>Coils 50 Ω – 10 kΩ</td></tr>\n          <tr><td>Temperature element</td><td>Thermistor (customizable)</td><td>Thermistor (customizable)</td></tr>\n          <tr><td>Uplink</td><td>4G / RS485</td><td>4G / RS485</td></tr>\n          <tr><td>Power supply</td><td>Built-in 8.4 V lithium battery</td><td>9–24 V solar / mains</td></tr>\n          <tr><td>Operating temperature</td><td>-20 ~ 60 ℃</td><td>-20 ~ 70 ℃</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ====== EMBEDMENT & FIELD PRACTICE ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Field practice</div>\n      <h2>Embedment &amp; Field Practice</h2>\n      <p>Sensor accuracy and installation accuracy are two different things: a piezometer leaves the factory at 0.025% FS, but an unsaturated filter or a mis-recorded depth can put 5–10% of error into the data. These field rules close that gap.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">1</span><div><b>Saturate the filter under water — at least 24 h</b><p>A piezometer's porous filter is never lowered dry. Residual air bubbles bias long-term readings low by 5–10%, and no later calibration can recover it.</p></div></li>\n          <li><span class=\"fi\">2</span><div><b>Two gates before concrete embedment</b><p>A 48-hour burn-in plus independent verification with a frequency meter. Once the concrete is poured there is no second chance.</p></div></li>\n          <li><span class=\"fi\">3</span><div><b>Record the actual depth to 0.1 m</b><p>The installed depth must match the design documents — a wrong depth record is the hardest error to trace in later data back-analysis.</p></div></li>\n          <li><span class=\"fi\">4</span><div><b>Seal the borehole above the sensor</b><p>Sand or bentonite sealing prevents water from connecting across layers; without it, the measuring point loses its layer-specific meaning.</p></div></li>\n          <li><span class=\"fi\">5</span><div><b>Choose gauge vs. absolute correctly</b><p>Vented (gauge) types for water-level work — atmospheric pressure is removed automatically; absolute types for sealed, confined water pressure. The wrong choice makes the data oscillate with the weather.</p></div></li>\n        </ul>\n      </div>\n      <div class=\"reveal\">\n        <div class=\"card\">\n          <span class=\"tag\">Open protocol</span>\n          <h3 style=\"margin-top:12px;\">Already Own Another Vendor's VW Sensors?</h3>\n          <p>SoilCreate acquisition terminals use an open protocol and identify any vibrating-wire sensor with a coil resistance from 50 Ω to 10 kΩ — covering Geokon, Sisgeo, Roctest, Maihak and mainstream domestic brands. Existing sensors connect to the SoilCreate Monitoring Cloud without replacement.</p>\n        </div>\n        <div class=\"card\" style=\"margin-top:16px;\">\n          <span class=\"tag\">Fault triage</span>\n          <h3 style=\"margin-top:12px;\">Lost Contact After Embedment? Don't Break Concrete First</h3>\n          <p>The field triage order: switch to intelligent frequency-sweep, step the excitation voltage level, verify independently with a frequency meter — and only then consider physical access. Intelligent sweep often recovers sensors with slowly degrading coils.</p>\n        </div>\n      </div>\n    </div>\n    <div class=\"gallery\" style=\"margin-top:40px;\">\n      <figure class=\"reveal\">\n        <img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-acquisition-cabinet.jpg\" alt=\"Vibrating-wire acquisition cabinet installed on a foundation-pit guard rail\" loading=\"lazy\" width=\"1000\" height=\"750\" decoding=\"async\">\n        <figcaption>Acquisition cabinet on a foundation-pit site, cabled to embedded VW sensors</figcaption>\n      </figure>\n      <figure class=\"reveal\">\n        <img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-terminal-wiring.jpg\" alt=\"Inside a field acquisition cabinet: VW terminal and sensor wiring\" loading=\"lazy\" width=\"1000\" height=\"750\" decoding=\"async\">\n        <figcaption>Inside the cabinet: acquisition terminal with multi-channel sensor wiring</figcaption>\n      </figure>\n      <figure class=\"reveal\">\n        <img src=\"/images/products/vibrating-wire-sensors/vibrating-wire-piezometer-probe.jpg\" alt=\"Vibrating-wire piezometer probe with signal cable\" loading=\"lazy\" width=\"1000\" height=\"175\" decoding=\"async\">\n        <figcaption>Vibrating-wire piezometer probe — the porous filter is saturated under water before lowering</figcaption>\n      </figure>\n    </div>\n  </div>\n</section>\n\n<!-- ====== WATER LEVEL SYSTEM ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Environmental monitoring</div>\n      <h2>Automated Water Level Monitoring System</h2>\n      <p>Two sensing principles: pressure-sensitive SCST-WL Series at 0.5% FS accuracy, and vibrating-wire SCSE-VW01-PZ for long-term stable monitoring — covering foundation-pit, reservoir and groundwater levels.</p>\n    </div>\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/hydrostatic-level-gauge/water-level-probe.jpg\" alt=\"Submersible water-level transducer with signal cable\" width=\"608\" height=\"549\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Integrated design, no trenching</b><p>The all-in-one unit drops straight into the standpipe — no trenching or surface wiring required.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Automatic temperature compensation</b><p>Built-in compensation keeps readings accurate through seasonal and day-night temperature swings.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>RS485 + 3-month battery life</b><p>Standard RS485 communication interface with over three months of operation per charge.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Part of a complete pit-safety system</b><p>Pairs with inclinometers and VW sensors to assess dewatering, detect leakage and track groundwater trends.</p></div></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"grid grid-4\" style=\"margin-top:48px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">0.5% FS</div><div class=\"name\">Pressure-Sensitive Accuracy</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">RS485</div><div class=\"name\">Communication Interface</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">3+</div><div class=\"name\">Months of Battery Life</div></div>\n      <div class=\"number-card reveal\"><div class=\"num\">AUTO</div><div class=\"name\">Temperature Compensation</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Frequently Asked Questions</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>Can SoilCreate loggers read vibrating-wire sensors from other vendors?</summary>\n        <div class=\"faq-body\">Yes. The acquisition terminals use an open protocol and auto-identify any VW sensor with a coil resistance between 50 Ω and 10 kΩ — covering Geokon, Sisgeo, Roctest, Maihak and mainstream domestic brands. Your existing sensors connect to the SoilCreate Monitoring Cloud without replacement.</div>\n      </details>\n      <details>\n        <summary>Do long signal cables degrade the reading?</summary>\n        <div class=\"faq-body\">The measurand is a frequency, not a voltage, so it does not attenuate with cable length and resists electromagnetic interference. On long cables and in strong-EMI environments, the intelligent frequency-sweep excitation gives an additional margin by automatically matching the wire's resonant frequency.</div>\n      </details>\n      <details>\n        <summary>Why does temperature compensation matter so much?</summary>\n        <div class=\"faq-body\">Ambient temperature changes the steel wire's tension. A 10 °C swing can bias an uncompensated stress reading by 5–10% — in high temperature-swing environments, uncompensated VW data is essentially unusable. Every SoilCreate VW sensor carries a built-in thermistor sampled synchronously with frequency, feeding the correction ε = K·(f² − f₀²) − k_T·(T − T₀).</div>\n      </details>\n      <details>\n        <summary>The channel reads zero frequency, or the frequency is unstable — what do I check?</summary>\n        <div class=\"faq-body\">Frequency = 0 usually means a broken coil or mismatched excitation parameters: measure the coil resistance with a multimeter and step through the excitation voltage levels. An unstable frequency typically means single-frequency excitation does not match the wire, or interference — switch to intelligent frequency-sweep. If a freshly commissioned unit drops offline, check the 4G / SIM / APN configuration by logging into the controller.</div>\n      </details>\n      <details>\n        <summary>Our piezometer reads consistently low after installation. Why?</summary>\n        <div class=\"faq-body\">The most common cause is air bubbles trapped in the porous filter — it was not saturated under water before lowering. The filter must soak under water for at least 24 hours; if installed dry or under-saturated, retrieve the sensor and re-saturate it. A sluggish response usually means a silted filter — back-flush or replace it.</div>\n      </details>\n      <details>\n        <summary>Why does our pore-pressure data move with the weather?</summary>\n        <div class=\"faq-body\">That is the signature of a gauge/absolute selection error. A gauge (vented) sensor automatically subtracts atmospheric pressure and suits water-level monitoring; sealed, confined water pressure needs an absolute sensor. If the wrong type is installed, switch to the absolute type or add barometric compensation from a separate atmospheric-pressure sensor.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n",
  "data-acquisition-monitoring-cloud": "<!-- ====== PAGE HERO ====== -->\n<div class=\"page-hero\">\n  <div class=\"container\">\n    <div class=\"crumb\">\n      <a href=\"/\">Home</a> /\n      <a href=\"/\">Products</a> /\n      <span>DAQ &amp; Cloud Platform</span>\n    </div>\n    <h1>Data Acquisition &amp; Monitoring Cloud</h1>\n    <p class=\"sub\">\n      The nerve center of every SoilCreate monitoring system: a self-developed acquisition gateway series and the SoilCreate Monitoring Cloud connect field sensors to dashboards, alerts and AI analytics — one continuous, fully owned data chain.\n      \n    </p>\n    <div class=\"model\">SoilCreate MONITORING CLOUD · SCDA-DG-01 · SCSE-VW01</div>\n  </div>\n</div>\n\n<!-- ====== EDGE DEVICES ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"split\">\n      <div class=\"visual reveal\"><img src=\"/images/products/data-acquisition-monitoring-cloud/data-acquisition-gateway.jpg\" alt=\"SCDA-DG-01 wired data logger — SoilCreate acquisition gateway\" width=\"1000\" height=\"693\" decoding=\"async\"></div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">Acquisition gateway series</div>\n        <h2 style=\"font-size:28px; margin-bottom:16px;\">\n          Edge devices that never lose a reading\n          \n        </h2>\n        <p style=\"color:var(--text-2); margin-bottom:22px;\">\n          Three self-developed gateways cover wired buses, long-range wireless and vibrating-wire sensors. Data is filtered and checked at the edge, buffered locally during network loss, and pushed to the cloud the moment connectivity returns.\n          \n        </p>\n        <ul class=\"feature-list\">\n          <li><span class=\"fi\">✓</span><div><b>Edge computing + filtering</b><p>Anomalies are identified and flagged right at the front end, before upload.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Breakpoint-resume + event-triggered reporting</b><p>On-board storage rides out network loss; rapid changes trigger accelerated reporting.</p></div></li>\n          <li><span class=\"fi\">✓</span><div><b>Hardened for the field</b><p>Solar power sized for 7 days of overcast with 30% reserve, lightning-protected enclosures, remote OTA upgrades.</p></div></li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"grid grid-3\" style=\"margin-top:48px;\">\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"6\" width=\"20\" height=\"12\" rx=\"2\"/><line x1=\"6\" y1=\"10\" x2=\"6\" y2=\"14\"/><line x1=\"10\" y1=\"10\" x2=\"10\" y2=\"14\"/><line x1=\"14\" y1=\"10\" x2=\"18\" y2=\"10\"/><line x1=\"14\" y1=\"14\" x2=\"18\" y2=\"14\"/></svg></div>\n        <span class=\"tag\">SCDA-DG-01</span>\n        <h3 style=\"margin-top:12px;\">Wired Data Logger</h3>\n        <p>RS485 bus input with AutoID auto-addressing, 4G uplink, and 16&nbsp;GB on-board storage for breakpoint-resume on network loss.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0\"/><path d=\"M1.42 9a16 16 0 0 1 21.16 0\"/><path d=\"M8.53 16.11a6 6 0 0 1 6.95 0\"/><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"/></svg></div>\n        <span class=\"tag\">SCDA-DG-01-LORA</span>\n        <h3 style=\"margin-top:12px;\">LoRa Base Station</h3>\n        <p>1&nbsp;km+ transmission range with ad-hoc mesh networking and 4G/MQTT uplink — cable-free coverage for remote, dispersed sites.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"2 12 6 12 9 5 13 19 16 12 22 12\"/></svg></div>\n        <span class=\"tag\">SCSE-VW01</span>\n        <h3 style=\"margin-top:12px;\">VW Acquisition Module</h3>\n        <p>16 channels with intelligent frequency-sweep, compatible with vibrating-wire sensors from multiple vendors. 8-ch (SCSE-VW01-8) and 4-ch (SCSE-VW01-4) variants available.</p>\n      </div>\n    </div>\n\n    <div class=\"grid grid-4\" style=\"margin-top:42px;\">\n      <div class=\"number-card reveal\"><div class=\"num\">16 GB</div><div class=\"name\">On-Board Storage</div><p>Store-and-forward keeps data safe through network loss.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">1 km+</div><div class=\"name\">LoRa Range</div><p>Ad-hoc mesh networking, no cabling required.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">16 ch</div><div class=\"name\">VW Channels / Module</div><p>Intelligent frequency-sweep, multi-vendor compatible.</p></div>\n      <div class=\"number-card reveal\"><div class=\"num\">IP65</div><div class=\"name\">Field Enclosure</div><p>Lightning protection with &lt;10 Ω grounding, −40 to 70 °C.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== INSIDE THE EDGE LAYER ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Edge layer</div>\n      <h2>Inside the Edge Layer: Six Function Blocks</h2>\n      <p>Field-service statistics show that most edge failures trace to power, lightning protection and APN/SIM configuration — not the sensors. That is why every SoilCreate edge device is engineered around six clearly separated function blocks.</p>\n    </div>\n\n    <div class=\"diagram-box reveal\">\n      <svg viewBox=\"0 0 820 380\" role=\"img\" aria-label=\"Edge device block diagram: sensor interfaces and power management feed the main-control SoC, which hands data to local storage and the communication module, all inside a protective enclosure\">\n        <!-- protective enclosure (block 6) -->\n        <rect x=\"32\" y=\"52\" width=\"676\" height=\"292\" rx=\"14\" fill=\"none\" stroke-width=\"2\" stroke-dasharray=\"8 6\" class=\"svg-stroke-soft\"/>\n        <text x=\"44\" y=\"74\" font-size=\"12\" class=\"svg-text-strong lang-en\">Protective enclosure · IP65 / IP67 · −40~70 ℃ · surge 8/20 µs · 20 kA</text>\n        <text x=\"44\" y=\"74\" font-size=\"12\" class=\"svg-text-strong lang-zh\">防护机箱 · IP65 / IP67 · −40~70℃ · 防雷浪涌 8/20µs · 20kA</text>\n        <!-- sensor interfaces -->\n        <rect x=\"48\" y=\"84\" width=\"170\" height=\"92\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <text x=\"133\" y=\"108\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-en\">Sensor interfaces</text>\n        <text x=\"133\" y=\"108\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-zh\">传感器接口</text>\n        <text x=\"133\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">VW sweep · 4–20 mA</text>\n        <text x=\"133\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">振弦扫频 · 4–20mA</text>\n        <text x=\"133\" y=\"148\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">RS-485 · CAN · SDI-12</text>\n        <!-- power management -->\n        <rect x=\"48\" y=\"216\" width=\"170\" height=\"100\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <text x=\"133\" y=\"240\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-en\">Power management</text>\n        <text x=\"133\" y=\"240\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-zh\">电源管理</text>\n        <text x=\"133\" y=\"262\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Solar MPPT charging</text>\n        <text x=\"133\" y=\"262\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">太阳能 MPPT 充电</text>\n        <text x=\"133\" y=\"280\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Li / lead-acid battery</text>\n        <text x=\"133\" y=\"280\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">锂电 / 铅酸蓄电池</text>\n        <text x=\"133\" y=\"298\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">DC-DC 5 / 12 / 24 V</text>\n        <!-- main control SoC -->\n        <rect x=\"280\" y=\"120\" width=\"180\" height=\"150\" rx=\"10\" fill=\"none\" stroke-width=\"2.5\" class=\"svg-stroke\"/>\n        <text x=\"370\" y=\"150\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-en\">Main control SoC</text>\n        <text x=\"370\" y=\"150\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-zh\">主控 SoC</text>\n        <text x=\"370\" y=\"174\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">ARM Cortex-A / RISC-V</text>\n        <text x=\"370\" y=\"192\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">Linux / RTOS</text>\n        <text x=\"370\" y=\"216\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Edge algorithms:</text>\n        <text x=\"370\" y=\"216\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">边缘算法：</text>\n        <text x=\"370\" y=\"234\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">filter · check · flag anomalies</text>\n        <text x=\"370\" y=\"234\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">滤波 · 校验 · 异常标记</text>\n        <!-- local storage -->\n        <rect x=\"520\" y=\"84\" width=\"170\" height=\"92\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <text x=\"605\" y=\"108\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-en\">Local storage</text>\n        <text x=\"605\" y=\"108\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-zh\">本地存储</text>\n        <text x=\"605\" y=\"130\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">SD / eMMC</text>\n        <text x=\"605\" y=\"148\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-en\">Buffer through network loss</text>\n        <text x=\"605\" y=\"148\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text lang-zh\">断网缓冲</text>\n        <!-- communication module -->\n        <rect x=\"520\" y=\"216\" width=\"170\" height=\"100\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-stroke-soft\"/>\n        <text x=\"605\" y=\"240\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-en\">Comms module</text>\n        <text x=\"605\" y=\"240\" text-anchor=\"middle\" font-size=\"13.5\" class=\"svg-text-strong lang-zh\">通讯模块</text>\n        <text x=\"605\" y=\"262\" text-anchor=\"middle\" font-size=\"11.5\" class=\"svg-text\">4G / 5G · NB-IoT · WiFi</text>\n        <text x=\"605\" y=\"280\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-en\">LoRa · BeiDou short message</text>\n        <text x=\"605\" y=\"280\" text-anchor=\"middle\" font-size=\"11\" class=\"svg-text lang-zh\">LoRa · 北斗短报文</text>\n        <!-- arrows: sensors / power -> MCU -->\n        <line x1=\"218\" y1=\"130\" x2=\"273\" y2=\"130\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <path d=\"M 270 126.8 L 277 130 L 270 133.2\" fill=\"none\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <line x1=\"218\" y1=\"266\" x2=\"273\" y2=\"266\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <path d=\"M 270 262.8 L 277 266 L 270 269.2\" fill=\"none\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <!-- arrows: MCU -> storage / comms -->\n        <line x1=\"463\" y1=\"130\" x2=\"513\" y2=\"130\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <path d=\"M 510 126.8 L 517 130 L 510 133.2\" fill=\"none\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <line x1=\"463\" y1=\"266\" x2=\"513\" y2=\"266\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <path d=\"M 510 262.8 L 517 266 L 510 269.2\" fill=\"none\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <!-- arrow: comms -> cloud -->\n        <line x1=\"690\" y1=\"266\" x2=\"729\" y2=\"266\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <path d=\"M 726 262.8 L 733 266 L 726 269.2\" fill=\"none\" stroke-width=\"1.8\" class=\"svg-stroke\"/>\n        <g transform=\"translate(738 244) scale(1.5)\">\n          <path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\" fill=\"none\" stroke-width=\"1.4\" class=\"svg-stroke\"/>\n        </g>\n        <text x=\"757\" y=\"298\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-strong lang-en\">Cloud</text>\n        <text x=\"757\" y=\"298\" text-anchor=\"middle\" font-size=\"12\" class=\"svg-text-strong lang-zh\">云平台</text>\n        <!-- relay annotation -->\n        <text x=\"370\" y=\"368\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-accent lang-en\">Power + sensors → main control → storage + comms</text>\n        <text x=\"370\" y=\"368\" text-anchor=\"middle\" font-size=\"12.5\" class=\"svg-text-accent lang-zh\">电源 + 传感器 → 主控 → 存储 + 通讯</text>\n      </svg>\n      <div class=\"diagram-caption\">\n        The six function blocks of a SoilCreate edge device and the power / main-control / comms relay: power management and the sensor interfaces feed the main-control SoC, which hands data to local storage and the communication module — all housed in the protective enclosure.\n        \n      </div>\n    </div>\n\n    <div class=\"grid grid-3\" style=\"margin-top:32px;\">\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/><rect x=\"9\" y=\"9\" width=\"6\" height=\"6\"/><line x1=\"9\" y1=\"1\" x2=\"9\" y2=\"4\"/><line x1=\"15\" y1=\"1\" x2=\"15\" y2=\"4\"/><line x1=\"9\" y1=\"20\" x2=\"9\" y2=\"23\"/><line x1=\"15\" y1=\"20\" x2=\"15\" y2=\"23\"/><line x1=\"20\" y1=\"9\" x2=\"23\" y2=\"9\"/><line x1=\"20\" y1=\"14\" x2=\"23\" y2=\"14\"/><line x1=\"1\" y1=\"9\" x2=\"4\" y2=\"9\"/><line x1=\"1\" y1=\"14\" x2=\"4\" y2=\"14\"/></svg></div>\n        <h3>Main Control SoC</h3>\n        <p>ARM Cortex-A / RISC-V running Linux or an RTOS, executing edge algorithms — filtering, checking and anomaly flagging before upload.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 12h3l2-7 4 14 3-10 2 3h6\"/></svg></div>\n        <h3>Sensor Interfaces</h3>\n        <p>Vibrating-wire frequency-sweep, 4–20 mA, RS-485, CAN and SDI-12 — one box aggregates mixed sensor fleets.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0\"/><path d=\"M1.42 9a16 16 0 0 1 21.16 0\"/><path d=\"M8.53 16.11a6 6 0 0 1 6.95 0\"/><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"/></svg></div>\n        <h3>Communication Module</h3>\n        <p>4G/5G, NB-IoT, WiFi, LoRa — plus BeiDou short message for sites with no public network at all.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2 3 14h7l-1 8 10-12h-7l1-8z\"/></svg></div>\n        <h3>Power Management</h3>\n        <p>Solar MPPT charging with lithium or lead-acid batteries, and DC-DC rails at 5/12/24 V for the sensor bus.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 12H2\"/><path d=\"M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z\"/><line x1=\"6\" y1=\"16\" x2=\"6.01\" y2=\"16\"/><line x1=\"10\" y1=\"16\" x2=\"10.01\" y2=\"16\"/></svg></div>\n        <h3>Local Storage</h3>\n        <p>SD / eMMC buffering rides out network loss; data resumes to the cloud from the breakpoint once connectivity returns.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\n        <h3>Protective Enclosure</h3>\n        <p>IP65/IP67 housings rated −40 to 70 °C, with surge protection rated 8/20 µs · 20 kA against lightning.</p>\n      </div>\n    </div>\n    <div class=\"section-head reveal\" style=\"margin-top:56px;\">\n      <h2 style=\"font-size:24px;\">Field Deployment Checklist</h2>\n    </div>\n    <div class=\"reveal\" style=\"max-width:860px;\">\n      <ul class=\"feature-list\">\n        <li><span class=\"fi\">1</span><div><b>Size the solar power with a safety factor</b><p>Panel wattage ÷ site average daily sunshine × 0.5 safety factor must exceed the device's average daily consumption — a rule calibrated on rainy-season field data. Even a 10% shortfall can mean an outage after sustained overcast.</p></div></li>\n        <li><span class=\"fi\">2</span><div><b>APN configured at the factory</b><p>On site, only the SIM card is swapped — eliminating the most common cause of \"phantom\" 4G failures: a mistyped APN.</p></div></li>\n        <li><span class=\"fi\">3</span><div><b>Lightning grounding under 10 Ω</b><p>Earth resistance below 10 Ω, with the lightning rod at least 3 m from the device. Substandard grounding is the leading cause of strike damage.</p></div></li>\n        <li><span class=\"fi\">4</span><div><b>OTA upgrades proven in the lab first</b><p>Every remote firmware rollout is validated in the lab before being pushed to cold, remote or hard-to-reach stations.</p></div></li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ====== CLOUD-EDGE-DEVICE DATA CHAIN ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Data chain</div>\n      <h2>One Continuous Cloud-Edge-Device Chain</h2>\n      <p>From the sensor in the borehole to the chart on your control-room wall, every link is developed and maintained by SoilCreate — no black-box dependence, full data sovereignty.</p>\n    </div>\n    <div class=\"arch reveal\">\n      <div class=\"arch-layer\">\n        <div class=\"idx\">01 / SENSORS</div>\n        <h4>Field Sensors</h4>\n        <ul>\n          <li>MEMS high-precision sensing</li>\n          <li>RS485 bus / AutoID addressing</li>\n          <li>Vibrating-wire &amp; LoRa options</li>\n        </ul>\n      </div>\n      <div class=\"arch-layer\">\n        <div class=\"idx\">02 / GATEWAY</div>\n        <h4>Acquisition Gateway</h4>\n        <ul>\n          <li>SCDA-DG-01</li>\n          <li>Edge computing + filtering</li>\n          <li>Breakpoint-resume / event-triggered</li>\n        </ul>\n      </div>\n      <div class=\"arch-layer\">\n        <div class=\"idx\">03 / NETWORK</div>\n        <h4>Transmission</h4>\n        <ul>\n          <li>4G/5G/NB-IoT all-carrier</li>\n          <li>MQTT / TCP / HTTP</li>\n          <li>LoRa ad-hoc networking</li>\n        </ul>\n      </div>\n      <div class=\"arch-layer\">\n        <div class=\"idx\">04 / CLOUD</div>\n        <h4>Monitoring Cloud</h4>\n        <ul>\n          <li>Microservices architecture</li>\n          <li>GIS/BIM 3D visualization</li>\n          <li>Tiered warning / multi-project</li>\n        </ul>\n      </div>\n      <div class=\"arch-layer\">\n        <div class=\"idx\">05 / USERS</div>\n        <h4>PC / App / Video Wall</h4>\n        <ul>\n          <li>Web dashboards &amp; reports</li>\n          <li>Mobile app alert push</li>\n          <li>Control-room video wall</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"arch-banner reveal\">FULL-CHAIN IN-HOUSE R&amp;D&nbsp;&nbsp;|&nbsp;&nbsp;NO BLACK-BOX DEPENDENCE&nbsp;&nbsp;|&nbsp;&nbsp;FULL DATA SOVEREIGNTY</div>\n  </div>\n</section>\n\n<!-- ====== CLOUD PLATFORM ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">SoilCreate Monitoring Cloud</div>\n      <h2>Six Core Capabilities, One Platform</h2>\n      <p>Built on a microservices architecture, the SoilCreate Monitoring Cloud turns raw sensor streams into decisions — with full audit trails: every threshold change is version-logged and every alarm leaves a trigger record.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n        <h3>Real-Time Monitoring</h3>\n        <p>Second-level data refresh across all measurement points, with live curves, cloud maps and period statistics.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></div>\n        <h3>Intelligent Tiered Early Warning</h3>\n        <p>Configurable graded alert levels pushed by SMS and app, with version-logged thresholds and trigger logs for every alarm.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"1 6 9 2 15 6 23 2 23 18 15 22 9 18 1 22\"/><line x1=\"9\" y1=\"2\" x2=\"9\" y2=\"18\"/><line x1=\"15\" y1=\"6\" x2=\"15\" y2=\"22\"/></svg></div>\n        <h3>GIS/BIM 3D Visualization</h3>\n        <p>Measurement points placed on design drawings, GIS maps and BIM models — see the structure, not just the numbers.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/></svg></div>\n        <h3>Multi-Project Management</h3>\n        <p>Tiered role-based permissions let owner, contractor and supervisor accounts work on the same platform in parallel.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg></div>\n        <h3>Open REST API</h3>\n        <p>Standard RESTful + MQTT interfaces integrate with your existing GIS, BIM, OA and regulatory supervision platforms — no vendor lock-in.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4M5 5l2.5 2.5M16.5 16.5 19 19M19 5l-2.5 2.5M7.5 16.5 5 19\"/></svg></div>\n        <h3>AI Analytics Engine</h3>\n        <p>Neural-network models deliver trend forecasting and decision support on top of live monitoring data.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== PLATFORM ARCHITECTURE & ACCESS CONTROL ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">Architecture &amp; governance</div>\n      <h2>Three Layers, Clear Permission Boundaries</h2>\n      <p>The platform follows the standard three-layer IoT architecture: a device layer of sensors, an edge layer handling acquisition, protocol conversion, buffering and edge AI, and a cloud layer that splits into access (MQTT / HTTP / device shadow), data (time-series + relational + object storage), algorithm (rules + anomaly detection) and application (dashboards, mobile, government access, API) tiers.</p>\n    </div>\n    <div tabindex=\"0\" role=\"region\" aria-label=\"Scrollable technical table 1\" data-aria-en=\"Scrollable technical table 1\" data-aria-zh=\"可横向滚动的技术参数表 1\" class=\"table-wrap reveal\">\n      <table class=\"spec-table\">\n        <thead>\n          <tr>\n            <th scope=\"col\">Module</th>\n            <th scope=\"col\">Purpose</th>\n            <th scope=\"col\">Permission boundary</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>Control indicators (alarm thresholds)</td><td>Graded alarm threshold configuration</td><td class=\"hl\">Writable by owner + supervising engineer only; every change version-logged</td></tr>\n          <tr><td>Project overview / cloud map</td><td>Project info, progress, measurement points on design drawings</td><td>Readable by owner, contractor and supervision</td></tr>\n          <tr><td>Daily reports</td><td>Daily monitoring summaries</td><td>Writable by the supervising engineer</td></tr>\n          <tr><td>Data summary / comparison / period statistics</td><td>Multi-dimensional queries; contractor vs. third-party comparison flags deviations &gt;10% in red</td><td>Readable by all parties</td></tr>\n          <tr><td>Project management (staff)</td><td>Staff categories and accounts</td><td>Writable by the owner only</td></tr>\n          <tr><td>Automation management</td><td>Device status and remote upgrades</td><td>Writable by SoilCreate O&amp;M only</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"split\" style=\"margin-top:48px;\">\n      <div class=\"reveal\">\n        <h3 style=\"font-size:20px; margin-bottom:12px;\">Four Audit Trails, Traceable Reviews</h3>\n        <p style=\"color:var(--text-2);\">\n          Beyond the version-logged thresholds and alarm trigger records noted above, account changes leave approval records (applicant, approver, permissions before and after), and every API call leaves an audit log (caller, time, endpoint, parameters). Together these four audit trails make any post-event review traceable to a person and a timestamp.\n          \n        </p>\n      </div>\n      <div class=\"reveal\">\n        <h3 style=\"font-size:20px; margin-bottom:12px;\">API Access in Five Steps</h3>\n        <p style=\"color:var(--text-2);\">\n          Integration over standard RESTful API + MQTT follows a fixed flow: requirements → interface documentation from pre-sales → customer development → joint testing → go-live. The platform already interfaces with government regulatory platforms — meeting mandates such as Shanghai's 2024 rule that automated monitoring data be transmitted directly to the supervision platform.\n          \n        </p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== AI CAPABILITIES ====== -->\n<section class=\"section-alt\">\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">AI layer</div>\n      <h2>AI That Works on Engineering Data</h2>\n      <p>Three production AI capabilities sit on top of the cloud platform, turning monitoring data into early, defensible safety judgments.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"5\" cy=\"6\" r=\"2\"/><circle cx=\"5\" cy=\"18\" r=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/><circle cx=\"19\" cy=\"6\" r=\"2\"/><circle cx=\"19\" cy=\"18\" r=\"2\"/><path d=\"M6.7 7.2 10.3 10.8M6.7 16.8l3.6-3.6M13.7 10.8l3.6-3.6M13.7 13.2l3.6 3.6\"/></svg></div>\n        <h3>Neural-Network Safety Assessment</h3>\n        <p>Models trained on monitoring data assess structural safety state and forecast deformation trends before thresholds are reached.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 17c2-4 4-6 6-6s3 2 4 4 2 4 4 4 4-2 6-6\"/><path d=\"M2 9c2-4 4-6 6-6s3 2 4 4 2 4 4 4 4-2 6-6\" opacity=\".4\"/></svg></div>\n        <h3>Kalman / Sidereal-Day Filtering</h3>\n        <p>Advanced denoising for GNSS time series strips multipath and orbital noise to expose true millimeter-level displacement.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"card-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></div>\n        <h3>Machine-Vision Defect Recognition</h3>\n        <p>Computer-vision models recognize surface defects such as cracking, complementing sensor data with visual evidence.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ====== FAQ ====== -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-head reveal\">\n      <div class=\"eyebrow\">FAQ</div>\n      <h2>Frequently Asked Questions</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <details>\n        <summary>What happens to the data when the network drops?</summary>\n        <div class=\"faq-body\">Nothing is lost. The edge device buffers readings to local storage (16 GB on the SCDA-DG-01) and resumes the upload from the breakpoint the moment connectivity returns. If readings change rapidly during the outage, event-triggered reporting raises the sampling and reporting frequency automatically.</div>\n      </details>\n      <details>\n        <summary>Can our existing GIS / BIM / OA systems pull data from the platform?</summary>\n        <div class=\"faq-body\">Yes — over standard RESTful API + MQTT. The onboarding flow is: state the requirement, receive the interface documentation from pre-sales, develop the integration, run joint testing, then go live. Every API call leaves an audit log recording the caller, time, endpoint and parameters.</div>\n      </details>\n      <details>\n        <summary>Who is allowed to change alarm thresholds?</summary>\n        <div class=\"faq-body\">Only owner and supervising-engineer roles can write to the control-indicator module. Every change is version-logged with the value before, the value after, the person and the time — so a later review can always establish who changed what, and when.</div>\n      </details>\n      <details>\n        <summary>Can owner, contractor and supervisor all use the platform at once?</summary>\n        <div class=\"faq-body\">Yes. Multi-party accounts work in parallel under tiered role-based permissions: all parties read the project overview, cloud maps and data summaries, while write access is bounded per module — staff management for the owner, daily reports for the supervising engineer, device management for SoilCreate O&amp;M. Account changes leave approval records.</div>\n      </details>\n      <details>\n        <summary>A gateway drops offline right after commissioning. What is the usual cause?</summary>\n        <div class=\"faq-body\">The two most common causes are an APN configuration error and an unpaid SIM — check both by logging into the controller. SoilCreate devices ship with the APN pre-configured at the factory so only the SIM is swapped on site. Severe data latency usually points to weak 4G signal; switch to a LoRa or NB-IoT backup link.</div>\n      </details>\n      <details>\n        <summary>How is the field cabinet protected against lightning and power failure?</summary>\n        <div class=\"faq-body\">Grounding resistance is kept below 10 Ω with the lightning rod at least 3 m from the device, and the enclosure carries 8/20 µs · 20 kA surge protection. Solar systems are sized for 7 days of overcast plus a 30% reserve; on a low-voltage alarm, clean the panels and check the battery — batteries are replaced every 3 years.</div>\n      </details>\n    </div>\n  </div>\n</section>\n\n"
}
